function handleAppShortcutLaunch() {
    const params = new URLSearchParams(window.location.search);
    const action = params.get('action');
    if (!action) return;

    switch (action) {
        case 'new-tour':
            goToView('app');
            break;

        case 'plan-tour':
            goToView('tour');
            break;

        case 'map':
            goToView('map');
            break;

        case 'highlights':
            goToView('chart');
            // Nutzt den vorhandenen Tab-Button statt die interne
            // setStatsSection()-Funktion zu duplizieren.
            document
                .querySelector('#stats-section-switch [data-stats-section="highlights"]')
                ?.click();
            break;
    }

    // Query-Parameter entfernen, damit ein Reload/erneuter Fokus
    // nicht ungewollt wieder dieselbe Aktion auslöst.
    window.history.replaceState({}, '', window.location.pathname);
}

