function scrollBoxHeaderToTopMobile(header) {
    if (!header) return;
    if (window.innerWidth > 768) return;

    const box = header.closest('.box');
    const scrollContainer = header.closest('.view');

    if (!box || !scrollContainer) return;

    function getTargetTop() {
        const containerRect = scrollContainer.getBoundingClientRect();
        const boxRect = box.getBoundingClientRect();

        return scrollContainer.scrollTop + (boxRect.top - containerRect.top);
    }

    function scrollNow() {
        scrollContainer.scrollTo({
            top: Math.max(0, getTargetTop()),
            behavior: 'smooth'
        });
    }

    // Sofort
    scrollNow();

    // Während die Accordion-Höhe wächst, nochmal nachkorrigieren
    setTimeout(scrollNow, 180);
    setTimeout(scrollNow, 420);
    setTimeout(scrollNow, 700);
}


// ---------------- Accordion ----------------
document.querySelectorAll('.box-header').forEach(header => {
    header.addEventListener('click', () => {
        const box = header.parentElement;
        const content = box.querySelector('.box-content');
        const willOpen = !box.classList.contains('active');

        if (willOpen) {
            const scope = box.closest('.view') || document;
            scope.querySelectorAll('.box.active').forEach(otherBox => {
                if (otherBox === box) return;
                otherBox.classList.remove('active');
                const otherContent = otherBox.querySelector('.box-content');
                if (otherContent) otherContent.style.maxHeight = '0';
            });
        }

        box.classList.toggle('active');

        if (box.classList.contains('active')) {
            content.style.maxHeight = content.scrollHeight + "px";

            if (willOpen) {
                requestAnimationFrame(() => {
                    scrollBoxHeaderToTopMobile(header);
                });
            }
        } else {
            content.style.maxHeight = "0";
        }
    });
});

