/* =========================================================
   Einheitliche Dezimalformatierung
   ========================================================= */

function formatDecimalAT(value, decimals = 2) {

    if (
        value === null ||
        value === undefined ||
        value === ''
    ) {
        return '';
    }

    const number = Number(
        String(value)
            .trim()
            .replace(',', '.')
    );

    if (!Number.isFinite(number)) {
        return '';
    }

    return number
        .toFixed(decimals)
        .replace('.', ',');
}

