// ------------ Hilfsfunktion ------------

/**
 * Öffnet eine .box (falls noch zu) und führt danach eine Aktion aus (z.B. scrollen).
 * @param {HTMLElement} box - Die .box, die geöffnet werden soll
 * @param {Function} callback - Funktion, die nach dem Öffnen ausgeführt wird
 */
function openBoxIfNeeded(box, callback) {
    if (!box) {
        if (typeof callback === 'function') callback();
        return;
    }

    // Wenn die Box schon offen ist → sofort Callback
    if (box.classList.contains('active')) {
        // Layout einmal durchlaufen lassen
        requestAnimationFrame(() => {
            if (typeof callback === 'function') callback();
        });
        return;
    }

    const content = box.querySelector('.box-content');
    box.classList.add('active');

    if (content) {
        // Erst maxHeight setzen, dann nach dem Layout-Update scrollen
        content.style.maxHeight = content.scrollHeight + 'px';

        // Ein requestAnimationFrame reicht meist, zur Sicherheit kleine Verzögerung
        setTimeout(() => {
            if (typeof callback === 'function') callback();
        }, 800);
    } else {
        if (typeof callback === 'function') callback();
    }
}

