// ---------IndexedDB-Hilfsfunktion--------

const FILE_DB_NAME = 'tourtracker-file-db';
const FILE_DB_STORE = 'handles';
const FILE_DB_KEY = 'mainDataFileHandle';

function openFileHandleDb() {
    return new Promise((resolve, reject) => {
        const req = indexedDB.open(FILE_DB_NAME, 1);

        req.onupgradeneeded = () => {
            const db = req.result;
            if (!db.objectStoreNames.contains(FILE_DB_STORE)) {
                db.createObjectStore(FILE_DB_STORE);
            }
        };

        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error);
    });
}

async function persistLinkedFileHandle(handle) {
    const db = await openFileHandleDb();

    return new Promise((resolve, reject) => {
        const tx = db.transaction(FILE_DB_STORE, 'readwrite');
        const store = tx.objectStore(FILE_DB_STORE);

        store.put(handle, FILE_DB_KEY);

        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
        tx.onabort = () => reject(tx.error);
    });
}

async function loadPersistedFileHandle() {
    const db = await openFileHandleDb();

    return new Promise((resolve, reject) => {
        const tx = db.transaction(FILE_DB_STORE, 'readonly');
        const store = tx.objectStore(FILE_DB_STORE);
        const req = store.get(FILE_DB_KEY);

        req.onsuccess = () => resolve(req.result || null);
        req.onerror = () => reject(req.error);
    });
}

async function clearPersistedFileHandle() {
    const db = await openFileHandleDb();

    return new Promise((resolve, reject) => {
        const tx = db.transaction(FILE_DB_STORE, 'readwrite');
        const store = tx.objectStore(FILE_DB_STORE);

        store.delete(FILE_DB_KEY);

        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error);
        tx.onabort = () => reject(tx.error);
    });
}

async function ensureFilePermission(handle, write = false) {
    if (!handle) return false;

    const options = { mode: write ? 'readwrite' : 'read' };

    if ((await handle.queryPermission(options)) === 'granted') {
        return true;
    }

    if ((await handle.requestPermission(options)) === 'granted') {
        return true;
    }

    return false;
}

function parseZeitToHours(zeitStr) {
    if (!zeitStr) return null;

    const s = zeitStr.trim();

    // Format: 3:30 oder 03:30
    const colonMatch = s.match(/^(\d+):(\d{2})$/);
    if (colonMatch) {
        const h = parseInt(colonMatch[1], 10);
        const m = parseInt(colonMatch[2], 10);
        return h + m / 60;
    }

    // Format: 3h 30min oder 3h30min oder 3 h 30 min
    const hMinMatch = s.match(/(\d+)\s*h\s*(\d+)\s*min/i);
    if (hMinMatch) {
        const h = parseInt(hMinMatch[1], 10);
        const m = parseInt(hMinMatch[2], 10);
        return h + m / 60;
    }

    // Format: 3h oder 3 h
    const hOnlyMatch = s.match(/^(\d+(?:[.,]\d+)?)\s*h$/i);
    if (hOnlyMatch) {
        return parseFloat(hOnlyMatch[1].replace(',', '.'));
    }

    // Format: 90min oder 90 min
    const minOnlyMatch = s.match(/^(\d+)\s*min$/i);
    if (minOnlyMatch) {
        return parseInt(minOnlyMatch[1], 10) / 60;
    }

    // Format: reine Zahl → als Stunden interpretieren
    const numMatch = s.match(/^(\d+(?:[.,]\d+)?)$/);
    if (numMatch) {
        return parseFloat(numMatch[1].replace(',', '.'));
    }

    return null;
}

function parseFerrataNumber(value) {
    const number = parseFloat(
        String(value ?? '').replace(',', '.')
    );

    return Number.isFinite(number) ? number : 0;
}

function parseFerrataTimeToMinutes(value) {
    if (!value || !String(value).includes(':')) return 0;

    const [hours, minutes] = String(value).split(':').map(Number);

    if (!Number.isFinite(hours) || !Number.isFinite(minutes)) {
        return 0;
    }

    return Math.max(0, hours * 60 + minutes);
}

function getFerrataValues(entry) {
    const difficulty = String(entry?.difficulty || '')
        .trim()
        .toLowerCase();

    /*
     * Reine Klettersteig-Tour:
     * Die gesamte Tour zählt als Klettersteig.
     */
    if (difficulty === 'klettersteig') {
        return {
            distance: parseFerrataNumber(entry.strecke),
            ascent: parseFerrataNumber(entry.aufstieg),
            minutes: parseFerrataTimeToMinutes(entry.zeit)
        };
    }

    /*
     * Hike & Climb:
     * Nur die separat eingegebenen Teilwerte zählen.
     */
    if (difficulty === 'hike & climb') {
        return {
            distance: parseFerrataNumber(entry.ferrataStrecke),
            ascent: parseFerrataNumber(entry.ferrataHm),
            minutes: parseFerrataTimeToMinutes(entry.ferrataZeit)
        };
    }

    /*
     * Wandern und Mehrtägig:
     * Keine Klettersteigwerte.
     */
    return {
        distance: 0,
        ascent: 0,
        minutes: 0
    };
}

function formatFerrataMinutes(totalMinutes) {
    const minutes = Math.max(0, Math.round(totalMinutes || 0));
    const hours = Math.floor(minutes / 60);
    const restMinutes = minutes % 60;

    return `${hours}:${String(restMinutes).padStart(2, '0')}`;
}

function getBikeValues(entry) {
    const difficulty = String(entry?.difficulty || '')
        .trim()
        .toLowerCase();

    if (
        difficulty !== 'bike & hike' &&
        difficulty !== 'radtour'
    ) {
        return {
            distance: 0,
            ascent: 0,
            minutes: 0
        };
    }

    return {
        distance: parseFerrataNumber(entry.bikeStrecke),
        ascent: parseFerrataNumber(entry.bikeHm),
        minutes: parseFerrataTimeToMinutes(entry.bikeZeit)
    };
}

/* =========================================================
   Persönlicher Leistungsindex
   ========================================================= */

function getPerformanceGroup(entry) {

    const difficulty =
        String(entry?.difficulty || '')
            .trim()
            .toLowerCase();

    /*
     * Nur reine Radtouren werden
     * separat verglichen.
     */
    if (difficulty === 'radtour') {
        return 'cycling';
    }

    /*
     * Alles andere gehört für den
     * Leistungsindex zur Wandergruppe:
     *
     * - Wandern
     * - Mehrtägig
     * - Klettersteig
     * - Hike & Climb
     * - Bike & Hike
     */
    return 'hiking';
}


function getPerformanceValues(entry) {

    if (!entry) return null;


    const difficulty =
        String(entry.difficulty || '')
            .trim()
            .toLowerCase();


    function numberValue(value) {

        const number =
            parseFloat(
                String(value ?? '')
                    .replace(',', '.')
            );

        return Number.isFinite(number)
            ? number
            : 0;
    }


    /*
     * Standard:
     *
     * Für sämtliche Touren außer reinen
     * Radtouren werden ausschließlich die
     * normalen Hauptwerte verwendet.
     *
     * Das gilt auch für:
     *
     * - Klettersteig
     * - Hike & Climb
     * - Bike & Hike
     *
     * Bei Hike & Climb enthalten diese Werte
     * bereits die Gesamtleistung der Tour.
     *
     * Bei Bike & Hike enthalten diese Werte
     * ebenfalls die Gesamtwerte der Tour; die separaten
     * bike...-Felder beschreiben nur den darin enthaltenen Radanteil.
     */
    let distance =
        numberValue(entry.strecke);

    let ascent =
        numberValue(entry.aufstieg);

    let hours =
        parseZeitToHours(entry.zeit) || 0;


    /*
     * Einzige Ausnahme:
     *
     * Reine Radtouren verwenden ausschließlich
     * die Radwerte.
     */
    if (difficulty === 'radtour') {

        const bike =
            getBikeValues(entry);

        distance =
            bike.distance;

        ascent =
            bike.ascent;

        hours =
            bike.minutes / 60;
    }


    /*
     * Geschwindigkeit über die jeweils
     * berücksichtigte Gesamtstrecke/-zeit.
     */
    const speed =
        distance > 0 &&
        hours > 0
            ? distance / hours
            : 0;


    /*
     * Dieselbe Rundtour-Logik wie bisher.
     */
    const adjustedDistance =
        entry.useFullDistanceForGradient
            ? distance
            : distance / 2;


    const adjustedHours =
        entry.useFullDistanceForGradient
            ? hours
            : hours / 2;


    /*
     * Steigung in hm/km.
     */
    const gradient =
        ascent > 0 &&
        adjustedDistance > 0
            ? ascent /
              adjustedDistance
            : 0;


    /*
     * Anstieg in hm/h.
     */
    const ascentRate =
        ascent > 0 &&
        adjustedHours > 0
            ? ascent /
              adjustedHours
            : 0;

/*
 * Dauerleistung:
 *
 * Bewertet, wie lange Geschwindigkeit
 * bzw. vertikale Leistung gehalten wurden.
 *
 * sqrt() sorgt bewusst für einen
 * abnehmenden Zeitbonus.
 */
/*
 * Dauerleistung mit leicht höherer
 * Gewichtung für Klettersteigzeit.
 *
 * 1 h Klettersteig entspricht hier
 * 1,25 h Wandern.
 */
const FERRATA_ENDURANCE_FACTOR = 1.25;


let ferrataHours = 0;


/*
 * Reiner Klettersteig:
 * gesamte Tourzeit ist Klettersteigzeit.
 */
if (difficulty === 'klettersteig') {

    ferrataHours =
        hours;


/*
 * Hike & Climb:
 * nur separat gespeicherte
 * Klettersteigzeit berücksichtigen.
 */
} else if (
    difficulty === 'hike & climb'
) {

    const ferrata =
        getFerrataValues(entry);

    ferrataHours =
        ferrata.minutes / 60;
}


/*
 * Sicherheit:
 * Klettersteigzeit kann niemals
 * länger als die gesamte Tourzeit sein.
 */
ferrataHours =
    Math.max(
        0,
        Math.min(
            ferrataHours,
            hours
        )
    );


/*
 * Effektive Gesamtdauer:
 *
 * Wanderzeit zählt normal,
 * Klettersteigzeit erhält 25 % Bonus.
 */
const enduranceHours =
    hours +
    ferrataHours *
    (
        FERRATA_ENDURANCE_FACTOR - 1
    );


/*
 * Für die vertikale Dauerleistung darf
 * nur der Teil berücksichtigt werden,
 * der innerhalb der verwendeten
 * Aufstiegszeit liegt.
 *
 * Rundtour:
 * adjustedHours = halbe Zeit
 *
 * volle Strecke:
 * adjustedHours = volle Zeit
 */
/*
 * Klettersteigzeit für die vertikale
 * Dauerleistung:
 *
 * Hike & Climb:
 * Klettersteiganteil immer vollständig
 * berücksichtigen.
 *
 * Reiner Klettersteig:
 * bestehende Rundtour-Logik beibehalten.
 */
const ferrataAscentHours =
    difficulty === 'hike & climb'
        ? ferrataHours
        : Math.min(
            ferrataHours,
            adjustedHours
        );


const enduranceAscentHours =
    adjustedHours +
    ferrataAscentHours *
    (
        FERRATA_ENDURANCE_FACTOR - 1
    );


const sustainedSpeed =
    speed > 0 &&
    enduranceHours > 0
        ? speed *
          Math.sqrt(
              enduranceHours
          )
        : 0;


const sustainedAscent =
    ascentRate > 0 &&
    enduranceAscentHours > 0
        ? ascentRate *
          Math.sqrt(
              enduranceAscentHours
          )
        : 0;

    return {
    distance,
    ascent,
    hours,

    adjustedHours,

    speed,
    gradient,
    ascentRate,

    sustainedSpeed,
    sustainedAscent
};
}


// Die Vergleichsvektoren in den Leistungsindex-Kontexten ändern sich
// nicht, solange der Kontext gültig ist. Deshalb können ihre sortierten
// Kopien wiederverwendet werden, anstatt pro Tour erneut zu sortieren.
const performancePercentileValuesCache = new WeakMap();

function getPerformancePercentile(
    value,
    values
) {
    let validValues = performancePercentileValuesCache.get(values);

    if (!validValues) {
        validValues = values
            .filter(Number.isFinite)
            .sort((a, b) => a - b);

        performancePercentileValuesCache.set(values, validValues);
    }

    const count = validValues.length;

    if (
        !Number.isFinite(value) ||
        count === 0
    ) {
        return 0;
    }

    /*
     * Nur eine Vergleichstour:
     * neutraler Mittelwert.
     */
    if (count === 1) {
        return 50;
    }

    const EPSILON = 0.000000001;
    const lowerThreshold = value - EPSILON;
    const upperThreshold = value + EPSILON;

    // Binäre Suche: erster Wert >= unterer Grenzwert.
    let low = 0;
    let high = count;

    while (low < high) {
        const middle = (low + high) >>> 1;
        if (validValues[middle] < lowerThreshold) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }

    const lowerCount = low;

    // Binäre Suche: erster Wert > oberer Grenzwert.
    low = lowerCount;
    high = count;

    while (low < high) {
        const middle = (low + high) >>> 1;
        if (validValues[middle] <= upperThreshold) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }

    const equalCount = low - lowerCount;

    /*
     * Bei identischen Werten wird weiterhin der
     * gemeinsame mittlere Rang verwendet.
     * Binäre Suche ersetzt nur wiederholte lineare Filter.
     */
    const position =
        lowerCount +
        Math.max(
            0,
            equalCount - 1
        ) / 2;

    const percentile =
        (
            position /
            (count - 1)
        ) * 100;

    return Math.max(
        0,
        Math.min(
            100,
            percentile
        )
    );
}

/* =========================================================
   Leistungsindex – Performance-Cache
   ========================================================= */

/*
 * Vergleichsbasis pro Leistungsgruppe.
 *
 * Die Tourhistorie ist für alle Berechnungen
 * dieselbe. Deshalb muss sie nicht für jede
 * einzelne Tour erneut komplett aufgebaut werden.
 */
const performanceIndexContextCache =
    new Map();


/*
 * Fertige Ergebnisse einzelner Touren.
 *
 * WeakMap ist hier ideal:
 * Die Tour selbst ist der Schlüssel.
 */
let performanceIndexResultCache =
    new WeakMap();


/*
 * Wird aufgerufen, sobald sich die
 * gespeicherten Tourdaten verändern.
 */
function invalidatePerformanceIndexCache() {

    performanceIndexContextCache.clear();

    performanceIndexResultCache =
        new WeakMap();
}


/*
 * Vergleichsdaten einer Leistungsgruppe
 * genau einmal aufbauen.
 */
function getPerformanceComparisonContext(
    targetGroup
) {

    if (
        performanceIndexContextCache.has(
            targetGroup
        )
    ) {

        return (
            performanceIndexContextCache.get(
                targetGroup
            )
        );
    }


    const allTours =
        appStorage.get('touren') || [];


    const comparisonTours =
        allTours
            .filter(
                tour =>
                    getPerformanceGroup(tour) ===
                    targetGroup
            )
            .map(
                tour => ({

                    entry:
                        tour,

                    values:
                        getPerformanceValues(
                            tour
                        )
                })
            )
            .filter(
                item =>
                    item.values &&
                    item.values.distance > 0 &&
                    item.values.hours > 0
            );


    /*
     * Wertearrays nur einmal erzeugen.
     */
    const distanceValues =
        comparisonTours.map(
            item =>
                item.values.distance
        );


    const ascentValues =
        comparisonTours.map(
            item =>
                item.values.ascent
        );


    const speedValues =
        comparisonTours.map(
            item =>
                item.values.speed
        );


    const ascentRateValues =
        comparisonTours.map(
            item =>
                item.values.ascentRate
        );


    const gradientValues =
        comparisonTours.map(
            item =>
                item.values.gradient
        );


    const sustainedSpeedValues =
        comparisonTours.map(
            item =>
                item.values.sustainedSpeed
        );


    const sustainedAscentValues =
        comparisonTours.map(
            item =>
                item.values.sustainedAscent
        );


    /*
     * Auch die fertigen Vergleichsscores
     * müssen nur einmal pro Gruppe
     * berechnet werden.
     *
     * Die Mathematik ist exakt dieselbe
     * wie bisher.
     */
    const comparisonScores =
        comparisonTours.map(
            item => {

                const values =
                    item.values;


                const distP =
                    getPerformancePercentile(
                        values.distance,
                        distanceValues
                    );


                const ascentP =
                    getPerformancePercentile(
                        values.ascent,
                        ascentValues
                    );


                const speedP =
                    getPerformancePercentile(
                        values.speed,
                        speedValues
                    );


                const ascentRateP =
                    getPerformancePercentile(
                        values.ascentRate,
                        ascentRateValues
                    );


                const gradientP =
                    getPerformancePercentile(
                        values.gradient,
                        gradientValues
                    );


                const sustainedSpeedP =
                    getPerformancePercentile(
                        values.sustainedSpeed,
                        sustainedSpeedValues
                    );


                const sustainedAscentP =
                    getPerformancePercentile(
                        values.sustainedAscent,
                        sustainedAscentValues
                    );


                const enduranceP =
                    (
                        sustainedSpeedP +
                        sustainedAscentP
                    ) / 2;


                return (
                    distP * 0.25 +
                    ascentP * 0.25 +
                    speedP * 0.15 +
                    ascentRateP * 0.15 +
                    gradientP * 0.10 +
                    enduranceP * 0.10
                );
            }
        );


    const context = {

        comparisonTours,

        distanceValues,
        ascentValues,
        speedValues,
        ascentRateValues,
        gradientValues,

        sustainedSpeedValues,
        sustainedAscentValues,

        comparisonScores
    };


    performanceIndexContextCache.set(
        targetGroup,
        context
    );


    return context;
}



/* =========================================================
   Leistungsindex einer einzelnen Tour
   ========================================================= */

function calculatePerformanceIndex(entry) {

    if (!entry) {
        return null;
    }


    /*
     * Falls diese konkrete Tour bereits
     * berechnet wurde, fertiges Ergebnis
     * sofort zurückgeben.
     */
    if (
        typeof entry === 'object' &&
        performanceIndexResultCache.has(
            entry
        )
    ) {

        return (
            performanceIndexResultCache.get(
                entry
            )
        );
    }


    const targetGroup =
        getPerformanceGroup(
            entry
        );


    const targetValues =
        getPerformanceValues(
            entry
        );


    /*
     * Strecke und Zeit bleiben
     * Mindestvoraussetzungen.
     */
    if (
        !targetValues ||
        targetValues.distance <= 0 ||
        targetValues.hours <= 0
    ) {

        return null;
    }


    const context =
        getPerformanceComparisonContext(
            targetGroup
        );


    if (
        context.comparisonTours.length ===
        0
    ) {

        return null;
    }


    const distancePercentile =
        getPerformancePercentile(
            targetValues.distance,
            context.distanceValues
        );


    const ascentPercentile =
        getPerformancePercentile(
            targetValues.ascent,
            context.ascentValues
        );


    const speedPercentile =
        getPerformancePercentile(
            targetValues.speed,
            context.speedValues
        );


    const ascentRatePercentile =
        getPerformancePercentile(
            targetValues.ascentRate,
            context.ascentRateValues
        );


    const gradientPercentile =
        getPerformancePercentile(
            targetValues.gradient,
            context.gradientValues
        );


    const sustainedSpeedPercentile =
        getPerformancePercentile(
            targetValues.sustainedSpeed,
            context.sustainedSpeedValues
        );


    const sustainedAscentPercentile =
        getPerformancePercentile(
            targetValues.sustainedAscent,
            context.sustainedAscentValues
        );


    /*
     * Dauerleistung:
     * unverändert 50 % Speed /
     * 50 % vertikale Leistung.
     */
    const endurancePercentile =
        (
            sustainedSpeedPercentile +
            sustainedAscentPercentile
        ) / 2;


    /*
     * Gewichtung bleibt exakt
     * wie bisher:
     *
     * 25 % Strecke
     * 25 % Aufstieg
     * 15 % Geschwindigkeit
     * 15 % Anstieg
     * 10 % Steigung
     * 10 % Dauerleistung
     */
    const rawScore =
        distancePercentile * 0.25 +
        ascentPercentile * 0.25 +
        speedPercentile * 0.15 +
        ascentRatePercentile * 0.15 +
        gradientPercentile * 0.10 +
        endurancePercentile * 0.10;


    const score =
        Math.round(
            rawScore
        );


    /*
     * Auch der Gesamtvergleich bleibt
     * mathematisch unverändert.
     */
    const overallPercentile =
        Math.round(
            getPerformancePercentile(
                rawScore,
                context.comparisonScores
            )
        );


    const groupLabels = {

        hiking:
            'Wandern',

        cycling:
            'Radtour'
    };


    const result = {

        score,

        overallPercentile,

        group:
            targetGroup,

        groupLabel:
            groupLabels[targetGroup] ||
            'Touren',

        comparisonCount:
            context
                .comparisonTours
                .length,

        distancePercentile,

        ascentPercentile,

        speedPercentile,

        ascentRatePercentile,

        gradientPercentile,

        endurancePercentile,

        values:
            targetValues
    };


    /*
     * Ergebnis für weitere Anzeigen
     * dieser Tour merken.
     */
    if (
        typeof entry === 'object'
    ) {

        performanceIndexResultCache.set(
            entry,
            result
        );
    }


    return result;
}

/* =========================================================
   Haptisches Feedback
   ========================================================= */

function hapticFeedback(duration = 12) {

    if (!('vibrate' in navigator)) {
        return;
    }

    navigator.vibrate(duration);
}


/* Texte und Zahlen */
document.addEventListener('input', (e) => {

    const input = e.target;

    if (!(input instanceof HTMLInputElement) &&
        !(input instanceof HTMLTextAreaElement)) {
        return;
    }

    const allowedTypes = [
        'text',
        'number',
        'search',
        'tel',
        'email'
    ];

    if (
        input instanceof HTMLInputElement &&
        !allowedTypes.includes(input.type)
    ) {
        return;
    }

    hapticFeedback(8);
});


/* Dashboard- und Diagramm-Kacheln */
document.addEventListener('click', (e) => {

    const tile = e.target.closest(
        '.dash-stat-tile, .chart-stat-tile'
    );

    if (!tile) return;

    hapticFeedback(15);
});

// ─── Schrittberechnung ────────────────────────────────────────────────

const STEP_LENGTH_METERS = 0.60;
const FERRATA_STEP_LENGTH_METERS = 0.40;
const FERRATA_VERTICAL_STEP_METERS = 0.20;
const STEP_REFERENCE_SPEED_KMH = 5.0;

function getStepSpeedFactor(speedKmh) {
    if (!Number.isFinite(speedKmh) || speedKmh <= 0) {
        return 1;
    }

    /*
     * Referenz: 5 km/h
     *
     * Langsamere Geschwindigkeit:
     * etwas mehr Schritte.
     *
     * Höhere Geschwindigkeit:
     * etwas weniger Schritte.
     */
    const factor =
        1 + (STEP_REFERENCE_SPEED_KMH - speedKmh) * 0.03;

    return Math.max(0.90, Math.min(1.15, factor));
}

function getStepGradientFactor(gradientHmPerKm) {
    if (!Number.isFinite(gradientHmPerKm) ||
        gradientHmPerKm <= 0) {
        return 1;
    }

    /*
     * Der Aufstieg wirkt über die Steigung.
     * Die Werte bleiben bewusst begrenzt,
     * damit die Schrittzahl nicht unrealistisch anwächst.
     */
    if (gradientHmPerKm <= 50)  return 1.00;
    if (gradientHmPerKm <= 100) return 1.04;
    if (gradientHmPerKm <= 150) return 1.08;
    if (gradientHmPerKm <= 250) return 1.15;

    return 1.25;
}

function getStepEffectiveDistance(distanceKm, useFullDistance) {
    if (!Number.isFinite(distanceKm) || distanceKm <= 0) {
        return 0;
    }

    /*
     * Bestehende Logik der App:
     *
     * true  = Steigung auf ganzer Strecke
     * false = Steigung auf halber Strecke
     */
    return useFullDistance
        ? distanceKm
        : distanceKm / 2;
}

function calculateNormalActivitySteps({
    distanceKm,
    ascentHm,
    timeMinutes,
    useFullDistanceForGradient
}) {
    if (!Number.isFinite(distanceKm) || distanceKm <= 0) {
        return 0;
    }

    const distanceMeters = distanceKm * 1000;

    // Schrittzahl in der Ebene
    const baseSteps =
        distanceMeters / STEP_LENGTH_METERS;

    const effectiveDistanceKm =
        getStepEffectiveDistance(
            distanceKm,
            useFullDistanceForGradient
        );

    const gradientHmPerKm =
        effectiveDistanceKm > 0
            ? ascentHm / effectiveDistanceKm
            : 0;

    const gradientFactor =
        getStepGradientFactor(gradientHmPerKm);

    const speedKmh =
        timeMinutes > 0
            ? distanceKm / (timeMinutes / 60)
            : 0;

    const speedFactor =
        getStepSpeedFactor(speedKmh);

    return Math.round(
        baseSteps *
        gradientFactor *
        speedFactor
    );
}

function calculateFerrataSteps({
    distanceKm,
    ascentHm,
    timeMinutes,
    useFullDistanceForGradient
}) {
    if (
        (!Number.isFinite(distanceKm) || distanceKm <= 0) &&
        (!Number.isFinite(ascentHm) || ascentHm <= 0)
    ) {
        return 0;
    }

    const safeDistanceKm =
        Number.isFinite(distanceKm) && distanceKm > 0
            ? distanceKm
            : 0;

    const safeAscentHm =
        Number.isFinite(ascentHm) && ascentHm > 0
            ? ascentHm
            : 0;

    /*
     * Klettersteig:
     *
     * horizontale Strecke mit 40-cm-Schrittlänge
     * plus vertikale Schritte mit 20-cm-Tritthöhe
     */
    const horizontalSteps =
        safeDistanceKm > 0
            ? (safeDistanceKm * 1000) /
              FERRATA_STEP_LENGTH_METERS
            : 0;

    const verticalSteps =
    safeAscentHm > 0
        ? safeAscentHm / FERRATA_VERTICAL_STEP_METERS
        : 0;

    /*
     * Für die Steigungsberechnung gilt ebenfalls
     * die Einstellung "ganze Strecke" bzw. "halbe Strecke".
     */
    const effectiveDistanceKm =
        getStepEffectiveDistance(
            safeDistanceKm,
            useFullDistanceForGradient
        );

    const gradientHmPerKm =
        effectiveDistanceKm > 0
            ? safeAscentHm / effectiveDistanceKm
            : 0;

    const gradientFactor =
        getStepGradientFactor(gradientHmPerKm);

    const speedKmh =
        safeDistanceKm > 0 && timeMinutes > 0
            ? safeDistanceKm / (timeMinutes / 60)
            : 0;

    const speedFactor =
        getStepSpeedFactor(speedKmh);

    /*
     * Der vertikale Anteil wird vollständig berücksichtigt.
     * Der zusätzliche Steigungsfaktor ist bewusst begrenzt.
     */
    return Math.round(
        (
            horizontalSteps +
            verticalSteps
        ) *
        gradientFactor *
        speedFactor
    );
}

function calculateEntrySteps(entry) {
    const difficulty = String(entry?.difficulty || '')
        .trim()
        .toLowerCase();

    /* Reine Radtouren liefern ausdrücklich keine Schritte. */
    if (difficulty === 'radtour') {
        return 0;
    }

    const totalDistance = parseFerrataNumber(entry.strecke);
    const totalAscent = parseFerrataNumber(entry.aufstieg);
    const totalMinutes = parseFerrataTimeToMinutes(entry.zeit);
    const useFullDistanceForGradient = Boolean(entry.useFullDistanceForGradient);

    /*
     * Die Hauptwerte Strecke/Aufstieg/Zeit sind Gesamtwerte.
     * Bei gemischten Touren wird daher der separat gespeicherte
     * Bike-/Klettersteiganteil abgezogen, bevor Wanderschritte
     * berechnet werden. Teilwerte werden niemals zusätzlich auf
     * die Gesamtwerte aufgeschlagen.
     */
    if (difficulty === 'hike & climb') {
        const ferrata = getFerrataValues(entry);

        const hikingDistance = Math.max(0, totalDistance - ferrata.distance);
        const hikingAscent = Math.max(0, totalAscent - ferrata.ascent);
        const hikingMinutes = Math.max(0, totalMinutes - ferrata.minutes);

        return (
            calculateNormalActivitySteps({
                distanceKm: hikingDistance,
                ascentHm: hikingAscent,
                timeMinutes: hikingMinutes,
                useFullDistanceForGradient
            }) +
            calculateFerrataSteps({
                distanceKm: ferrata.distance,
                ascentHm: ferrata.ascent,
                timeMinutes: ferrata.minutes,
                useFullDistanceForGradient
            })
        );
    }

    if (difficulty === 'bike & hike') {
        const bike = getBikeValues(entry);

        return calculateNormalActivitySteps({
            distanceKm: Math.max(0, totalDistance - bike.distance),
            ascentHm: Math.max(0, totalAscent - bike.ascent),
            timeMinutes: Math.max(0, totalMinutes - bike.minutes),
            useFullDistanceForGradient
        });
    }

    if (difficulty === 'klettersteig') {
        return calculateFerrataSteps({
            distanceKm: totalDistance,
            ascentHm: totalAscent,
            timeMinutes: totalMinutes,
            useFullDistanceForGradient
        });
    }

    return calculateNormalActivitySteps({
        distanceKm: totalDistance,
        ascentHm: totalAscent,
        timeMinutes: totalMinutes,
        useFullDistanceForGradient
    });
}

// ─── Mobile Custom Select ────────────────────────────────────────────────────

let mobSelBackdrop = null;

function mobSelEnsureBackdrop() {
    if (mobSelBackdrop) return;
    mobSelBackdrop = document.createElement('div');
    mobSelBackdrop.className = 'mob-sel-backdrop';
    mobSelBackdrop.innerHTML = `
        <div class="mob-sel-sheet">
            <div class="mob-sel-hdr">
                <span class="mob-sel-title"></span>
                <button class="mob-sel-close" aria-label="Schließen">✕</button>
            </div>
            <ul class="mob-sel-list"></ul>
        </div>`;
    document.body.appendChild(mobSelBackdrop);

    mobSelBackdrop.addEventListener('click', e => {
        if (e.target === mobSelBackdrop) mobSelClose();
    });
    mobSelBackdrop.querySelector('.mob-sel-close').addEventListener('click', mobSelClose);

    attachMobSelSwipeDown();
}

function mobSelOpen(native) {
    mobSelEnsureBackdrop();

    // Titel aus Label
    const label = native.id
        ? document.querySelector(`label[for="${native.id}"]`)
        : null;
    mobSelBackdrop.querySelector('.mob-sel-title').textContent =
        label ? label.textContent.replace(':', '').trim() : '';

    // Optionen aufbauen
    const list = mobSelBackdrop.querySelector('.mob-sel-list');
    list.innerHTML = '';
    Array.from(native.options).forEach(opt => {
        const li = document.createElement('li');
        li.className = 'mob-sel-opt' + (opt.value === native.value ? ' selected' : '');
        li.textContent = opt.text;
        li.addEventListener('click', () => {
            native.value = opt.value;
            native.dispatchEvent(new Event('change', { bubbles: true }));
            mobSelSyncDisplay(native);
            mobSelClose();
        });
        list.appendChild(li);
    });

    mobSelBackdrop.classList.add('open');
}

function mobSelClose() {
    mobSelBackdrop?.classList.remove('open');
}

function animateMobSelClose() {
    if (!mobSelBackdrop) return;
    const sheet = mobSelBackdrop.querySelector('.mob-sel-sheet');
    if (!sheet) { mobSelClose(); return; }

    sheet.classList.remove('is-dragging');

    const targetY = sheet.getBoundingClientRect().height + 40;

    requestAnimationFrame(() => {
        sheet.style.transform = `translateY(${targetY}px)`;
    });

    setTimeout(() => {
        mobSelBackdrop.classList.remove('open');
        sheet.style.transform = '';
    }, 300);
}

function attachMobSelSwipeDown() {
    if (!mobSelBackdrop || mobSelBackdrop.dataset.swipeInit === '1') return;
    mobSelBackdrop.dataset.swipeInit = '1';

    const sheet = mobSelBackdrop.querySelector('.mob-sel-sheet');
    const list  = mobSelBackdrop.querySelector('.mob-sel-list');
    if (!sheet) return;

    let tracking = false, swipeMode = false;
    let startY = 0, startX = 0, currentY = 0;
    let lastY = 0, lastT = 0, velocity = 0;

    const CLOSE_THR = 90;
    const VEL_THR   = 0.5;
    const FLICK_MIN = 25;
    const MAX_DRAG  = 280;
    const DIR_LOCK  = 8;

    function resetState() {
        tracking = swipeMode = false;
        startY = startX = currentY = lastY = velocity = 0;
        sheet.classList.remove('is-dragging');
        sheet.style.transform = '';
    }

    sheet.addEventListener('touchstart', (e) => {
        if (!mobSelBackdrop.classList.contains('open')) return;
        if (e.target.closest('button')) return;
        if (list && list.scrollTop > 2 && e.target.closest('.mob-sel-list')) return;

        const t = e.touches[0];
        tracking = true;
        swipeMode = false;
        startY = currentY = lastY = t.clientY;
        startX = t.clientX;
        lastT = performance.now();
        velocity = 0;
    }, { passive: true });

    sheet.addEventListener('touchmove', (e) => {
        if (!tracking) return;

        const t = e.touches[0];
        const now = performance.now();
        const dt = now - lastT;
        if (dt > 0 && dt < 100) velocity = (t.clientY - lastY) / dt;
        lastY = t.clientY;
        lastT = now;

        const dy = t.clientY - startY;
        const dx = t.clientX - startX;

        if (!swipeMode) {
            if (Math.abs(dy) < DIR_LOCK && Math.abs(dx) < DIR_LOCK) return;
            if (Math.abs(dx) >= Math.abs(dy)) { tracking = false; return; }
            if (dy < 0) { tracking = false; return; }
            swipeMode = true;
        }

        e.preventDefault();
        if (dy <= 0) return;

        const clamped = dy > MAX_DRAG ? MAX_DRAG + (dy - MAX_DRAG) * 0.18 : dy;
        currentY = t.clientY;
        sheet.classList.add('is-dragging');
        sheet.style.transform = `translateY(${clamped.toFixed(1)}px)`;
    }, { passive: false });

    function handleEnd() {
        if (!tracking) return;
        const dy = currentY - startY;

        if (swipeMode && (dy > CLOSE_THR || (dy > FLICK_MIN && velocity > VEL_THR))) {
            tracking = swipeMode = false;
            animateMobSelClose();
            return;
        }
        resetState();
    }

    sheet.addEventListener('touchend',    handleEnd,  { passive: true });
    sheet.addEventListener('touchcancel', resetState, { passive: true });
}

function mobSelSyncDisplay(native) {
    const wrapper = native.closest('.mob-sel-wrap');
    if (!wrapper) return;
    const disp = wrapper.querySelector('.mob-sel-disp');
    if (disp) disp.textContent = native.options[native.selectedIndex]?.text || '';
}

function mobSelWrap(native) {
    if (native.dataset.mobSel || native.closest('.mob-sel-wrap')) return;
    native.dataset.mobSel = '1';

    const wrapper = document.createElement('div');
    wrapper.className = 'mob-sel-wrap';

    const btn = document.createElement('div');
    btn.className = 'mob-sel-btn';
    btn.setAttribute('tabindex', '0');

    const disp = document.createElement('span');
    disp.className = 'mob-sel-disp';
    disp.textContent = native.options[native.selectedIndex]?.text || '';

    btn.appendChild(disp);
    btn.insertAdjacentHTML('beforeend',
        `<svg class="mob-sel-arr" width="11" height="7" viewBox="0 0 11 7">
            <path d="M1 1l4.5 4.5L10 1" stroke="currentColor"
                  stroke-width="1.8" fill="none" stroke-linecap="round"/>
        </svg>`
    );

    native.parentNode.insertBefore(wrapper, native);
    wrapper.appendChild(btn);
    native.classList.add('mob-sel-hidden');
    wrapper.appendChild(native);

    btn.addEventListener('click', () => mobSelOpen(native));
    btn.addEventListener('keydown', e => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); mobSelOpen(native); }
    });

    // Value-Setter überschreiben für programmatische Änderungen
    try {
        const desc = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value');
        Object.defineProperty(native, 'value', {
            get() { return desc.get.call(this); },
            set(v) { desc.set.call(this, v); mobSelSyncDisplay(this); },
            configurable: true
        });
    } catch (_) {}

    native.addEventListener('change', () => mobSelSyncDisplay(native));
}

function initMobileCustomSelects() {
    if (!isMobileLayout()) return;
    document.querySelectorAll('select').forEach(mobSelWrap);

    // Neue Selects (dynamisch erzeugte) automatisch einwickeln
    new MutationObserver(mutations => {
        if (!isMobileLayout()) return;
        mutations.forEach(m => {
            m.addedNodes.forEach(node => {
                if (node.nodeType !== 1) return;
                if (node.tagName === 'SELECT') mobSelWrap(node);
                node.querySelectorAll?.('select').forEach(mobSelWrap);
            });
        });
    }).observe(document.body, { childList: true, subtree: true });
}

function initHeaderScrollShadow(){
    const header = document.querySelector('.accordion-header');
    if (!header) return;

    const check = (scrollTop) => {
        header.classList.toggle('header-scrolled', scrollTop > 4);
    };

    // Erfasst Scroll innerhalb der einzelnen .view-Container (Mobile)
    document.addEventListener('scroll', (e) => {
        const t = e.target;
        if (t === document || t === window) return;
        check(t.scrollTop || 0);
    }, true);

    // Erfasst normales Fenster-Scrollen (Desktop)
    window.addEventListener('scroll', () => {
        check(window.scrollY || document.documentElement.scrollTop || 0);
    });
}

// --------------Datei speichern-----------

let linkedFileHandle = null;
const BACKUP_LAST_SAVED_KEY = 'backupLastSavedAt_v1';

function formatBackupStatusDate(value) {
    const date = new Date(value);
    if (!Number.isFinite(date.getTime())) return 'Noch keine';

    return date.toLocaleString('de-AT', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    }).replace(',', ' ·');
}

function updateBackupStatusSummary() {
    const savedEl = document.getElementById('backup-status-saved');
    const plannedEl = document.getElementById('backup-status-planned');
    const lastEl = document.getElementById('backup-status-last');
    const fileEl = document.getElementById('backup-status-file');

    const savedTours = appStorage.get('touren') || [];
    const plannedTours = appStorage.get('plannedTours') || [];
    const lastSavedAt = appStorage.get(BACKUP_LAST_SAVED_KEY);

    if (savedEl) savedEl.textContent = String(Array.isArray(savedTours) ? savedTours.length : 0);
    if (plannedEl) plannedEl.textContent = String(Array.isArray(plannedTours) ? plannedTours.length : 0);
    if (lastEl) lastEl.textContent = formatBackupStatusDate(lastSavedAt);
    if (fileEl) fileEl.textContent = linkedFileHandle?.name || 'Nicht verbunden';
}

function markBackupSavedNow() {
    appStorage.set(BACKUP_LAST_SAVED_KEY, new Date().toISOString());
    updateBackupStatusSummary();
}

function buildAppDataPayload() {
    return {
        version: 1,
        updatedAt: new Date().toISOString(),
        touren: appStorage.get('touren') || [],
        plannedTours: appStorage.get('plannedTours') || [],
        meta: {
            theme: document.body.classList.contains('dark')
                ? 'dark'
                : document.body.classList.contains('green')
                ? 'green'
                : document.body.classList.contains('summit')
                ? 'summit'
                : 'light',
            themeEditorSettings: appStorage.get(THEME_EDITOR_KEY) || null,
            font: getThemeEditorFontName(),
            fontSize: getThemeEditorFontSizeScale()
        }
    };
}

function applyAppDataPayload(payload) {
    if (!payload || typeof payload !== 'object') {
        throw new Error('Ungültige Datendatei');
    }

    const importedTours =
        ensureUniqueEntryIds(
            Array.isArray(payload.touren)
                ? payload.touren
                : [],
            'tour'
        ).entries;

    const importedPlannedTours =
        ensureUniqueEntryIds(
            Array.isArray(payload.plannedTours)
                ? payload.plannedTours
                : [],
            'plan'
        ).entries;

    appStorage.set('touren', importedTours);
    appStorage.set('plannedTours', importedPlannedTours);

    if (payload.meta?.themeEditorSettings) {
        appStorage.set(THEME_EDITOR_KEY, payload.meta.themeEditorSettings);

        if (typeof invalidateThemeEditorDraft === 'function') {
            invalidateThemeEditorDraft();
        }
    }

    if (payload.meta?.theme) {

    const ICONS = {
        light: '☀️',
        dark: '🌙',
        green: '🌿',
        summit: '⛰️'
    };

    const validThemes = [
        'light',
        'dark',
        'green',
        'summit'
    ];

    let theme =
        payload.meta.theme;

    if (!validThemes.includes(theme)) {
        theme = 'light';
    }

    document.body.classList.remove(
        'dark',
        'green',
        'summit'
    );

    if (theme === 'dark') {
        document.body.classList.add('dark');
    }

    if (theme === 'green') {
        document.body.classList.add('green');
    }

    if (theme === 'summit') {
        document.body.classList.add('summit');
    }

    appStorage.set('theme', theme);



    try {


        localStorage.setItem('tourtracker-theme', theme);


    } catch (error) {


        console.warn('[Theme] localStorage-Sicherung fehlgeschlagen:', error);


    }

    if (typeof applyThemeEditorSettingsToDom === 'function') {
        applyThemeEditorSettingsToDom();
    }

}

    const importedFont = payload.meta?.font;
    if (
        typeof importedFont === 'string' &&
        Object.prototype.hasOwnProperty.call(THEME_EDITOR_FONT_PRESETS, importedFont)
    ) {
        appStorage.set(THEME_EDITOR_FONT_KEY, importedFont);
        if (typeof applyThemeEditorFont === 'function') {
            applyThemeEditorFont(importedFont, false);
        }
    }

    const importedFontSize = Number(payload.meta?.fontSize);
    if (Number.isFinite(importedFontSize)) {
        appStorage.set(
            THEME_EDITOR_FONT_SIZE_KEY,
            Math.max(80, Math.min(130, importedFontSize))
        );
        if (typeof applyThemeEditorFontSize === 'function') {
            applyThemeEditorFontSize(importedFontSize, false);
        }
    }

    tablePage = 1;
    loadData();
    loadPlannedTours();
    updatePlannedPeaks();
    updateBackupStatusSummary();
}

function updateFileStatus(text) {
    const statusEl = document.getElementById('file-status');
    if (statusEl) statusEl.textContent = text;
    updateBackupStatusSummary();
}

async function createNewDataFile() {
    if (!window.showSaveFilePicker) {
        showToast(
    'Dieser Browser unterstützt die Datendatei-Funktion leider nicht vollständig.',
    {
        type: 'info',
        duration: 4000
    }
);
        return;
    }

    try {
        const handle = await window.showSaveFilePicker({
            suggestedName: 'Tourentracker-Daten.json',
            types: [
                {
                    description: 'JSON-Datei',
                    accept: {
                        'application/json': ['.json']
                    }
                }
            ]
        });

        linkedFileHandle = handle;
        await persistLinkedFileHandle(handle);

        updateFileStatus(`Neue Datei verbunden: ${handle.name}`);

        await saveDataToLinkedFile();
    } catch (err) {
        if (err?.name !== 'AbortError') {
            console.error(err);
            showToast(
    'Neue Datei konnte nicht angelegt werden.',
    {
        type: 'error',
        duration: 3500
    }
);
        }
    }
}

async function openExistingDataFile() {
    if (!window.showOpenFilePicker) {
        showToast(
    'Dieser Browser unterstützt das Öffnen bestehender Datendateien leider nicht vollständig.',
    {
        type: 'info',
        duration: 4000
    }
);
        return;
    }

    try {
        const [handle] = await window.showOpenFilePicker({
            multiple: false,
            types: [
                {
                    description: 'JSON-Datei',
                    accept: {
                        'application/json': ['.json']
                    }
                }
            ]
        });

        if (!handle) return;

        linkedFileHandle = handle;
        await persistLinkedFileHandle(handle);

        updateFileStatus(`Geöffnet: ${handle.name}`);

        await loadDataFromLinkedFile();
    } catch (err) {
        if (err?.name !== 'AbortError') {
            console.error(err);
            showToast(
    'Bestehende Datei konnte nicht geöffnet werden.',
    {
        type: 'error',
        duration: 3500
    }
);
        }
    }
}

async function saveDataToLinkedFile(silent = false) {
    if (!linkedFileHandle) {
        if (!silent) {
    showToast(
        'Bitte zuerst eine Datei anlegen oder öffnen.',
        {
            type: 'info',
            duration: 3000
        }
    );
}
        return false;
    }

    try {
        const hasPermission = await ensureFilePermission(linkedFileHandle, true);
        if (!hasPermission) {
            if (!silent) {
                showToast(
    'Keine Schreibberechtigung für die Datei.',
    {
        type: 'error',
        duration: 3500
    }
);
            } else {
                console.warn('Auto-Save: Keine Schreibberechtigung für die Datei.');
            }
            return false;
        }

        const writable = await linkedFileHandle.createWritable();
        const payload = buildAppDataPayload();

        await writable.write(JSON.stringify(payload, null, 2));
        await writable.close();

        updateFileStatus(`Gespeichert: ${linkedFileHandle.name} (${new Date().toLocaleTimeString('de-DE')})`);
        markBackupSavedNow();
        return true;
    } catch (err) {
        console.error(err);
        if (!silent) {
            showToast(
    'Speichern in Datei fehlgeschlagen.',
    {
        type: 'error',
        duration: 3500
    }
);
        } else {
            console.warn('Automatischer Datei-Sync fehlgeschlagen — Tour wurde aber lokal gespeichert.');
        }
        return false;
    }
}

async function loadDataFromLinkedFile() {
    if (!linkedFileHandle) {
        showToast(
    'Bitte zuerst eine bestehende Datei öffnen oder eine Datei anlegen.',
    {
        type: 'info',
        duration: 3000
    }
);
        return;
    }

    try {
        const hasPermission = await ensureFilePermission(linkedFileHandle, false);
        if (!hasPermission) {
            showToast(
    'Keine Leseberechtigung für die Datei.',
    {
        type: 'error',
        duration: 3500
    }
);
            return;
        }

        const file = await linkedFileHandle.getFile();
        const text = await file.text();
        const payload = JSON.parse(text);

        applyAppDataPayload(payload);
        updateFileStatus(`Geladen: ${linkedFileHandle.name}`);
    } catch (err) {
        console.error(err);
        showToast(
    'Laden aus Datei fehlgeschlagen oder Datei ist ungültig.',
    {
        type: 'error',
        duration: 4000
    }
);
    }
}

async function disconnectDataFile() {
    linkedFileHandle = null;

    try {
        await clearPersistedFileHandle();
    } catch (err) {
        console.error('Datei-Verknüpfung konnte nicht gelöscht werden:', err);
    }

    updateFileStatus('Keine Datei verbunden');
}

async function autoSaveDataFileIfLinked() {
    // Automatischer Datei-Sync deaktiviert — die File System Access API
    // löst dabei native Berechtigungs-Dialoge aus, die sich nicht stylen lassen.
    // Datensicherung läuft stattdessen ausschließlich über
    // "Einfacher Download" / "Einfacher Import" (siehe Datensicherung-Box).
    return;
}

async function restoreLinkedFileHandleOnStartup() {
    try {
        const handle = await loadPersistedFileHandle();

        if (!handle) {
            updateFileStatus('Keine Datei verbunden');
            return;
        }

        linkedFileHandle = handle;

        const hasReadPermission = await handle.queryPermission({ mode: 'read' });

        if (hasReadPermission === 'granted') {
            updateFileStatus(`Verbunden: ${handle.name}`);

            // Theme zusätzlich aus der verknüpften Datendatei wiederherstellen.
            // Die Tourdaten selbst werden dabei NICHT automatisch geladen.
            try {
                const file = await handle.getFile();
                const payload = JSON.parse(await file.text());
                const fileTheme = payload?.meta?.theme;
                const validThemes = ['light', 'dark', 'green', 'summit'];

                if (payload?.meta?.themeEditorSettings) {
                    appStorage.set(THEME_EDITOR_KEY, payload.meta.themeEditorSettings);

                    if (typeof invalidateThemeEditorDraft === 'function') {
                        invalidateThemeEditorDraft();
                    }
                }

                const fileFont = payload?.meta?.font;
                if (
                    typeof fileFont === 'string' &&
                    Object.prototype.hasOwnProperty.call(THEME_EDITOR_FONT_PRESETS, fileFont)
                ) {
                    appStorage.set(THEME_EDITOR_FONT_KEY, fileFont);
                    if (typeof applyThemeEditorFont === 'function') {
                        applyThemeEditorFont(fileFont, false);
                    }
                }

                const fileFontSize = Number(payload?.meta?.fontSize);
                if (Number.isFinite(fileFontSize)) {
                    appStorage.set(
                        THEME_EDITOR_FONT_SIZE_KEY,
                        Math.max(80, Math.min(130, fileFontSize))
                    );
                    if (typeof applyThemeEditorFontSize === 'function') {
                        applyThemeEditorFontSize(fileFontSize, false);
                    }
                }

                if (validThemes.includes(fileTheme)) {
                    document.body.classList.remove('dark', 'green', 'summit');

                    if (fileTheme === 'dark') {
                        document.body.classList.add('dark');
                    } else if (fileTheme === 'green') {
                        document.body.classList.add('green');
                    } else if (fileTheme === 'summit') {
                        document.body.classList.add('summit');
                    }

                    appStorage.set('theme', fileTheme);

                    try {
                        localStorage.setItem('tourtracker-theme', fileTheme);
                    } catch (error) {
                        console.warn('[Theme] lokale Sicherung aus Datendatei fehlgeschlagen:', error);
                    }

                    try {
                        sessionStorage.setItem('tourtracker-theme', fileTheme);
                    } catch (error) {
                        console.warn('[Theme] Session-Sicherung aus Datendatei fehlgeschlagen:', error);
                    }

                    const icons = {
                        light: '☀️',
                        dark: '🌙',
                        green: '🌿',
                        summit: '⛰️'
                    };
                

                    document.querySelectorAll('[data-theme-choice]').forEach(option => {
                        const active = option.dataset.themeChoice === fileTheme;
                        option.classList.toggle('active', active);
                        option.setAttribute('aria-pressed', active ? 'true' : 'false');
                    });

                    if (typeof applyThemeEditorSettingsToDom === 'function') {
                        applyThemeEditorSettingsToDom();
                    }

                    if (typeof refreshThemeDependentUi === 'function') {
                        refreshThemeDependentUi();
                    }
                }
            } catch (error) {
                console.warn('[Theme] Theme aus verknüpfter Datendatei konnte nicht gelesen werden:', error);
            }
        } else {
            updateFileStatus(`Gemerkte Datei: ${handle.name} (Zugriff bei Bedarf bestätigen)`);
        }
    } catch (err) {
        console.error('Gespeicherte Datei-Verknüpfung konnte nicht geladen werden:', err);
        updateFileStatus('Keine Datei verbunden');
    }
}

// ---------------- Filter ----------------

const DIAGRAM_FILTER_KEY = 'diagramFilterState_v1';

let diagramFilterState = { selectedYears: [] };

function saveDiagramFilterState() {
    appStorage.set(DIAGRAM_FILTER_KEY, diagramFilterState);
}



/* =========================================================
   Stats – gemeinsamer Jahresfilter
   für Diagramme, Statistik und Highlights
   ========================================================= */

function applyStatsYearFilter(entries) {

    if (
        !Array.isArray(entries) ||
        statsYearFilter === 'all'
    ) {
        return entries;
    }

    const currentYear =
        new Date().getFullYear();


    return entries.filter(entry => {

        if (!entry.date) return false;

        const date =
            new Date(entry.date);

        if (isNaN(date.getTime())) {
            return false;
        }


        if (statsYearFilter === 'past') {

            return (
                date.getFullYear() !==
                currentYear
            );
        }


        return (
            date.getFullYear() ===
            Number(statsYearFilter)
        );
    });
}


/*
 * Datengrundlage für Statistik,
 * Diagramme und Highlights.
 *
 * Es gilt ausschließlich der
 * eigene Stats-Jahresfilter.
 */

let tourDataRevision = 0;
let statsFilteredDataCache = {
    revision: -1,
    yearFilter: null,
    data: []
};

function invalidateTourDataCaches() {
    tourDataRevision++;

    statsFilteredDataCache = {
        revision: -1,
        yearFilter: null,
        data: []
    };

    if (typeof invalidateTourSearchCache === 'function') {
        invalidateTourSearchCache();
    }
}

/* =========================================================
   Abgeleitete Views nur bei Bedarf neu rendern
   ========================================================= */

const derivedViewDirty = {
    dashboard: true,
    chart: true,
    map: true,
    filter: true,
    tour: true
};

function markDerivedViewsDirty(...views) {
    views.forEach(view => {
        if (view in derivedViewDirty) {
            derivedViewDirty[view] = true;
        }
    });
}

function markDerivedViewClean(view) {
    if (view in derivedViewDirty) {
        derivedViewDirty[view] = false;
    }
}

function isDerivedViewDirty(view) {
    return Boolean(derivedViewDirty[view]);
}

function markStorageDependentViewsDirty(key) {
    if (key === 'touren') {
        markDerivedViewsDirty(
            'dashboard',
            'chart',
            'map',
            'filter'
        );
        return;
    }

    if (key === 'plannedTours') {
        markDerivedViewsDirty('tour');
        return;
    }

    /*
     * Kartenmarker und Heatmaps verwenden Theme-Farben.
     * Ein Themewechsel außerhalb der Karte macht deshalb
     * nur die Karte für den nächsten Aufruf "dirty".
     */
    if (key === 'theme') {
        markDerivedViewsDirty('map');
    }
}

function getStatsFilteredData() {
    if (
        statsFilteredDataCache.revision === tourDataRevision &&
        statsFilteredDataCache.yearFilter === statsYearFilter
    ) {
        return statsFilteredDataCache.data;
    }

    const all =
        appStorage.get('touren') || [];

    const data =
        applyStatsYearFilter(all);

    statsFilteredDataCache = {
        revision: tourDataRevision,
        yearFilter: statsYearFilter,
        data
    };

    return data;
}


function populateStatsYearSelect() {

    const yearSelect =
        document.getElementById(
            'stats-year-select'
        );

    if (!yearSelect) return;


    const tours =
        appStorage.get('touren') || [];

    const years =
        new Set();


    tours.forEach(entry => {

        if (!entry.date) return;

        const date =
            new Date(entry.date);

        if (isNaN(date.getTime())) {
            return;
        }

        years.add(
            date.getFullYear()
        );
    });


    const sortedYears =
        Array.from(years)
            .sort(
                (a, b) => b - a
            );


    yearSelect.innerHTML = `
        <option value="all">
            Alle Jahre
        </option>

        <option value="past">
            Vergangene Jahre
        </option>
    `;


    sortedYears.forEach(year => {

        const option =
            document.createElement(
                'option'
            );

        option.value =
            String(year);

        option.textContent =
            String(year);

        yearSelect.appendChild(
            option
        );
    });


    const validValue =
        statsYearFilter === 'all' ||
        statsYearFilter === 'past' ||
        sortedYears.includes(
            Number(statsYearFilter)
        );


    if (!validValue) {
        statsYearFilter = 'all';
    }


    yearSelect.value =
        statsYearFilter;


    updateStatsYearButtons(
        sortedYears
    );
}


function updateStatsYearButtons(
    sortedYears = null
) {

    const yearSelect =
        document.getElementById(
            'stats-year-select'
        );

    const prevBtn =
        document.getElementById(
            'stats-year-prev-btn'
        );

    const nextBtn =
        document.getElementById(
            'stats-year-next-btn'
        );


    if (
        !yearSelect ||
        !prevBtn ||
        !nextBtn
    ) {
        return;
    }


    const years =
        sortedYears ||
        Array.from(
            yearSelect.options
        )
            .map(option =>
                option.value
            )
            .filter(value =>
                value !== 'all' &&
                value !== 'past'
            )
            .map(Number)
            .sort(
                (a, b) => b - a
            );


    if (
        statsYearFilter === 'all' ||
        statsYearFilter === 'past' ||
        years.length === 0
    ) {

        prevBtn.disabled =
            years.length === 0;

        nextBtn.disabled =
            years.length === 0;

        return;
    }


    const index =
        years.indexOf(
            Number(statsYearFilter)
        );


    prevBtn.disabled =
        index === -1 ||
        index >= years.length - 1;


    nextBtn.disabled =
        index === -1 ||
        index <= 0;
}


function shiftStatsYear(direction) {

    const yearSelect =
        document.getElementById(
            'stats-year-select'
        );

    if (!yearSelect) return;


    const years =
        Array.from(
            yearSelect.options
        )
            .map(option =>
                option.value
            )
            .filter(value =>
                value !== 'all' &&
                value !== 'past'
            )
            .map(Number)
            .sort(
                (a, b) => b - a
            );


    if (!years.length) return;


    let newValue;


    if (
        statsYearFilter === 'all' ||
        statsYearFilter === 'past'
    ) {

        newValue =
            direction === 'next'
                ? years[0]
                : years[
                    years.length - 1
                  ];

    } else {

        const index =
            years.indexOf(
                Number(
                    statsYearFilter
                )
            );

        if (index === -1) return;


        const newIndex =
            direction === 'next'
                ? index - 1
                : index + 1;


        if (
            newIndex < 0 ||
            newIndex >= years.length
        ) {
            return;
        }


        newValue =
            years[newIndex];
    }


    yearSelect.value =
        String(newValue);

    yearSelect.dispatchEvent(
        new Event('change')
    );
}


function refreshStatsYearViews() {

    /*
     * Der Jahresfilter betrifft nur die aktuell sichtbare
     * Stats-Unterseite. Versteckte Unterseiten werden erst
     * beim Öffnen berechnet.
     */
    if (currentView === 'chart') {
        refreshChartViewData();
        return;
    }

    markDerivedViewsDirty('chart');
}

function getDiagramFilteredTours() {
    return getStatsFilteredData();
}

function getDiagramFilteredToursIgnoringYear() {

    /*
     * Der Jahresvergleich besitzt seine
     * eigene Jahresauswahl.
     *
     * Deshalb immer alle gespeicherten
     * Touren als Ausgangsbasis liefern.
     */
    return [
        ...(appStorage.get('touren') || [])
    ];
}

document
    .getElementById(
        'stats-year-select'
    )
    ?.addEventListener(
        'change',
        event => {

            statsYearFilter =
                event.target.value;

            updateStatsYearButtons();

            refreshStatsYearViews();
        }
    );


document
    .getElementById(
        'stats-year-prev-btn'
    )
    ?.addEventListener(
        'click',
        () => {
            shiftStatsYear('prev');
        }
    );


document
    .getElementById(
        'stats-year-next-btn'
    )
    ?.addEventListener(
        'click',
        () => {
            shiftStatsYear('next');
        }
    );

function populateFilters(data) {
    const years = new Set();
    data.forEach(entry => {
        if (!entry.date) return;
        const d = new Date(entry.date);
        if (isNaN(d.getTime())) return;
        years.add(d.getFullYear());
    });
    populateYearCompareButtons(Array.from(years).sort((a, b) => b - a));
}

