// ─── Toast-System ────────────────────────────────────────────────────────────

let _toastContainer = null;

function getToastContainer() {
    if (_toastContainer) return _toastContainer;
    _toastContainer = document.createElement('div');
    _toastContainer.className = 'toast-container';
    document.body.appendChild(_toastContainer);
    return _toastContainer;
}

function showToast(message, { type = 'info', duration = 2000, undoCallback = null } = {}) {
    const container = getToastContainer();

    const icons = { error: '⚠️', success: '✓', undo: '🗑️', info: 'ℹ️' };
    const icon = icons[type] || icons.info;

    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;

    toast.innerHTML = `
        <span class="toast-icon">${icon}</span>
        <span class="toast-msg">${message}</span>
        ${undoCallback ? `<button type="button" class="toast-undo-btn">Rückgängig</button>` : ''}
        <div class="toast-bar"></div>
    `;

    let undoClicked = false;
    let timer = null;

    if (undoCallback) {
        toast.querySelector('.toast-undo-btn').addEventListener('click', () => {
            undoClicked = true;
            clearTimeout(timer);
            removeToast(toast);
            undoCallback();
        });
    }

    container.appendChild(toast);

    // Progress-Bar animieren
    const bar = toast.querySelector('.toast-bar');
    requestAnimationFrame(() => {
        bar.style.transition = `transform ${duration}ms linear`;
        bar.style.transform = 'scaleX(0)';
    });

    timer = setTimeout(() => {
        if (!undoClicked) removeToast(toast);
    }, duration);

    return toast;
}

function removeToast(toast) {
    if (!toast || !toast.parentNode) return;
    toast.classList.add('toast-exit');
    setTimeout(() => toast.remove(), 280);
}

// ─── Achievement-Toast bei neu erreichten Meilensteinen ─────────────────────

function getYearFromDate(dateStr) {
    if (!dateStr) return null;
    const d = new Date(dateStr);
    return isNaN(d.getTime()) ? null : d.getFullYear();
}

const MILESTONE_LABELS = {
    dist: 'Strecke',
    asc: 'Aufstieg',
    time: 'Gehzeit',
    peaks: 'Gipfel',
    steps: 'Schritte'
};

const MILESTONE_ICONS = {
    dist: '📏',
    asc: '⛰️',
    time: '⏱️',
    peaks: '✟',
    steps: '👣'
};

const MILESTONE_UNITS = {
    dist: 'km',
    asc: 'hm',
    time: 'h',
    peaks: 'Gipfel',
    steps: 'Schritte'
};

function checkAndShowNewMilestones(before, after, opts = {}) {
    const { scope = 'lifetime', year = null, startDelay = 0 } = opts;
    const newAchievements = [];

    ['dist', 'asc', 'time', 'peaks', 'steps'].forEach(type => {
        const beforeCount = before[type].reached.length;
        const afterReached = after[type].reached;
        if (afterReached.length > beforeCount) {
            afterReached.slice(beforeCount).forEach(m => {
                newAchievements.push({ type, milestone: m.milestone });
            });
        }
    });

    newAchievements.forEach((ach, i) => {
        setTimeout(() => {
            const message = scope === 'year'
                ? `${MILESTONE_ICONS[ach.type]} ${MILESTONE_LABELS[ach.type]} ${year}: ${ach.milestone.toLocaleString('de-AT')} ${MILESTONE_UNITS[ach.type]} in diesem Jahr erreicht!`
                : `${MILESTONE_ICONS[ach.type]} ${MILESTONE_LABELS[ach.type]}: ${ach.milestone.toLocaleString('de-AT')} ${MILESTONE_UNITS[ach.type]} erreicht!`;
            showAchievementToast(message);
        }, startDelay + i * 600);
    });

    return newAchievements.length;
}

function showAchievementToast(message) {
    const container = getToastContainer();

    const toast = document.createElement('div');
    toast.className = 'toast toast-achievement';

    toast.innerHTML = `
        <span class="toast-icon toast-achievement-icon">🏆</span>
        <span class="toast-msg">${message}</span>
        <div class="toast-bar"></div>
        <div class="light-sweep toast-achievement-sweep"></div>
    `;

    container.appendChild(toast);

    const bar = toast.querySelector('.toast-bar');
    const duration = 5000;
    requestAnimationFrame(() => {
        bar.style.transition = `transform ${duration}ms linear`;
        bar.style.transform = 'scaleX(0)';
    });

    setTimeout(() => removeToast(toast), duration);
}


