//-------------Hilfsfunktion Gipfelhöhe--------------

function parsePeakHeight(value) {
    if (value === null || value === undefined) return 0;

    let s = String(value)
        .trim()
        .replace(/\s/g, '')
        .replace(/[^\d.,-]/g, '');

    if (!s) return 0;

    // Falls Höhe als "2.345" eingegeben wurde -> 2345
    if (/^\d{1,3}(\.\d{3})+$/.test(s)) {
        s = s.replace(/\./g, '');
    }

    // Komma als Dezimaltrenner erlauben
    s = s.replace(',', '.');

    const n = parseFloat(s);
    return Number.isFinite(n) ? n : 0;
}

// ---------------- Gefilterte Daten ----------------
/* =========================================================
   Persistente Eintrags-IDs
   ========================================================= */

function createEntryId(prefix = 'entry') {
    if (
        typeof crypto !== 'undefined' &&
        typeof crypto.randomUUID === 'function'
    ) {
        return `${prefix}-${crypto.randomUUID()}`;
    }

    return (
        `${prefix}-` +
        `${Date.now().toString(36)}-` +
        `${Math.random().toString(36).slice(2, 10)}`
    );
}

function ensureUniqueEntryIds(entries, prefix) {
    const list = Array.isArray(entries) ? entries : [];
    const seen = new Set();
    let changed = false;

    list.forEach(entry => {
        if (!entry || typeof entry !== 'object') return;

        let id = String(entry.id || '').trim();

        if (!id || seen.has(id)) {
            id = createEntryId(prefix);
            entry.id = id;
            changed = true;
        }

        seen.add(id);
    });

    return { entries: list, changed };
}

function migrateStoredEntryIds() {
    const savedResult = ensureUniqueEntryIds(
        appStorage.get('touren') || [],
        'tour'
    );

    const plannedResult = ensureUniqueEntryIds(
        appStorage.get('plannedTours') || [],
        'plan'
    );

    if (savedResult.changed) {
        appStorage.set('touren', savedResult.entries);
    }

    if (plannedResult.changed) {
        appStorage.set('plannedTours', plannedResult.entries);
    }
}

function getFilteredData() {

    /*
     * Die normalen Tour- und Gipfellisten
     * arbeiten immer mit allen
     * gespeicherten Touren.
     */
    return [
        ...(appStorage.get('touren') || [])
    ];
}

