function loadImageFromFile(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = () => reject(reader.error);
        reader.readAsDataURL(file);
    });
}

function compressImageDataUrl(dataUrl, {
    maxWidth = 1400,
    maxHeight = 1400,
    quality = 0.82,
    mimeType = 'image/jpeg'
} = {}) {
    return new Promise((resolve, reject) => {
        const img = new Image();

        img.onload = () => {
            let { width, height } = img;

            const scale = Math.min(
                1,
                maxWidth / width,
                maxHeight / height
            );

            const targetWidth = Math.round(width * scale);
            const targetHeight = Math.round(height * scale);

            const canvas = document.createElement('canvas');
            canvas.width = targetWidth;
            canvas.height = targetHeight;

            const ctx = canvas.getContext('2d');
            if (!ctx) {
                reject(new Error('Canvas-Kontext nicht verfügbar'));
                return;
            }

            ctx.drawImage(img, 0, 0, targetWidth, targetHeight);

            const compressed = canvas.toDataURL(mimeType, quality);
            resolve(compressed);
        };

        img.onerror = reject;
        img.src = dataUrl;
    });
}

async function handleTourImageFile(file) {
    if (!file) return;

    if (!file.type.startsWith('image/')) {
        showToast(
    'Bitte ein gültiges Bild auswählen.',
    {
        type: 'error',
        duration: 3000
    }
);
        return;
    }

    try {
        const rawDataUrl = await loadImageFromFile(file);
        const compressedDataUrl = await compressImageDataUrl(rawDataUrl, {
            maxWidth: 1400,
            maxHeight: 1400,
            quality: 0.82,
            mimeType: 'image/jpeg'
        });

        pendingTourImageData =
    compressedDataUrl;

pendingTourImageName =
    file.name || 'Bild';


updateTourImagePreview(
    compressedDataUrl
);

        const saveBox = form.closest('.box');
        requestAnimationFrame(() => updateBoxHeight(saveBox));
    } catch (err) {
        console.error(err);
        showToast(
    'Bild konnte nicht verarbeitet werden.',
    {
        type: 'error',
        duration: 3000
    }
);
    }
}

