function animateModalClose(modal, closeFn) {
    const card     = modal?.querySelector('.modal-card');
    const backdrop = modal?.querySelector('.modal-backdrop');

    if (!card || !backdrop) { closeFn(); return; }
    if (!isModalSwipeLayout()) { closeFn(); return; }

    // is-closing verhindert, dass modalSlideUp erneut feuert
    card.classList.add('is-closing');
    card.classList.remove('is-dragging');

    const targetY = card.getBoundingClientRect().height + 60;

    requestAnimationFrame(() => {
        card.style.transform = `translateY(${targetY}px)`;
        backdrop.style.opacity = '0';
    });

    setTimeout(() => {
        card.classList.remove('is-closing');
        closeFn();
    }, 500);
}

function attachModalSwipeDown(modal, closeFn) {
    if (!modal || modal.dataset.swipeInit === '1') return;

    const card     = modal.querySelector('.modal-card');
    const backdrop = modal.querySelector('.modal-backdrop');
    if (!card || !backdrop) return;
    modal.dataset.swipeInit = '1';

    let tracking  = false;   // touchstart erfasst
    let swipeMode = false;   // Richtung bestätigt: abwärts
    let startY = 0, startX = 0, currentY = 0;
    let lastY  = 0, lastT  = 0, velocity  = 0;

    const CLOSE_THR = 110;
    const VEL_THR   = 0.5;
    const FLICK_MIN = 30;
    const MAX_DRAG  = 260;
    const DIR_LOCK  = 8;

    function resetState() {
        tracking = swipeMode = false;
        startY = startX = currentY = lastY = velocity = 0;
        card.classList.remove('is-dragging');
        card.style.transform   = '';
        card.style.touchAction = '';
        backdrop.style.opacity = '';
    }

    // ── touchstart ────────────────────────────────────────────────────────
    card.addEventListener('touchstart', (e) => {
        if (!isModalSwipeLayout()) return;
        if (modal.classList.contains('hidden')) return;
        if (e.target.closest('button, input, select, textarea, a, [role="button"]')) return;
        if (card.scrollTop > 2) return; // Modal-Inhalt gescrollt → kein Swipe

        const t   = e.touches[0];
        tracking  = true;
        swipeMode = false;
        startY = currentY = lastY = t.clientY;
        startX    = t.clientX;
        lastT     = performance.now();
        velocity  = 0;
    }, { passive: true });

    // ── touchmove — non-passive damit preventDefault() greift ─────────────
    card.addEventListener('touchmove', (e) => {
        if (!tracking || !isModalSwipeLayout() || modal.classList.contains('hidden')) return;

        const t   = e.touches[0];
        const now = performance.now();
        const dt  = now - lastT;
        if (dt > 0 && dt < 100) velocity = (t.clientY - lastY) / dt;
        lastY = t.clientY;
        lastT = now;

        const dy = t.clientY - startY;
        const dx = t.clientX - startX;

        // Richtung noch unklar
        if (!swipeMode) {
            if (Math.abs(dy) < DIR_LOCK && Math.abs(dx) < DIR_LOCK) return;
            if (Math.abs(dx) >= Math.abs(dy)) { tracking = false; return; } // horizontal → Abbruch
            if (dy < 0)                        { tracking = false; return; } // aufwärts → Abbruch

            // Abwärts bestätigt
            swipeMode = true;
            card.style.touchAction = 'none'; // Browser-Scroll zusätzlich deaktivieren
        }

        e.preventDefault(); // ← das ist der eigentliche Fix

        if (dy <= 0) return;

        const clamped = dy > MAX_DRAG ? MAX_DRAG + (dy - MAX_DRAG) * 0.18 : dy;
        currentY = t.clientY;
        card.classList.add('is-dragging');
        card.style.transform   = `translateY(${(clamped * 0.82).toFixed(1)}px)`;
        backdrop.style.opacity = (0.45 * (1 - Math.min(dy / MAX_DRAG, 1))).toFixed(2);

    }, { passive: false }); // ← zwingend non-passive!

    // ── touchend ──────────────────────────────────────────────────────────
    function handleEnd() {
        if (!tracking) return;
        const dy = currentY - startY;

        if (swipeMode && (dy > CLOSE_THR || (dy > FLICK_MIN && velocity > VEL_THR))) {
            tracking = swipeMode = false;
            card.style.touchAction = '';
            animateModalClose(modal, closeFn);
            return;
        }
        resetState();
    }

    card.addEventListener('touchend',    handleEnd,  { passive: true });
    card.addEventListener('touchcancel', resetState, { passive: true });
}



function initModalSwipeDown() {
    const modal = document.getElementById('tour-detail-modal');
    attachModalSwipeDown(modal, closeTourDetail);
}

function initAllModalSwipes() {
    const modalConfig = [
    { id: 'tour-detail-modal',  closeFn: closeTourDetail       },
    { id: 'compare-modal',      closeFn: closeCompareModal      },
    { id: 'month-stats-modal',  closeFn: closeMonthStatsModal   },
    { id: 'stats-chart-modal',  closeFn: closeStatsChartModal   },
    { id: 'tour-list-modal',    closeFn: closeTourListModal     },
    { id: 'milestone-modal',    closeFn: closeMilestoneModal    },
    { id: 'dash-stat-modal',    closeFn: closeDashStatModal     },
];

    modalConfig.forEach(({ id, closeFn }) => {
        const modal = document.getElementById(id);
        if (modal) attachModalSwipeDown(modal, closeFn);
    });
}

