function openImageLightbox(src, alt = 'Tourbild') {
    const lightbox = document.getElementById('image-lightbox');
    const img = document.getElementById('image-lightbox-img');
    const inner = lightbox?.querySelector('.image-lightbox-inner');

    if (!lightbox || !img || !src) return;

    img.src = src;
    img.alt = alt || 'Tourbild';

    if (inner) {
        inner.classList.remove('is-dragging');
        inner.style.transform = '';
    }

    lightbox.style.background = 'rgba(0,0,0,0.82)';
    lightbox.classList.remove('hidden');
    lightbox.setAttribute('aria-hidden', 'false');
}

function closeImageLightbox() {
    const lightbox = document.getElementById('image-lightbox');
    const img = document.getElementById('image-lightbox-img');
    const inner = lightbox?.querySelector('.image-lightbox-inner');

    if (!lightbox || !img) return;

    if (inner) {
        inner.classList.remove('is-dragging');
        inner.style.transform = '';
    }

    lightbox.classList.add('hidden');
    lightbox.setAttribute('aria-hidden', 'true');
    lightbox.style.background = '';

    img.src = '';
    img.alt = 'Tourbild';
}

function animateCloseImageLightboxDown() {
    const lightbox = document.getElementById('image-lightbox');
    const inner = lightbox?.querySelector('.image-lightbox-inner');

    if (!lightbox || !inner) {
        closeImageLightbox();
        return;
    }

    if (window.innerWidth > 768) {
        closeImageLightbox();
        return;
    }

    inner.classList.remove('is-dragging');

    const targetY = window.innerHeight + 120;

    requestAnimationFrame(() => {
        inner.style.transform = `translateY(${targetY}px)`;
        lightbox.style.background = 'rgba(0,0,0,0)';
    });

    setTimeout(() => {
        closeImageLightbox();
    }, 260);
}

function initImageLightbox() {
    const lightbox = document.getElementById('image-lightbox');
    const closeBtn = document.getElementById('image-lightbox-close');
    const inner = lightbox?.querySelector('.image-lightbox-inner');
    const img = document.getElementById('image-lightbox-img');

    if (!lightbox || !inner || !img) return;

    closeBtn?.addEventListener('click', closeImageLightbox);

    lightbox.addEventListener('click', (e) => {
        if (e.target === lightbox) {
            closeImageLightbox();
        }
    });

    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && !lightbox.classList.contains('hidden')) {
            closeImageLightbox();
        }
    });

    let dragging = false;
    let startY = 0;
    let currentY = 0;
    let activePointerId = null;

    const CLOSE_THRESHOLD = 90;
    const MAX_DRAG = 320;

    function resetSwipeStyles() {
        dragging = false;
        startY = 0;
        currentY = 0;
        activePointerId = null;

        inner.classList.remove('is-dragging');
        inner.style.transform = '';
        lightbox.style.background = 'rgba(0,0,0,0.82)';
    }

    function onPointerMove(e) {
        if (!dragging) return;
        if (window.innerWidth > 768) return;
        if (lightbox.classList.contains('hidden')) return;

        if (activePointerId !== null && e.pointerId !== activePointerId) return;

        e.preventDefault();

        let deltaY = e.clientY - startY;

        // Nur nach unten ziehen
        if (deltaY <= 0) {
            deltaY = 0;
        }

        if (deltaY > MAX_DRAG) {
            deltaY = MAX_DRAG;
        }

        currentY = e.clientY;

        inner.classList.add('is-dragging');
        inner.style.transform = `translateY(${deltaY}px)`;

        const nextOpacity = Math.max(0.08, 0.82 - deltaY / 340);
        lightbox.style.background = `rgba(0,0,0,${nextOpacity})`;
    }

    function onPointerUp(e) {
        if (!dragging) return;

        if (activePointerId !== null && e.pointerId !== activePointerId) return;

        const deltaY = currentY - startY;

        if (deltaY > CLOSE_THRESHOLD) {
            dragging = false;
            activePointerId = null;
            animateCloseImageLightboxDown();
            return;
        }

        resetSwipeStyles();
    }

    function startSwipe(e) {
        if (window.innerWidth > 768) return;
        if (lightbox.classList.contains('hidden')) return;
        if (e.pointerType === 'mouse') return;

        e.preventDefault();

        dragging = true;
        startY = e.clientY;
        currentY = e.clientY;
        activePointerId = e.pointerId;

        inner.classList.remove('is-dragging');

        try {
            img.setPointerCapture?.(e.pointerId);
        } catch (_) {}
    }

    img.addEventListener('pointerdown', startSwipe, { passive: false });

    window.addEventListener('pointermove', onPointerMove, { passive: false });
    window.addEventListener('pointerup', onPointerUp, { passive: false });
    window.addEventListener('pointercancel', resetSwipeStyles, { passive: false });
}

function returnFromTourDetailToModal() {
    const detailModal = document.getElementById('tour-detail-modal');
    const returnModalId = tourDetailReturnModalId;

    if (!returnModalId) return;

    const returnModal =
        document.getElementById(returnModalId);

    if (!returnModal) {
        closeTourDetail();
        return;
    }

    // Tourdetail schließen
    detailModal?.classList.add('hidden');

    // Ursprüngliches Modal wieder anzeigen
    returnModal.classList.remove('hidden');

    document.body.classList.add('modal-open');

    // Rücksprungzustand löschen
    tourDetailReturnModalId = null;

    const backBtn = document.getElementById('td-back');
    if (backBtn) {
        backBtn.hidden = true;
    }
}

