function drawAverageStepsDiagram() {
    const canvas =
        document.getElementById('avg-steps-canvas');

    if (!canvas) return;

    const ctx = resizeCanvasToDisplaySize(canvas);
    const { textColor } = getChartTheme();

    ctx.clearRect(0, 0, getCanvasLogicalWidth(canvas), getCanvasLogicalHeight(canvas));

    const data = getDiagramFilteredTours();

    const monthStepSums = Array(12).fill(0);
    const monthCounts = Array(12).fill(0);

    data.forEach(entry => {
        if (!entry.date) return;

        const date = new Date(entry.date);

        if (isNaN(date.getTime())) return;

        const steps =
            Number(calculateEntrySteps(entry)) || 0;

        if (steps <= 0) return;

        const month = date.getMonth();

        monthStepSums[month] += steps;
        monthCounts[month]++;
    });

    const monthAverages =
        monthStepSums.map((sum, month) =>
            monthCounts[month] > 0
                ? sum / monthCounts[month]
                : 0
        );

    const validValues =
        monthAverages.filter(value => value > 0);

    const totalSteps = getBoundedAverage(validValues) || 0;

    drawChartTitleWithTotal(
        ctx,
        canvas,
        'Ø Schritte pro Tour',
        totalSteps > 0
            ? Math.round(totalSteps)
                .toLocaleString('de-AT')
            : '–'
    );

    drawBars(
        canvas,
        ctx,
        monthAverages,
        '',
        0
    );
}



