function refreshChartViewData() {
    populateStatsYearSelect();

    const statisticsActive =
        document.getElementById('stats-statistics-page')
            ?.classList.contains('active');

    const highlightsActive =
        document.getElementById('stats-highlights-page')
            ?.classList.contains('active');

    const developmentActive =
        document.getElementById('stats-development-page')
            ?.classList.contains('active');

    const peaksActive =
        document.getElementById('stats-peaks-page')
            ?.classList.contains('active');

    if (statisticsActive) {
        updateStats();
        markDerivedViewClean('chart');
        return;
    }

    if (highlightsActive) {
        updateHighlights();
        markDerivedViewClean('chart');
        return;
    }

    if (developmentActive) {
        updateDevelopmentStatsPage();
        markDerivedViewClean('chart');
        return;
    }

    if (peaksActive) {
        updatePeakStatsPage();
        markDerivedViewClean('chart');
        return;
    }

    updateCharts();
    markDerivedViewClean('chart');
}

