if (currentIndex < 0) currentIndex = 0;

/**
 * Setzt alle Views passend nebeneinander:
 * aktive View = 0%
 * linke View = -100%
 * rechte View = 100%
 */
function positionViews(activeIndex, animate = true, dragPercent = 0) {
    viewOrder.forEach((name, index) => {
        const view = viewMap[name];
        if (!view) return;

        const offset = (index - activeIndex) * 100 + dragPercent;

        if (!animate) {
            view.classList.add('no-transition');
        } else {
            view.classList.remove('no-transition');
        }

        view.style.transform = `translateX(${offset}%)`;

        if (index === activeIndex && dragPercent === 0) {
            view.classList.add('visible');
        } else {
            view.classList.remove('visible');
        }
    });

    if (!animate) {
        requestAnimationFrame(() => {
            Object.values(viewMap).forEach(view => {
                view.classList.remove('no-transition');
            });
        });
    }
}

function updateMoreViewIndicator() {
    const moreButton =
        document.getElementById('more-toggle');

    if (!moreButton) return;

    const dots = Array.from(
        moreButton.querySelectorAll('.more-dot')
    );

    // Alle Punkte zunächst deaktivieren
    dots.forEach(dot => {
        dot.classList.remove('is-active');
    });

    const moreViewIndicatorMap = {
        tour: 0,
        filter: 1,
        backup: 2,
        theme: 3,
        achievements: 4,
        wrapped: 5
    };

    const activeDotIndex =
        moreViewIndicatorMap[currentView];

    if (
        activeDotIndex !== undefined &&
        dots[activeDotIndex]
    ) {
        dots[activeDotIndex].classList.add('is-active');
    }

    const isMoreView =
        Object.prototype.hasOwnProperty.call(
            moreViewIndicatorMap,
            currentView
        );

    moreButton.classList.toggle(
        'more-view-active',
        isMoreView
    );
}

