function redrawChartViewIfNeeded() {
    if (currentView !== 'chart') return;

    if (isDerivedViewDirty('chart')) {
        requestAnimationFrame(
            refreshChartViewData
        );
        return;
    }

    /*
     * Bei unveränderten Daten muss nur ein sichtbares Canvas
     * nach dem View-Wechsel an seine aktuelle Größe angepasst
     * werden. Statistik/Highlights benötigen kein Re-Render.
     */
    const diagramsActive =
        document.getElementById('stats-diagrams-page')
            ?.classList.contains('active');

    if (diagramsActive) {
        requestAnimationFrame(drawActiveChart);
    }
}

function updateGlobalScrollLockForView() {
    if (currentView === 'filter') {
        // Seite ganz nach oben setzen
        window.scrollTo(0, 0);
        document.documentElement.scrollTop = 0;
        document.body.scrollTop = 0;

        document.body.classList.add('filter-view-lock');
    } else {
        document.body.classList.remove('filter-view-lock');
    }
}

/**
 * Wechselt zu einer View per echter Horizontalbewegung.
 */
function closeAllOpenBoxes() {
    document.querySelectorAll('.box.active').forEach(box => {
        box.classList.remove('active');
        const content = box.querySelector('.box-content');
        if (content) content.style.maxHeight = '0';
    });
}

function goToView(targetView, animate = true) {
    const targetIndex = viewOrder.indexOf(targetView);
    if (targetIndex === -1) return;

    const previousView = currentView;
    const isViewChange = targetView !== currentView;

    if (isViewChange) {
        closeAllOpenBoxes();
    }

    // Alte View kurz anblurren, bevor sie rausslided
    const oldViewEl = document.getElementById(currentView + '-view');
    if (isViewChange && animate && oldViewEl) {
        oldViewEl.classList.add('view-blur-out');
    }

    currentIndex = targetIndex;
    currentView = targetView;

    positionViews(currentIndex, animate, 0);
    updateViewButtons();
    redrawChartViewIfNeeded();
    updateGlobalScrollLockForView();

    if (targetView === 'map') {
        setTimeout(() => {
            if (isDerivedViewDirty('map')) {
                refreshTourMap();
            } else {
                initTourMap();
                requestAnimationFrame(() => {
                    tourMap?.invalidateSize();
                });
            }
        }, 320);
    }

    if (
        targetView === 'dashboard' &&
        isDerivedViewDirty('dashboard')
    ) {
        renderDashboard();
    }

    if (
        targetView === 'filter' &&
        isDerivedViewDirty('filter')
    ) {
        refreshFilterViewData();
    }

    if (
        targetView === 'tour' &&
        isDerivedViewDirty('tour')
    ) {
        loadPlannedTours();
        updatePlannedPeaks();
        markDerivedViewClean('tour');
    }

    if (targetView === 'backup') {
        updateBackupStatusSummary();
    }

    if (targetView === 'achievements') {
                    populateAchievementsYearSelect();
                    renderAchievementsView();
          }

          if (
    targetView === 'wrapped' &&
    (!wrappedCurrentYear || !wrappedSlides.length)
) {
    const years =
        getWrappedAvailableYears();

    if (years.length) {
        wrappedCurrentYear = years[0];
        wrappedSlides =
            buildWrappedSlideData(
                wrappedCurrentYear
            );

        wrappedSlideIndex = 0;
        wrappedPaused = true;

        clearWrappedAutoAdvance();
        populateWrappedYearSelect();
        renderWrappedProgressBar();
        updateWrappedProgressSegments();
        renderWrappedSlide(0);
        updateWrappedPauseButtonLabel();

        attachWrappedPhotos(
            wrappedSlides,
            wrappedCurrentYear
        ).then(() => {
            renderWrappedSlide(wrappedSlideIndex);
        });
    }
}

if (previousView === 'wrapped' && targetView !== 'wrapped') {
    clearWrappedAutoAdvance();
    exitWrappedFullscreenIfActive();
}

    if (isViewChange && animate) {
        // Neue View startet leicht geblurrt und blendet dann scharf ein
        const newViewEl = document.getElementById(targetView + '-view');
        if (newViewEl) {
            newViewEl.classList.add('view-blur-in');
            requestAnimationFrame(() => {
                requestAnimationFrame(() => {
                    newViewEl.classList.remove('view-blur-in');
                });
            });
        }

        // Alte View nach Abschluss der Slide-Transition wieder scharf zurücksetzen
        setTimeout(() => {
            if (oldViewEl) oldViewEl.classList.remove('view-blur-out');
        }, 380);
    }
}

