// ---------- echter Mobile-Swipe mit Finger-Drag ----------

let touchStartX = 0;
let touchStartY = 0;

let touchCurrentX = 0;
let touchCurrentY = 0;

let isDraggingView = false;

let hasHorizontalIntent = false;
let hasVerticalThemeIntent = false;
let hasVerticalIntent = false;

const swipeThresholdPx = 70;
const themeSwipeThresholdPx = 80;

swipeArea.addEventListener('touchstart', (e) => {
    if (window.innerWidth > 900) return;
    if (e.target.closest('#tour-map') || e.target.closest('#year-compare-canvas') || e.target.closest('.modal')) return;

    const t = e.touches[0];

touchStartX = t.clientX;
touchStartY = t.clientY;

touchCurrentX = touchStartX;
touchCurrentY = touchStartY;

isDraggingView = true;

hasHorizontalIntent = false;
hasVerticalIntent = false;
hasVerticalThemeIntent = false;

    Object.values(viewMap).forEach(view => view.classList.add('no-transition'));
}, { passive: true });

swipeArea.addEventListener('touchmove', (e) => {
    if (!isDraggingView || window.innerWidth > 900) return;
    if (e.target.closest('#tour-map') || e.target.closest('#year-compare-canvas') || e.target.closest('.modal')) return;

    const t = e.touches[0];

touchCurrentX = t.clientX;
touchCurrentY = t.clientY;

const deltaX =
    touchCurrentX - touchStartX;

const deltaY =
    touchCurrentY - touchStartY;


/*
 * Richtung eindeutig feststellen.
 *
 * Eine horizontale Bewegung muss deutlich stärker
 * sein als die vertikale Bewegung. Dadurch wird
 * normales Hoch-/Runterscrollen nicht mehr als
 * View-Swipe erkannt.
 */
if (
    !hasHorizontalIntent &&
    !hasVerticalIntent
) {
    const absX = Math.abs(deltaX);
    const absY = Math.abs(deltaY);

    // Kleine Bewegungen noch nicht bewerten
    if (absX < 16 && absY < 16) {
        return;
    }

    // Eindeutig vertikale Bewegung sperrt den View-Swipe
    if (absY > absX * 1.35) {
        hasVerticalIntent = true;

        /*
         * Nur ein Abwärtswischen auf dem Dashboard
         * darf weiterhin das Theme wechseln.
         */
        if (
            currentView === 'dashboard' &&
            deltaY > 0
        ) {
            hasVerticalThemeIntent = true;
            e.preventDefault();
        }

        return;
    }

    // Eindeutig horizontale Bewegung aktiviert den View-Swipe
    if (absX > absY * 1.35) {
        hasHorizontalIntent = true;
    } else {
        // Diagonale Bewegung: keine Ansicht wechseln
        return;
    }
}

/*
 * Vertikale Bewegung niemals horizontal weiterverarbeiten.
 */
if (hasVerticalIntent) {
    return;
}

    // verhindert, dass während horizontalem Swipe die Seite vertikal ruckelt
    e.preventDefault();

    const width = swipeArea.getBoundingClientRect().width || window.innerWidth;
    let dragPercent = (deltaX / width) * 100;

    // am linken/rechten Rand Widerstand einbauen
    if (currentIndex === 0 && dragPercent > 0) {
        dragPercent *= 0.25;
    }

    if (currentIndex === viewOrder.length - 1 && dragPercent < 0) {
        dragPercent *= 0.25;
    }

    positionViews(currentIndex, false, dragPercent);
}, { passive: false });

swipeArea.addEventListener('touchend', (e) => {
    if (!isDraggingView || window.innerWidth > 900) return;
    if (e.target.closest('#tour-map') || e.target.closest('#year-compare-canvas') || e.target.closest('.modal')) return;

    const endTouch =
    e.changedTouches?.[0];

if (endTouch) {
    touchCurrentX = endTouch.clientX;
    touchCurrentY = endTouch.clientY;
}

const deltaX =
    touchCurrentX - touchStartX;

const deltaY =
    touchCurrentY - touchStartY;

    isDraggingView = false;

    Object.values(viewMap).forEach(view => view.classList.remove('no-transition'));

    /*
 * Dashboard Theme-Swipe
 */
if (
    currentView === 'dashboard' &&
    hasVerticalThemeIntent &&
    deltaY >= themeSwipeThresholdPx &&
    Math.abs(deltaY) > Math.abs(deltaX) * 1.25
) {

    hasVerticalThemeIntent = false;
    hasHorizontalIntent = false;

    /*
     * View sicher wieder exakt in Ausgangsposition setzen.
     */
    positionViews(
        currentIndex,
        false,
        0
    );

    if (typeof window.cycleTheme === 'function') {

        const nextTheme =
            window.cycleTheme();

        /*
         * Optionales kurzes Feedback.
         */
        const themeNames = {
            light: 'Hell',
            dark: 'Dunkel',
            green: 'Grün',
            summit: 'Summit'
        };

        if (typeof showToast === 'function') {
            showToast(
                `Theme: ${themeNames[nextTheme] || nextTheme}`,
                {
                    duration: 1200
                }
            );
        }
    }

    return;
}

    /*
 * Bei vertikalem Scrollen niemals eine View wechseln.
 */
if (!hasHorizontalIntent) {
    hasVerticalIntent = false;
    hasVerticalThemeIntent = false;

    positionViews(
        currentIndex,
        false,
        0
    );

    return;
}

let targetIndex = currentIndex;

if (
    Math.abs(deltaX) > swipeThresholdPx &&
    Math.abs(deltaX) > Math.abs(deltaY) * 1.35
) {
    // Finger nach links => nächste View
    if (
        deltaX < 0 &&
        currentIndex < viewOrder.length - 1
    ) {
        targetIndex = currentIndex + 1;
    }

    // Finger nach rechts => vorherige View
    if (
        deltaX > 0 &&
        currentIndex > 0
    ) {
        targetIndex = currentIndex - 1;
    }
}

hasHorizontalIntent = false;
hasVerticalIntent = false;
hasVerticalThemeIntent = false;

const targetView = viewOrder[targetIndex];
goToView(targetView, true);
}, { passive: true });

swipeArea.addEventListener('touchcancel', () => {
    if (!isDraggingView) return;

    isDraggingView = false;
    hasHorizontalIntent = false;
hasVerticalIntent = false;
hasVerticalThemeIntent = false;
    Object.values(viewMap).forEach(view => view.classList.remove('no-transition'));

    goToView(currentView, true);
}, { passive: true });

