function drawSmartBarLabel(ctx, text, x, y, barWidth, barHeight, textColor, intensity = 0) {
    const shortBarThreshold = 32

    ctx.save();
    ctx.fillStyle = textColor;
    ctx.font = '12px Inter, sans-serif';

    if (barHeight < shortBarThreshold) {
        /*
           Kurzer Balken:
           Wert steht oberhalb der Bergspitze,
           aber ebenfalls hochkant.
        */

        const steepness = 0.3 + intensity * 0.7;
        const peakHeight = barHeight * (0.2 + steepness * 0.5);
        const peakRise = peakHeight * (0.5 + steepness);

        const labelX = x + barWidth / 2;
        const labelY = y - peakRise - 0;

        ctx.translate(labelX, labelY);
        ctx.rotate(-Math.PI / 2);

        /*
           textAlign = 'left':
           Der Text startet direkt oberhalb des Balkens
           und läuft nach oben weg.
        */
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';

        ctx.fillText(text, 0, 0);

    } else {
        /*
           Langer Balken:
           Wert bleibt hochkant im Balken.
        */
        ctx.translate(x + barWidth / 2, y + barHeight / 2);
        ctx.rotate(-Math.PI / 2);

        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        ctx.fillText(text, 0, 0);
    }

    ctx.restore();
}

function getChartHorizontalPadding() {
    return (
        window.matchMedia(
            '(max-width: 1024px) and (orientation: landscape) and (pointer: coarse)'
        ).matches
            ? 24
            : 40
    );
}

function drawChartTitleWithTotal(ctx, canvas, title, totalText) {
    const color = getChartTheme().textColor;

    /*
     * Titel etwas klarer,
     * aber schwächer als der Kennwert rechts.
     */
    ctx.font = '600 13px Inter, sans-serif';
    ctx.fillStyle = color;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';

    ctx.fillText(
        title,
        getChartHorizontalPadding(),
        24
    );


    /*
     * Kennwert rechts stärker hervorheben.
     */
    ctx.font = '700 13px Inter, sans-serif';
    ctx.textAlign = 'right';

    ctx.fillText(
        totalText,
        getCanvasLogicalWidth(canvas) - getChartHorizontalPadding(),
        24
    );
}

