const MONTH_NAMES_FULL = [
    'Jänner','Februar','März','April','Mai','Juni',
    'Juli','August','September','Oktober','November','Dezember'
];

function getMonthStats(monthIndex) {
    const sourceData = getDiagramFilteredTours();
    const data = sourceData.filter(entry => {
        if (!entry.date) return false;
        const d = new Date(entry.date);
        return !isNaN(d.getTime()) && d.getMonth() === monthIndex;
    });

    const count = data.length;
    let totalDistance = 0;
    let totalAscent = 0;
    let totalMinutes = 0;
    let totalSteps = 0;

    let totalPeaks = 0;
    let peaks2000 = 0;
    let peaks2500 = 0;
    let peaks3000 = 0;
    let bigTours = 0;
    let gradSum = 0, gradWeight = 0;
    let ascentRateSum = 0, ascentRateWeight = 0;

    data.forEach(entry => {
        const dist = parseFloat(String(entry.strecke  || '').replace(',', '.')) || 0;
        const asc  = parseFloat(String(entry.aufstieg || '').replace(',', '.')) || 0;

        totalDistance += dist;
        totalAscent   += asc;
        totalSteps    += calculateEntrySteps(entry);
        totalPeaks    += parseInt(entry.gipfel) || 0;

        if (entry.zeit && entry.zeit.includes(':')) {
            const [h, m] = entry.zeit.split(':').map(Number);
            if (!isNaN(h) && !isNaN(m)) totalMinutes += h * 60 + m;
        }

        if (isBigTourCountable(entry, sourceData)) bigTours++;

        if (entry.gipfelDetails && Array.isArray(entry.gipfelDetails)) {
            entry.gipfelDetails.forEach(g => {
                const height = parsePeakHeight(g.hoehe);
                if      (height >= 3000)                    peaks3000++;
                else if (height >= 2500 && height <= 2999)  peaks2500++;
                else if (height >= 2000 && height <= 2499)  peaks2000++;
            });
        }

        const ascAdj  = getAdjustedAscent(entry);
        const distAdj = getAdjustedDistance(entry);
        const timeAdj = getAdjustedTimeHours(entry);

        if (distAdj > 0 && ascAdj > 0) { gradSum       += ascAdj / distAdj; gradWeight++;       }
        if (timeAdj > 0 && ascAdj > 0) { ascentRateSum += ascAdj / timeAdj; ascentRateWeight++; }
    });

    const totalHours   = totalMinutes / 60;
    const avgSpeed     = totalHours > 0    ? totalDistance / totalHours             : 0;
    const avgGradient  = gradWeight > 0    ? gradSum       / gradWeight             : 0;
    const avgAscentH   = ascentRateWeight > 0 ? ascentRateSum / ascentRateWeight    : 0;
    const avgDistance  = count > 0 ? totalDistance / count                          : 0;
    const avgAscent    = count > 0 ? Math.round(totalAscent / count)                : 0;
    const avgMin       = count > 0 ? totalMinutes / count                            : 0;

    return {
        count,
        bigTours,

        totalDistance,
        totalAscent,
        totalSteps,

        totalTimeH: Math.floor(totalMinutes / 60),
        totalTimeM: Math.round(totalMinutes % 60),

        totalPeaks,
        peaks2000,
        peaks2500,
        peaks3000,
        avgDistance, avgAscent,
        avgTimeH: Math.floor(avgMin / 60),
        avgTimeM: Math.round(avgMin % 60),
        avgSpeed, avgGradient, avgAscentH
    };
}

function openMonthCategoryModal(type, monthIndex) {
    const modal   = document.getElementById('month-stats-modal');
    const titleEl = document.getElementById('ms-title');
    const bodyEl  = document.getElementById('ms-body');

    if (!modal || !titleEl || !bodyEl) return;

    const monthNames = [
        'Jänner', 'Februar', 'März', 'April', 'Mai', 'Juni',
        'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'
    ];

    const monthName = monthNames[monthIndex] || 'Monat';

    /*
     * Die Diagramme verwenden dieselbe Datenbasis
     * wie die übrigen Diagrammfunktionen.
     */
    const allTours = getDiagramFilteredTours();

    const monthTours = allTours.filter(entry => {
        if (!entry.date) return false;

        const date = new Date(entry.date);

        return !isNaN(date.getTime()) &&
               date.getMonth() === monthIndex;
    });

    const formatNumber = value =>
        Number(value || 0)
            .toLocaleString('de-AT');

    const formatDecimal = (value, decimals = 2) =>
    formatDecimalAT(value, decimals);

    const formatTourName = entry =>
        escapeHtml(entry?.tourname || 'Unbekannte Tour');

    const formatDate = entry =>
        escapeHtml(entry?.date || '–');

    /*
     * Werte pro Tour
     */
    const tourValues = [];

    monthTours.forEach(entry => {
        const distance =
            parseFloat(
                String(entry.strecke || '')
                    .replace(',', '.')
            ) || 0;

        const ascent =
            parseFloat(
                String(entry.aufstieg || '')
                    .replace(',', '.')
            ) || 0;

        const timeHours =
            parseZeitToHours(entry.zeit);

        const steps =
            Number(calculateEntrySteps(entry)) || 0;

        const adjustedDistance =
            getAdjustedDistance(entry);

        const adjustedAscent =
            getAdjustedAscent(entry);

        const adjustedTime =
            getAdjustedTimeHours(entry);

        const speed =
            distance > 0 && timeHours > 0
                ? distance / timeHours
                : 0;

        const gradient =
            adjustedDistance > 0 &&
            adjustedAscent > 0
                ? adjustedAscent / adjustedDistance
                : 0;

        const ascentRate =
            adjustedTime > 0 &&
            adjustedAscent > 0
                ? adjustedAscent / adjustedTime
                : 0;

        const isBigTour =
    isBigTourCountable(
        entry,
        allTours
    );


const bigTourIndex =
    isBigTour
        ? getBigTourIndex(
            entry,
            allTours
        )
        : 0;


const performance =
    calculatePerformanceIndex(
        entry
    );


const performanceScore =
    performance &&
    Number.isFinite(
        performance.score
    )
        ? performance.score
        : null;


tourValues.push({
    entry,
    monthIndex,

    /*
     * Wichtig für den späteren Klick:
     * Index bleibt auf die ursprüngliche
     * monthTours-Liste bezogen.
     */
    tourIndex:
        monthTours.indexOf(entry),

    distance,
    ascent,
    timeHours,
    steps,
    speed,
    gradient,
    ascentRate,

    performanceScore,

    isBigTour,
    bigTourIndex
});
    });

    /*
     * Nur Touren mit gültigem Wert verwenden
     */
    const validValues = key =>
        tourValues.filter(item =>
            Number(item[key]) > 0
        );

    /*
     * Werte je Kategorie
     */
    let title = '';
    let summaryHtml = '';
    let listHtml = '';

    if (type === 'bigTours') {

    const bigTours =
        tourValues
            .filter(
                item => item.isBigTour
            )
            .sort(
                (a, b) =>
                    b.bigTourIndex -
                    a.bigTourIndex
            );

        const totalDistance =
            bigTours.reduce(
                (sum, item) => sum + item.distance,
                0
            );

        const totalAscent =
            bigTours.reduce(
                (sum, item) => sum + item.ascent,
                0
            );

        title = `💪🏼 Big Tours · ${monthName}`;

        summaryHtml = `
            <ul class="stats-list">
                <li>
                    <span class="stats-label">Anzahl Big Tours</span>
                    <span class="stats-value">${bigTours.length}</span>
                </li>
                <li>
                    <span class="stats-label">Gesamtstrecke</span>
                    <span class="stats-value">
                        ${formatDecimal(totalDistance)} km
                    </span>
                </li>
                <li>
                    <span class="stats-label">Gesamtaufstieg</span>
                    <span class="stats-value">
                        ${formatNumber(Math.round(totalAscent))} hm
                    </span>
                </li>
            </ul>
        `;

        listHtml = renderMonthTourRows(
    bigTours,
    item =>
        `Index ${Math.round(
            item.bigTourIndex
        )}`
);
    }

    if (type === 'steps') {
        const entries =
            validValues('steps');

        const totalSteps =
            entries.reduce(
                (sum, item) => sum + item.steps,
                0
            );

        const averageSteps =
            entries.length > 0
                ? totalSteps / entries.length
                : 0;

        title = `👣 Schritte · ${monthName}`;

        summaryHtml = `
            <ul class="stats-list">
                <li>
                    <span class="stats-label">Schritte gesamt</span>
                    <span class="stats-value">
                        ${formatNumber(Math.round(totalSteps))}
                    </span>
                </li>
                <li>
                    <span class="stats-label">Ø Schritte / Tour</span>
                    <span class="stats-value">
                        ${formatNumber(Math.round(averageSteps))}
                    </span>
                </li>
                <li>
                    <span class="stats-label">Touren</span>
                    <span class="stats-value">${entries.length}</span>
                </li>
            </ul>
        `;

        listHtml = renderMonthTourRows(
            entries,
            item =>
                `${formatNumber(Math.round(item.steps))} Schritte`
        );
    }

    if (type === 'avgSteps') {
        const entries =
            validValues('steps');

        const totalSteps =
            entries.reduce(
                (sum, item) => sum + item.steps,
                0
            );

        const averageSteps =
            entries.length > 0
                ? totalSteps / entries.length
                : 0;

        title = `👣 Ø Schritte · ${monthName}`;

        summaryHtml = `
            <ul class="stats-list">
                <li>
                    <span class="stats-label">Ø Schritte / Tour</span>
                    <span class="stats-value">
                        ${formatNumber(Math.round(averageSteps))}
                    </span>
                </li>
                <li>
                    <span class="stats-label">Schritte gesamt</span>
                    <span class="stats-value">
                        ${formatNumber(Math.round(totalSteps))}
                    </span>
                </li>
                <li>
                    <span class="stats-label">Touren</span>
                    <span class="stats-value">${entries.length}</span>
                </li>
            </ul>
        `;

        listHtml = renderMonthTourRows(
            entries,
            item =>
                `${formatNumber(Math.round(item.steps))} Schritte`
        );
    }

    if (type === 'peaks') {
        const entries =
            monthTours.filter(entry =>
                (parseInt(entry.gipfel) || 0) > 0
            );

        const totalPeaks =
            entries.reduce(
                (sum, entry) =>
                    sum + (parseInt(entry.gipfel) || 0),
                0
            );

        const allPeaks = [];

        entries.forEach(entry => {
            (entry.gipfelDetails || []).forEach(peak => {
                const height =
                    parsePeakHeight(peak.hoehe);

                allPeaks.push({
                    name: peak.name || 'Unbenannter Gipfel',
                    height,
                    entry
                });
            });
        });

        allPeaks.sort(
            (a, b) => b.height - a.height
        );

        const highestPeak =
            allPeaks.length > 0
                ? allPeaks[0].height
                : 0;

        title = `🏔️ Gipfel · ${monthName}`;

        summaryHtml = `
            <ul class="stats-list">
                <li>
                    <span class="stats-label">Gipfel gesamt</span>
                    <span class="stats-value">${totalPeaks}</span>
                </li>
                <li>
                    <span class="stats-label">Touren mit Gipfeln</span>
                    <span class="stats-value">${entries.length}</span>
                </li>
                <li>
                    <span class="stats-label">Höchster Gipfel</span>
                    <span class="stats-value">
                        ${highestPeak > 0
                            ? formatNumber(Math.round(highestPeak)) + ' m'
                            : '–'}
                    </span>
                </li>
            </ul>
        `;

        listHtml = allPeaks.length === 0
            ? '<div style="opacity:.7;padding:8px 0;">Keine Gipfel in diesem Monat.</div>'
            : `
                <ul class="stats-list">
                    ${allPeaks.map(peak => `
                        <li
                            class="highlight-clickable"
                            data-month-entry="${monthTours.indexOf(peak.entry)}">

                            <span class="stats-label">
                                ⛰ ${escapeHtml(peak.name)}
                            </span>

                            <span class="stats-value">
                                ${peak.height > 0
                                    ? formatNumber(Math.round(peak.height)) + ' m'
                                    : '–'}
                            </span>
                        </li>
                    `).join('')}
                </ul>
            `;
    }

    if (type === 'performanceIndex') {

    /*
     * Nur Touren verwenden, für die
     * ein Leistungsindex berechnet
     * werden konnte.
     */
    const entries =
        tourValues
            .filter(item =>
                Number.isFinite(
                    item.performanceScore
                )
            )
            .sort(
                (a, b) =>
                    b.performanceScore -
                    a.performanceScore
            );


    const average =
        entries.length > 0
            ? entries.reduce(
                (sum, item) =>
                    sum +
                    item.performanceScore,
                0
            ) / entries.length
            : 0;


    const best =
        entries.length > 0
            ? entries[0]
                .performanceScore
            : 0;


    title =
        `⚡ Leistungsindex · ${monthName}`;


    summaryHtml = `
        <ul class="stats-list">

            <li>
                <span class="stats-label">
                    Ø Leistungsindex
                </span>

                <span class="stats-value">
                    ${
                        entries.length > 0
                            ? Math.round(
                                average
                              ) +
                              ' / 100'
                            : '–'
                    }
                </span>
            </li>


            <li>
                <span class="stats-label">
                    Bester Leistungsindex
                </span>

                <span class="stats-value">
                    ${
                        entries.length > 0
                            ? Math.round(
                                best
                              ) +
                              ' / 100'
                            : '–'
                    }
                </span>
            </li>


            <li>
                <span class="stats-label">
                    Touren
                </span>

                <span class="stats-value">
                    ${entries.length}
                </span>
            </li>

        </ul>
    `;


    /*
     * Bereits absteigend nach
     * Leistungsindex sortiert.
     */
    listHtml =
        renderMonthTourRows(
            entries,
            item =>
                `${Math.round(
                    item.performanceScore
                )} / 100`
        );
}

    if (type === 'speed') {
        const entries =
            validValues('speed');

        const average =
            entries.length > 0
                ? entries.reduce(
                    (sum, item) => sum + item.speed,
                    0
                ) / entries.length
                : 0;

        const fastest =
            entries.length > 0
                ? Math.max(
                    ...entries.map(item => item.speed)
                )
                : 0;

        const slowest =
            entries.length > 0
                ? Math.min(
                    ...entries.map(item => item.speed)
                )
                : 0;

        title = `💨 Ø Geschwindigkeit · ${monthName}`;

        summaryHtml = `
            <ul class="stats-list">
                <li>
                    <span class="stats-label">Durchschnitt</span>
                    <span class="stats-value">
                        ${formatDecimal(average)} km/h
                    </span>
                </li>
                <li>
                    <span class="stats-label">Schnellste Tour</span>
                    <span class="stats-value">
                        ${formatDecimal(fastest)} km/h
                    </span>
                </li>
                <li>
                    <span class="stats-label">Langsamste Tour</span>
                    <span class="stats-value">
                        ${formatDecimal(slowest)} km/h
                    </span>
                </li>
            </ul>
        `;

        listHtml = renderMonthTourRows(
            [...entries].sort(
                (a, b) => b.speed - a.speed
            ),
            item =>
                `${formatDecimal(item.speed)} km/h`
        );
    }

    if (type === 'gradient') {
        const entries =
            validValues('gradient');

        const average =
            entries.length > 0
                ? entries.reduce(
                    (sum, item) => sum + item.gradient,
                    0
                ) / entries.length
                : 0;

        const steepest =
            entries.length > 0
                ? Math.max(
                    ...entries.map(item => item.gradient)
                )
                : 0;

        const flattest =
            entries.length > 0
                ? Math.min(
                    ...entries.map(item => item.gradient)
                )
                : 0;

        title = `📐 Ø Steigung · ${monthName}`;

        summaryHtml = `
            <ul class="stats-list">
                <li>
                    <span class="stats-label">Durchschnitt</span>
                    <span class="stats-value">
                        ${formatNumber(Math.round(average))} hm/km
                    </span>
                </li>
                <li>
                    <span class="stats-label">Steilste Tour</span>
                    <span class="stats-value">
                        ${formatNumber(Math.round(steepest))} hm/km
                    </span>
                </li>
                <li>
                    <span class="stats-label">Flachste Tour</span>
                    <span class="stats-value">
                        ${formatNumber(Math.round(flattest))} hm/km
                    </span>
                </li>
            </ul>
        `;

        listHtml = renderMonthTourRows(
            [...entries].sort(
                (a, b) => b.gradient - a.gradient
            ),
            item =>
                `${formatNumber(Math.round(item.gradient))} hm/km`
        );
    }

    if (type === 'ascentRate') {
        const entries =
            validValues('ascentRate');

        const average =
            entries.length > 0
                ? entries.reduce(
                    (sum, item) => sum + item.ascentRate,
                    0
                ) / entries.length
                : 0;

        const fastest =
            entries.length > 0
                ? Math.max(
                    ...entries.map(item => item.ascentRate)
                )
                : 0;

        const slowest =
            entries.length > 0
                ? Math.min(
                    ...entries.map(item => item.ascentRate)
                )
                : 0;

        title = `⬆️ Ø Anstieg · ${monthName}`;

        summaryHtml = `
            <ul class="stats-list">
                <li>
                    <span class="stats-label">Durchschnitt</span>
                    <span class="stats-value">
                        ${formatNumber(Math.round(average))} hm/h
                    </span>
                </li>
                <li>
                    <span class="stats-label">Schnellster Anstieg</span>
                    <span class="stats-value">
                        ${formatNumber(Math.round(fastest))} hm/h
                    </span>
                </li>
                <li>
                    <span class="stats-label">Langsamster Anstieg</span>
                    <span class="stats-value">
                        ${formatNumber(Math.round(slowest))} hm/h
                    </span>
                </li>
            </ul>
        `;

        listHtml = renderMonthTourRows(
            [...entries].sort(
                (a, b) => b.ascentRate - a.ascentRate
            ),
            item =>
                `${formatNumber(Math.round(item.ascentRate))} hm/h`
        );
    }

    /*
     * Gemeinsame Ausgabe für alle Kategorien
     */
    if (!summaryHtml) {
        title = `${monthName}`;

        summaryHtml = `
            <div style="opacity:.7;padding:8px 0;">
                Für diese Kategorie sind keine Daten vorhanden.
            </div>
        `;
    }

    titleEl.textContent = title;

    bodyEl.innerHTML = `
        ${summaryHtml}
        ${listHtml || ''}
    `;

    /*
     * Touren/Gipfel im Modal anklickbar machen
     */
    bodyEl
        .querySelectorAll('[data-month-entry]')
        .forEach(row => {
            row.addEventListener('click', () => {
                const index =
                    parseInt(row.dataset.monthEntry);

                const entry =
                    monthTours[index];

                if (!entry) return;

                closeMonthStatsModal();

openTourDetail(entry, {
    returnModalId: 'month-stats-modal'
});
            });
        });

    const card =
        modal.querySelector('.modal-card');

    const backdrop =
        modal.querySelector('.modal-backdrop');

    if (card) {
        card.classList.remove('is-dragging');
        card.style.transform = '';
    }

    if (backdrop) {
        backdrop.style.opacity = '';
    }

    attachModalSwipeDown(
        modal,
        closeMonthStatsModal
    );

    modal.classList.remove('hidden');
    document.body.classList.add('modal-open');
}


/*
 * Gemeinsame Liste der Touren für das Kategorien-Modal
 */
function renderMonthTourRows(items, valueFn) {
    if (!items || items.length === 0) {
        return `
            <div style="opacity:.7;padding:8px 0;">
                Keine passenden Touren in diesem Monat.
            </div>
        `;
    }

    return `
        <ul class="stats-list">
            ${items.map(item => `
                <li
                    class="highlight-clickable"
                    data-month-entry="${item.tourIndex}"

                    <span class="stats-label">
                        ${escapeHtml(item.entry.date || '–')} ·
                        ${escapeHtml(item.entry.tourname || 'Unbekannte Tour')}
                    </span>

                    <span class="stats-value">
                        ${valueFn(item)}
                    </span>
                </li>
            `).join('')}
        </ul>
    `;
}

function openMonthStatsModal(monthIndex) {
    const modal   = document.getElementById('month-stats-modal');
    const titleEl = document.getElementById('ms-title');
    const bodyEl  = document.getElementById('ms-body');
    if (!modal || !titleEl || !bodyEl) return;

    const s = getMonthStats(monthIndex);
    titleEl.textContent = MONTH_NAMES_FULL[monthIndex];

    if (s.count === 0) {
        bodyEl.innerHTML = `<div style="opacity:.7; padding:8px 0;">Keine Touren in diesem Monat · anderen Monat oder Jahr wählen.</div>`;
    } else {
        const sub = (label, value) => `
            <li class="stats-sub">
                <span class="stats-label">${label}</span>
                <span class="stats-value">${value}</span>
            </li>`;

        const row = (label, value) => `
            <li>
                <span class="stats-label">${label}</span>
                <span class="stats-value">${value}</span>
            </li>`;

        bodyEl.innerHTML = `<ul class="stats-list">
            ${row('Anzahl Touren',             s.count)}
            ${row('Big Tours (≥10km &amp; ≥1000hm)', s.bigTours)}
            ${row('Gipfel erreicht',           s.totalPeaks)}
            ${s.peaks2000 > 0 ? sub('Gipfel über 2000 m', s.peaks2000) : ''}
            ${s.peaks2500 > 0 ? sub('Gipfel über 2500 m', s.peaks2500) : ''}
            ${s.peaks3000 > 0 ? sub('Gipfel über 3000 m', s.peaks3000) : ''}
            ${row('Gesamtstrecke (km)',        formatDecimalAT(s.totalDistance))}
            ${sub('Ø Strecke (km)',            formatDecimalAT(s.avgDistance))}
            ${row('Gesamtaufstieg (Hm)',       Math.round(s.totalAscent))}
            ${sub('Ø Aufstieg (Hm)',           s.avgAscent)}
            ${row('Gehzeit',                   `${s.totalTimeH}:${String(s.totalTimeM).padStart(2,'0')}`)}
            ${sub('Ø Gehzeit',                 `${s.avgTimeH}:${String(s.avgTimeM).padStart(2,'0')}`)}
            ${row(
                'Schritte gesamt',
                Math.round(s.totalSteps).toLocaleString('de-AT')
            )}
            ${row('Ø Geschwindigkeit (km/h)',   s.avgSpeed.toFixed(2).replace('.', ','))}
            ${row('Ø Steigung (hm/km)',         Math.round(s.avgGradient))}
            ${row('Ø Anstieg (hm/h)',           Math.round(s.avgAscentH))}
        </ul>`;
    }

    const card     = modal.querySelector('.modal-card');
    const backdrop = modal.querySelector('.modal-backdrop');
    if (card)     { card.classList.remove('is-dragging'); card.style.transform = ''; }
    if (backdrop) { backdrop.style.opacity = ''; }

    attachModalSwipeDown(modal, closeMonthStatsModal);
    modal.classList.remove('hidden');
    document.body.classList.add('modal-open');
}

