function dashShiftYear(direction) {
    const yearSel = document.getElementById('dash-year-select');
    if (!yearSel) return;
    const years = Array.from(yearSel.options)
        .map(o => o.value)
        .filter(v => v !== 'all' && v !== 'past')
        .map(Number)
        .sort((a, b) => b - a); // absteigend: neuestes Jahr zuerst
    if (!years.length) return;

    let newVal;
    if (dashYearFilter === 'all' || dashYearFilter === 'past') {
        newVal = direction === 'next' ? years[0] : years[years.length - 1];
    } else {
        const idx = years.indexOf(Number(dashYearFilter));
        if (idx === -1) {
            newVal = years[0];
        } else {
            const newIdx = direction === 'next' ? idx - 1 : idx + 1;
            if (newIdx < 0 || newIdx >= years.length) return; // schon am Rand
            newVal = years[newIdx];
        }
    }
    yearSel.value = String(newVal);
    yearSel.dispatchEvent(new Event('change'));
}

document.getElementById('dash-year-prev-btn')?.addEventListener('click', () => dashShiftYear('prev'));
document.getElementById('dash-year-next-btn')?.addEventListener('click', () => dashShiftYear('next'));

