function initCanvasBarClicks() {
    const msCanvasIds = [
        'ms-dist-canvas',
        'ms-asc-canvas',
        'ms-time-canvas',
        'ms-peaks-canvas'
    ];

    const nonMonthlyCanvasIds = [
        'regions-canvas',
        'scatter-distance-ascent-canvas',
        'scatter-time-ascent-canvas',
        'scatter-time-distance-canvas',
    ];

    const monthCategoryByCanvasId = {
    'big-tours-canvas': 'bigTours',
    'steps-canvas': 'steps',
    'peaks-canvas': 'peaks',
    'performance-index-canvas':
        'performanceIndex',
    'speed-canvas': 'speed',
    'gradient-canvas': 'gradient',
    'ascent-rate-canvas': 'ascentRate',
    'avg-steps-canvas': 'avgSteps'
};

    Object.values(chartCanvasMap).forEach(canvas => {
        if (!canvas) return;
        if (msCanvasIds.includes(canvas.id)) return;
        if (nonMonthlyCanvasIds.includes(canvas.id)) return;

        canvas.addEventListener('click', e => {
            if (
                !canvas.classList.contains(
                    'active-chart-canvas'
                )
            ) {
                return;
            }

            const rect = canvas.getBoundingClientRect();

            const scaleX =
                getCanvasLogicalWidth(canvas) / rect.width;

            const x =
                (e.clientX - rect.left) * scaleX;

            const padding = getChartHorizontalPadding();

            const barStep =
                (getCanvasLogicalWidth(canvas) - padding * 2) / 12;

            const barWidth = barStep - 10;

            for (let i = 0; i < 12; i++) {
                const barStart =
                    padding + i * barStep;

                if (
                    x >= barStart - 3 &&
                    x <= barStart + barWidth + 3
                ) {
                    const category =
    monthCategoryByCanvasId[canvas.id];

if (category) {
    openMonthCategoryModal(category, i);
} else {
    openMonthStatsModal(i);
}

return;
                }
            }
        });
    });

    document
        .getElementById('ms-close')
        ?.addEventListener(
            'click',
            closeMonthStatsModal
        );

    document
        .getElementById('month-stats-modal')
        ?.addEventListener('click', e => {
            if (
                e.target.matches(
                    '[data-month-close="1"]'
                )
            ) {
                closeMonthStatsModal();
            }
        });

    document
        .getElementById('stats-chart-modal-close')
        ?.addEventListener(
            'click',
            closeStatsChartModal
        );

    document
        .getElementById('stats-chart-modal')
        ?.addEventListener('click', e => {
            if (
                e.target.matches(
                    '[data-stats-chart-close="1"]'
                )
            ) {
                closeStatsChartModal();
            }
        });
}

function openTourListModal(title, tours) {
    const modal   = document.getElementById('tour-list-modal');
    const titleEl = document.getElementById('tl-title');
    const bodyEl  = document.getElementById('tl-body');
    if (!modal || !titleEl || !bodyEl) return;

    titleEl.textContent = title;

    const sorted = sortEntries([...tours]);

    if (sorted.length === 0) {
        bodyEl.innerHTML = '<div style="opacity:.7; padding:8px 0;">Keine Touren gefunden · Filter oder Suchbegriff ändern.</div>';
    } else {
        const ul = document.createElement('ul');
        ul.className = 'tour-list';

        sorted.forEach((entry, index) => {
            const li = document.createElement('li');
            li.innerHTML = `
                <span class="tour-nr">${index + 1}.</span>
                <span class="tour-date">${entry.date || '–'}</span>
                <span class="tour-name">${escapeHtml(entry.tourname || 'Unbekannt')}</span>
            `;
            li.style.cursor = 'pointer';
            li.addEventListener('click', () => {
    closeTourListModal();

    openTourDetail(entry, {
        returnModalId: 'tour-list-modal'
    });
});
            ul.appendChild(li);
        });

        bodyEl.innerHTML = '';
        bodyEl.appendChild(ul);
    }

    const card     = modal.querySelector('.modal-card');
    const backdrop = modal.querySelector('.modal-backdrop');
    if (card)     { card.classList.remove('is-dragging'); card.style.transform = ''; }
    if (backdrop) { backdrop.style.opacity = ''; }

    attachModalSwipeDown(modal, closeTourListModal);
    modal.classList.remove('hidden');
    document.body.classList.add('modal-open');
}

