function populateYearCompareButtons(years) {
    const container = document.getElementById('yc-year-buttons');
    if (!container) return;

    const selected = diagramFilterState.selectedYears || [];
    container.innerHTML = '';

    // "Alle Jahre" Toggle-Chip
    const allBtn = document.createElement('button');
    allBtn.type = 'button';
    const allSelected = years.length > 0 && years.every(y => selected.includes(y));
    allBtn.className =
    'yc-year-toggle-btn yc-year-all-btn' +
    (allSelected ? ' active' : '');
    allBtn.textContent = 'Alle Jahre';

    allBtn.addEventListener('click', () => {
        const currentlyAll = years.length > 0 && years.every(y => (diagramFilterState.selectedYears || []).includes(y));
        diagramFilterState.selectedYears = currentlyAll ? [] : [...years].sort((a, b) => a - b);
        saveDiagramFilterState();

        populateYearCompareButtons(years);

        redrawInlineYearCompareIfVisible();

    });

    container.appendChild(allBtn);

    years.forEach(year => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'yc-year-toggle-btn' + (selected.includes(year) ? ' active' : '');
        btn.textContent = String(year);

        btn.addEventListener('click', () => {
            let sel = [...(diagramFilterState.selectedYears || [])];

            if (sel.includes(year)) {
                sel = sel.filter(y => y !== year);
            } else {
                sel.push(year);
                sel.sort((a, b) => a - b);
            }

            diagramFilterState.selectedYears = sel;
            saveDiagramFilterState();

            populateYearCompareButtons(years);

            redrawInlineYearCompareIfVisible();

        });

        container.appendChild(btn);
    });
}

const YC_METRIC_ORDER = [
    'tours',
    'bigTours',
    'peaks',
    'distance',
    'avgDistance',
    'ascent',
    'avgAscent',
    'time',
    'avgTime',
    'steps',
    'avgSteps',
    'performance',
    'speed',
    'gradient',
    'ascentRate'
];

function shiftYearCompareMetric(direction) {
    const idx = YC_METRIC_ORDER.indexOf(yearCompareMetric);
    const newIdx = (idx + direction + YC_METRIC_ORDER.length) % YC_METRIC_ORDER.length;
    yearCompareMetric = YC_METRIC_ORDER[newIdx];

    const sel = document.getElementById('yc-metric-select');
    if (sel) sel.value = yearCompareMetric;

    requestAnimationFrame(drawYearCompareDiagram);
}

function initYearCompareSwipe() {
    const canvas = document.getElementById('year-compare-canvas');
    if (!canvas || canvas.dataset.swipeInit === '1') return;
    canvas.dataset.swipeInit = '1';

    let startX = 0, startY = 0, tracking = false;
    const SWIPE_THRESHOLD = 50;

    canvas.addEventListener('touchstart', (e) => {
        const inline =
    document.getElementById(
        'year-compare-inline'
    );

if (
    !inline ||
    inline.classList.contains(
        'hidden'
    )
) {
    return;
}
        const t = e.touches[0];
        startX = t.clientX;
        startY = t.clientY;
        tracking = true;
    }, { passive: true });

    canvas.addEventListener('touchend', (e) => {
        if (!tracking) return;
        tracking = false;
        const inline =
    document.getElementById(
        'year-compare-inline'
    );

if (
    !inline ||
    inline.classList.contains(
        'hidden'
    )
) {
    return;
}

        const t = e.changedTouches[0];
        const dx = t.clientX - startX;
        const dy = t.clientY - startY;

        if (Math.abs(dx) > SWIPE_THRESHOLD && Math.abs(dx) > Math.abs(dy)) {
            shiftYearCompareMetric(dx < 0 ? 1 : -1);
        }
    }, { passive: true });
}

document.getElementById('yc-metric-prev-btn')?.addEventListener('click', () => shiftYearCompareMetric(-1));
document.getElementById('yc-metric-next-btn')?.addEventListener('click', () => shiftYearCompareMetric(1));



function getYearCompareGradientStops(year, years) {
    const currentYear = new Date().getFullYear();
    const numericYear = Number(year);

    /*
     * Das aktuelle Jahr bleibt immer in der
     * aktuellen Farbe des Themes.
     */
    if (numericYear === currentYear) {
        return getChartTheme().gradientStops;
    }

    /*
     * Die übrigen Jahre werden nach ihrer tatsächlichen
     * Jahreszahl sortiert und nicht nach ihrer aktuellen
     * Position im Diagramm.
     */
    const otherYears = years
        .map(Number)
        .filter(y => y !== currentYear)
        .sort((a, b) => a - b);

    const rank = otherYears.indexOf(numericYear);

    /*
     * Vergleichsfarben 1 bis 4 verwenden.
     * Die Theme-Grundfarbe 0 wird dadurch übersprungen.
     */
    const colorIndex =
        rank >= 0
            ? 1 + (rank % 4)
            : 1;

    return getYearGradientStops(colorIndex);
}

function getYearCompareYAxisConfig(values, metric) {
    const maxDataValue = Math.max(
        ...values.map(value => Number(value) || 0),
        0
    );

    let baseStep = 1;

    switch (metric) {
        case 'distance':
        case 'avgDistance':
            baseStep = 5;
            break;

        case 'ascent':
        case 'avgAscent':
            baseStep = 250;
            break;

        case 'time':
        case 'avgTime':
            // Jahresvergleichszeit wird in Stunden gespeichert
            baseStep = 1;
            break;

        case 'performance':
            baseStep = 20;
            break;

        case 'speed':
            baseStep = 1;
            break;

        case 'gradient':
            baseStep = 25;
            break;

        case 'ascentRate':
            baseStep = 50;
            break;

        case 'steps':
            baseStep = 10000;
            break;

        case 'avgSteps':
            baseStep = 2000;
            break;

        case 'tours':
        case 'bigTours':
        case 'peaks':
        default:
            baseStep = 1;
            break;
    }

    /*
     * Sechs Linien insgesamt:
     *
     * 0
     * 1 × step
     * 2 × step
     * 3 × step
     * 4 × step
     * 5 × step
     */
    let step = baseStep;

    while (maxDataValue > step * 5) {
        step *= 2;
    }

    return {
        step,
        maxValue: step * 5
    };
}

function drawYearCompareDiagram() {
    const canvas =
        document.getElementById('year-compare-canvas');

    if (!canvas) return;

    const ctx = resizeCanvasToDisplaySize(canvas);

    const allData =
        getDiagramFilteredToursIgnoringYear();

    const { isDark, textColor } = getChartTheme();

    ctx.clearRect(0, 0, getCanvasLogicalWidth(canvas), getCanvasLogicalHeight(canvas));

    /*
     * Vorhandene Jahre ermitteln
     */
    const yearSet = new Set();

    allData.forEach(entry => {
        if (!entry.date) return;

        const date = new Date(entry.date);

        if (!isNaN(date.getTime())) {
            yearSet.add(date.getFullYear());
        }
    });

    /*
     * Ausgewählte Jahre berücksichtigen.
     * Dabei werden Zahlen und Strings gleich behandelt.
     */
    const selectedYears =
        diagramFilterState.selectedYears || [];

    const years = selectedYears.length > 0
        ? Array.from(yearSet)
            .filter(year =>
                selectedYears.some(selected =>
                    Number(selected) === Number(year)
                )
            )
            .sort((a, b) => a - b)
        : Array.from(yearSet)
            .sort((a, b) => a - b)
            .slice(-5);

    if (years.length === 0) {
        ctx.fillStyle = textColor;
        ctx.font = '14px Inter, sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        ctx.fillText(
            'Keine Daten · Jahr oder Filter ändern',
            getCanvasLogicalWidth(canvas) / 2,
            getCanvasLogicalHeight(canvas) / 2
        );

        return;
    }

    /*
     * Monatsdaten vorbereiten
     */
    const yearData = {};
const yearDataCount = {};
const yearSpeedDistance = {};
const yearSpeedHours = {};

/*
 * Mehrtagestouren bei "Anzahl Touren"
 * nur einmal zählen.
 */
const countedTourGroups = new Set();

    years.forEach(year => {
        yearData[year] = Array(12).fill(0);
        yearDataCount[year] = Array(12).fill(0);
        yearSpeedDistance[year] = Array(12).fill(0);
        yearSpeedHours[year] = Array(12).fill(0);
    });

    /*
     * Werte je Jahr und Monat berechnen
     */
    allData.forEach(entry => {
        if (!entry.date) return;

        const date = new Date(entry.date);

        if (isNaN(date.getTime())) return;

        const year = date.getFullYear();
        const month = date.getMonth();

        if (!yearData[year]) return;

        const distance =
            parseFloat(
                String(entry.strecke || '')
                    .replace(',', '.')
            ) || 0;

        const ascent =
            parseFloat(
                String(entry.aufstieg || '')
                    .replace(',', '.')
            ) || 0;

        const steps =
            Number(calculateEntrySteps(entry)) || 0;

        let timeMinutes = 0;

        if (
            entry.zeit &&
            String(entry.zeit).includes(':')
        ) {
            const [hours, minutes] =
                String(entry.zeit)
                    .split(':')
                    .map(Number);

            if (
                Number.isFinite(hours) &&
                Number.isFinite(minutes)
            ) {
                timeMinutes =
                    hours * 60 + minutes;
            }
        }

        const timeHours =
            timeMinutes / 60;

        const adjustedDistance =
            getAdjustedDistance(entry);

        const adjustedAscent =
            getAdjustedAscent(entry);

        const adjustedTime =
            getAdjustedTimeHours(entry);

        const speed =
            distance > 0 && timeHours > 0
                ? distance / timeHours
                : 0;

        const gradient =
            adjustedDistance > 0 &&
            adjustedAscent > 0
                ? adjustedAscent / adjustedDistance
                : 0;

        const ascentRate =
            adjustedTime > 0 &&
            adjustedAscent > 0
                ? adjustedAscent / adjustedTime
                : 0;

        const performance = calculatePerformanceIndex(entry);
        const performanceScore =
            performance && Number.isFinite(performance.score)
                ? Number(performance.score)
                : null;

        switch (yearCompareMetric) {
            case 'tours':

    /*
     * Normale Tagestour:
     * immer zählen.
     */
    if (!entry.tourGroup) {
        yearData[year][month] += 1;
        break;
    }


    /*
     * Mehrtagestour:
     * nur die erste Etappe zählt
     * als eigentliche Tour.
     */
    if (
        !isFirstEtappeInList(
            entry,
            allData
        )
    ) {
        break;
    }


    /*
     * Zusätzliche Absicherung:
     * dieselbe Tourgruppe niemals
     * zweimal zählen.
     */
    const tourGroupKey =
        String(entry.tourGroup)
            .trim();

    if (
        countedTourGroups.has(
            tourGroupKey
        )
    ) {
        break;
    }

    countedTourGroups.add(
        tourGroupKey
    );

    yearData[year][month] += 1;

    break;

            case 'distance':
                yearData[year][month] += distance;
                break;

            case 'ascent':
                yearData[year][month] += ascent;
                break;

            case 'time':
                yearData[year][month] += timeHours;
                break;

            case 'performance':
                if (performanceScore !== null) {
                    yearData[year][month] += performanceScore;
                    yearDataCount[year][month]++;
                }
                break;

            case 'speed':
                if (distance > 0 && timeHours > 0) {
                    yearSpeedDistance[year][month] += distance;
                    yearSpeedHours[year][month] += timeHours;
                }
                break;

            case 'gradient':
                if (gradient > 0) {
                    yearData[year][month] += gradient;
                    yearDataCount[year][month]++;
                }
                break;

            case 'ascentRate':
                if (ascentRate > 0) {
                    yearData[year][month] += ascentRate;
                    yearDataCount[year][month]++;
                }
                break;

            case 'steps':
                yearData[year][month] += steps;
                break;

            case 'avgSteps':
                if (steps > 0) {
                    yearData[year][month] += steps;
                    yearDataCount[year][month]++;
                }
                break;

            case 'bigTours':
                if (isBigTourCountable(entry, allData)) {
                    yearData[year][month] += 1;
                }
                break;

            case 'avgDistance':
                if (distance > 0) {
                    yearData[year][month] += distance;
                    yearDataCount[year][month]++;
                }
                break;

            case 'avgAscent':
                if (String(entry.aufstieg ?? '').trim() !== '') {
                    yearData[year][month] += ascent;
                    yearDataCount[year][month]++;
                }
                break;

            case 'avgTime':
                if (timeHours > 0) {
                    yearData[year][month] += timeHours;
                    yearDataCount[year][month]++;
                }
                break;

            case 'peaks':
                yearData[year][month] +=
                    parseInt(entry.gipfel) || 0;
                break;
        }
    });

    /*
     * Durchschnittswerte berechnen
     */
    if (
    [
        'avgDistance',
        'avgAscent',
        'avgTime',
        'performance',
        'gradient',
        'ascentRate',
        'avgSteps'
    ].includes(yearCompareMetric)
) {
        years.forEach(year => {
            for (let month = 0; month < 12; month++) {
                const count =
                    yearDataCount[year][month];

                yearData[year][month] =
                    count > 0
                        ? yearData[year][month] / count
                        : 0;
            }
        });
    }

    if (yearCompareMetric === 'speed') {
        years.forEach(year => {
            for (let month = 0; month < 12; month++) {
                const hours = yearSpeedHours[year][month];
                yearData[year][month] = hours > 0
                    ? yearSpeedDistance[year][month] / hours
                    : 0;
            }
        });
    }

    /*
     * Beschriftungen
     */
    const metricLabels = {
        tours:       'Anzahl Touren',
        bigTours:    'Big Tours',
        peaks:       'Gipfel gesamt',
        distance:    'Strecke gesamt (km)',
        avgDistance: 'Ø Strecke (km)',
        ascent:      'Aufstieg gesamt (hm)',
        avgAscent:   'Ø Aufstieg (hm)',
        time:        'Gehzeit gesamt (h)',
        avgTime:     'Ø Gehzeit (h)',
        steps:       'Schritte gesamt',
        avgSteps:    'Ø Schritte',
        performance: 'Ø Leistungsindex',
        speed:       'Ø Geschwindigkeit (km/h)',
        gradient:    'Ø Steigung (hm/km)',
        ascentRate:  'Ø Anstieg (hm/h)'
    };

    /*
     * Diagrammfläche
     */
    const padding = 52;
    const legendHeight = 24;
    const paddingTop = 32 + legendHeight;
    const paddingBottom = 40;

    const chartWidth =
        getCanvasLogicalWidth(canvas) - padding * 2;

    const chartHeight =
        getCanvasLogicalHeight(canvas) -
        paddingBottom -
        paddingTop;

    const stepX =
        chartWidth / 11;

    /*
     * Y-Achse mit geraden Werten:
     * 0 plus fünf weitere Hilfslinien
     */
    const allYearValues =
        years.flatMap(year => yearData[year]);

    const yAxisConfig =
        getYearCompareYAxisConfig(
            allYearValues,
            yearCompareMetric
        );

    const maxValue = Math.max(
        1,
        Number(yAxisConfig?.maxValue) || 1
    );

    const yStep = Math.max(
        1,
        Number(yAxisConfig?.step) || 1
    );

    const xForMonth = month =>
        padding + month * stepX;

    const yForValue = value =>
        paddingTop +
        chartHeight -
        (value / maxValue) * chartHeight;

    /*
     * Titel
     */
    ctx.fillStyle = textColor;
    ctx.font = '13px Inter, sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';

    ctx.fillText(
        `Jahresvergleich · ${metricLabels[yearCompareMetric] || ''}`,
        padding,
        22
    );

    /*
     * Farblegende
     */
    const legendItemWidth = 58;

    let legendX =
        padding +
        chartWidth / 2 -
        (years.length * legendItemWidth) / 2;

    const legendY =
        14 + legendHeight / 2 + 6;

    years.forEach(year => {
        const stops =
            getYearCompareGradientStops(
                year,
                years
            );

        const legendGradient =
            ctx.createLinearGradient(
                legendX,
                0,
                legendX + 14,
                0
            );

        stops.forEach(([stop, colour]) => {
            legendGradient.addColorStop(
                stop,
                colour
            );
        });

        ctx.strokeStyle = legendGradient;
        ctx.lineWidth = 2;
        ctx.setLineDash([]);

        ctx.beginPath();
        ctx.moveTo(legendX, legendY);
        ctx.lineTo(legendX + 14, legendY);
        ctx.stroke();

        ctx.fillStyle =
            stops[stops.length - 1][1];

        ctx.beginPath();
        ctx.arc(
            legendX + 7,
            legendY,
            3,
            0,
            Math.PI * 2
        );
        ctx.fill();

        ctx.fillStyle = textColor;
        ctx.font = '11px Inter, sans-serif';
        ctx.textAlign = 'left';
        ctx.textBaseline = 'alphabetic';

        ctx.fillText(
            String(year),
            legendX + 19,
            legendY + 4
        );

        legendX += legendItemWidth;
    });

    /*
     * Y-Achsenformat
     */
    const formatYAxisValue = value => {
        if (
            [
                'time',
                'avgTime'
            ].includes(yearCompareMetric)
        ) {
            const hours = Math.floor(value);

            const minutes = Math.round(
                (value - hours) * 60
            );

            return `${hours}:${String(minutes).padStart(2, '0')}`;
        }

        if (
            [
                'tours',
                'bigTours',
                'peaks',
                'steps',
                'avgSteps'
            ].includes(yearCompareMetric)
        ) {
            return Math.round(value)
                .toLocaleString('de-AT');
        }

        if (value === 0) {
            return '0';
        }

        if (value >= 10000) {
            return `${Math.round(value / 1000)}k`;
        }

        if (value >= 1000) {
    return (
        formatDecimalAT(value / 1000) +
        'k'
    );
}

        return value % 1 === 0
    ? String(Math.round(value))
    : formatDecimalAT(value);
    };

    /*
     * Genau sechs horizontale Hilfslinien:
     * 0 plus fünf gerade Stufen
     */
    for (let i = 0; i <= 5; i++) {
        const value = i * yStep;
        const y = yForValue(value);

        ctx.strokeStyle =
            isDark
                ? 'rgba(214,225,240,0.20)'
                : 'rgba(46,64,54,0.10)';

        ctx.lineWidth = 1;
        ctx.setLineDash([3, 5]);

        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(
            getCanvasLogicalWidth(canvas) - padding,
            y
        );
        ctx.stroke();

        ctx.fillStyle = textColor;
        ctx.font = '10px Inter, sans-serif';
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';

        ctx.fillText(
            formatYAxisValue(value),
            padding - 7,
            y
        );
    }

    ctx.setLineDash([]);

    /*
     * Grundlinie
     */
    ctx.strokeStyle =
        isDark
            ? '#d6e1f030'
            : '#2e403630';

    ctx.lineWidth = 1;

    ctx.beginPath();
    ctx.moveTo(
        padding,
        paddingTop + chartHeight
    );
    ctx.lineTo(
        getCanvasLogicalWidth(canvas) - padding,
        paddingTop + chartHeight
    );
    ctx.stroke();

    /*
     * Monatsbeschriftungen
     */
    const monthLabels = [
        'J', 'F', 'M', 'A', 'M', 'J',
        'J', 'A', 'S', 'O', 'N', 'D'
    ];

    monthLabels.forEach((label, month) => {
        ctx.fillStyle = textColor;
        ctx.font = '12px Inter, sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'alphabetic';

        ctx.fillText(
            label,
            xForMonth(month),
            getCanvasLogicalHeight(canvas) - paddingBottom + 18
        );
    });

    /*
     * Linien und Punkte pro Jahr
     */
    years.forEach(year => {
        const stops =
            getYearCompareGradientStops(
                year,
                years
            );

        const values =
            yearData[year];

        const lastActiveMonth =
            values.reduce(
                (last, value, month) =>
                    value > 0 ? month : last,
                -1
            );

        if (lastActiveMonth < 0) {
            return;
        }

        const lineGradient =
            ctx.createLinearGradient(
                padding,
                0,
                getCanvasLogicalWidth(canvas) - padding,
                0
            );

        stops.forEach(([stop, colour]) => {
            lineGradient.addColorStop(
                stop,
                colour
            );
        });

        /*
         * Datenfläche
         */
        ctx.beginPath();

        for (
            let month = 0;
            month <= lastActiveMonth;
            month++
        ) {
            const x = xForMonth(month);
            const y = yForValue(values[month]);

            if (month === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
        }

        ctx.lineTo(
            xForMonth(lastActiveMonth),
            paddingTop + chartHeight
        );

        ctx.lineTo(
            xForMonth(0),
            paddingTop + chartHeight
        );

        ctx.closePath();

        const areaGradient =
            ctx.createLinearGradient(
                0,
                paddingTop,
                0,
                paddingTop + chartHeight
            );

        stops.forEach(([stop, colour]) => {
            /*
             * Hex-Farben erhalten eine dezente Transparenz.
             */
            if (
                typeof colour === 'string' &&
                colour.startsWith('#') &&
                colour.length === 7
            ) {
                areaGradient.addColorStop(
                    stop,
                    `${colour}22`
                );
            } else {
                areaGradient.addColorStop(
                    stop,
                    colour
                );
            }
        });

        ctx.fillStyle = areaGradient;
        ctx.fill();

        /*
         * Linie
         */
        ctx.strokeStyle = lineGradient;
        ctx.lineWidth = 2.5;
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';
        ctx.setLineDash([]);

        ctx.beginPath();

        for (
            let month = 0;
            month <= lastActiveMonth;
            month++
        ) {
            const x = xForMonth(month);
            const y = yForValue(values[month]);

            if (month === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
        }

        ctx.stroke();

        /*
         * Punkte
         */
        const dotColour =
            stops[stops.length - 1][1];

        for (
            let month = 0;
            month <= lastActiveMonth;
            month++
        ) {
            const value = values[month];

            if (value <= 0) continue;

            const x = xForMonth(month);
            const y = yForValue(value);

            ctx.fillStyle =
                getChartTheme().dotFill;

            ctx.beginPath();
            ctx.arc(
                x,
                y,
                4.5,
                0,
                Math.PI * 2
            );
            ctx.fill();

            ctx.fillStyle = dotColour;

            ctx.beginPath();
            ctx.arc(
                x,
                y,
                3,
                0,
                Math.PI * 2
            );
            ctx.fill();
        }
    });
}

