function getAllAchievementBadgeDefs() {
    return Object.values(ACHIEVEMENT_CATEGORIES).flatMap(cat => cat.badges);
}

function computeLongestMonthStreak(entries) {
    const monthSet = new Set();

    entries.forEach(entry => {
        const date = parseStatsCalendarDate(entry?.date);
        if (date) monthSet.add(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`);
    });

    const sortedMonths = [...monthSet].sort();
    let longest = 0, current = 0, prevKey = null;

    sortedMonths.forEach(key => {
        const [y, m] = key.split('-').map(Number);
        if (prevKey) {
            const [py, pm] = prevKey.split('-').map(Number);
            const isConsecutive = (py === y && pm === m - 1) || (y === py + 1 && pm === 12 && m === 1);
            current = isConsecutive ? current + 1 : 1;
        } else {
            current = 1;
        }
        longest = Math.max(longest, current);
        prevKey = key;
    });

    return longest;
}

function computeFullYearActive(entries) {
    const yearMonths = {};

    entries.forEach(entry => {
        const date = parseStatsCalendarDate(entry?.date);
        if (!date) return;
        const y = date.getFullYear();
        if (!yearMonths[y]) yearMonths[y] = new Set();
        yearMonths[y].add(date.getMonth());
    });

    return Object.values(yearMonths).some(months => months.size === 12);
}

function computePerformanceRecordHistory(entries) {
    const sorted = [...entries]
        .filter(e => e.date)
        .sort((a, b) => new Date(a.date) - new Date(b.date));

    let maxScore = -Infinity;
    const records = [];

    sorted.forEach(entry => {
        const perf = calculatePerformanceIndex(entry);
        const score = perf && Number.isFinite(perf.score) ? perf.score : null;
        if (score !== null && score > maxScore) {
            maxScore = score;
            records.push({
    id: entry.id,
    date: entry.date,
    tourname: entry.tourname || '–',
    entry,
    score
});
        }
    });

    return { records, maxScore: maxScore === -Infinity ? 0 : maxScore };
}

function computeAllAchievements(toursInput = null) {
    const allTours = toursInput ?? (appStorage.get('touren') || []);
    const ms = computeMilestones(allTours);
    const results = {};

    ['dist', 'asc', 'time', 'peaks', 'steps'].forEach((msKey, i) => {
        const catId = ['distance', 'ascent', 'time', 'peaks', 'steps'][i];
        const msData = ms[msKey];
        ACHIEVEMENT_CATEGORIES[catId].badges.forEach(badge => {
            const reachedItem = msData.reached.find(r => r.milestone === badge.threshold);
            results[badge.id] = {
                unlocked: !!reachedItem,
                unlockedAt: reachedItem?.date || null,
                unlockedTour: reachedItem?.tourname || null,
       unlockedTourId: reachedItem?.entry?.id || null,
       progressCurrent: msData.total,
                progressTarget: badge.threshold
            };
        });
    });

    const sortedByDate = [...allTours].filter(e => e.date).sort((a, b) => new Date(a.date) - new Date(b.date));

    ACHIEVEMENT_CATEGORIES.tourCount.badges.forEach(badge => {
        const reachedAt = sortedByDate[badge.threshold - 1];

results[badge.id] = {
    unlocked: allTours.length >= badge.threshold,
    unlockedAt: reachedAt?.date || null,
    unlockedTour: reachedAt?.tourname || null,
    unlockedTourId: reachedAt?.id || null,
    progressCurrent: allTours.length,
    progressTarget: badge.threshold
};
    });

    const bigTours = sortedByDate.filter(e => {
        const d = parseFloat(String(e.strecke || '').replace(',', '.')) || 0;
        const a = parseFloat(String(e.aufstieg || '').replace(',', '.')) || 0;
        return d >= 10 && a >= 1000;
    });
    ACHIEVEMENT_CATEGORIES.bigTours.badges.forEach(badge => {
        const reachedAt = bigTours[badge.threshold - 1];

results[badge.id] = {
    unlocked: bigTours.length >= badge.threshold,
    unlockedAt: reachedAt?.date || null,
    unlockedTour: reachedAt?.tourname || null,
    unlockedTourId: reachedAt?.id || null,
    progressCurrent: bigTours.length,
    progressTarget: badge.threshold
};
    });

    const peakFirstSeen = new Map();
    sortedByDate.forEach(entry => {
        (entry.gipfelDetails || []).forEach(g => {
            const name = (g?.name || '').trim();
            if (name && !peakFirstSeen.has(name)) {
                peakFirstSeen.set(name, {
    id: entry.id,
    date: entry.date,
    tourname: entry.tourname
});
            }
        });
    });
    const uniquePeakEntries = [...peakFirstSeen.values()].sort((a, b) => new Date(a.date) - new Date(b.date));
    ACHIEVEMENT_CATEGORIES.uniquePeaks.badges.forEach(badge => {
        const reachedAt = uniquePeakEntries[badge.threshold - 1];
        results[badge.id] = {
            unlocked: peakFirstSeen.size >= badge.threshold,
            unlockedAt: reachedAt?.date || null,
            unlockedTour: reachedAt?.tourname || null,
unlockedTourId: reachedAt?.id || null,
progressCurrent: peakFirstSeen.size,
            progressTarget: badge.threshold
        };
    });

    const peakHeightEvents = [];
    sortedByDate.forEach(entry => {
        (entry.gipfelDetails || []).forEach(g => {
            const height = parsePeakHeight(g?.hoehe);
            if (height > 0) {
    peakHeightEvents.push({
        height,
        id: entry.id,
        date: entry.date,
        tourname: entry.tourname
    });
}
        });
    });
    ACHIEVEMENT_CATEGORIES.peakHeight.badges.forEach(badge => {
        const match = peakHeightEvents.find(p => p.height >= badge.threshold);
        results[badge.id] = {
            unlocked: !!match,
            unlockedAt: match?.date || null,
            unlockedTour: match?.tourname || null,
            unlockedTourId: match?.id || null,
            progressCurrent: peakHeightEvents.length ? Math.max(...peakHeightEvents.map(p => p.height)) : 0,
            progressTarget: badge.threshold
        };
    });

    const regionFirstSeen = new Map();
sortedByDate.forEach(entry => {
    const rawRegion = String(entry?.region || '').trim();
    if (rawRegion && !regionFirstSeen.has(rawRegion)) {
        regionFirstSeen.set(rawRegion, {
    id: entry.id,
    date: entry.date,
    tourname: entry.tourname
});
    }
});
    const regionEntries = [...regionFirstSeen.values()].sort((a, b) => new Date(a.date) - new Date(b.date));
    ACHIEVEMENT_CATEGORIES.regions.badges.forEach(badge => {
        const reachedAt = regionEntries[badge.threshold - 1];
        results[badge.id] = {
            unlocked: regionFirstSeen.size >= badge.threshold,
            unlockedAt: reachedAt?.date || null,
            unlockedTour: reachedAt?.tourname || null,
unlockedTourId: reachedAt?.id || null,
progressCurrent: regionFirstSeen.size,
            progressTarget: badge.threshold
        };
    });

    const typeFirstSeen = {};
    sortedByDate.forEach(entry => {
        const val = entry.difficulty;
        if (val && !typeFirstSeen[val]) typeFirstSeen[val] = {
    id: entry.id,
    date: entry.date,
    tourname: entry.tourname
};
    });

    ACHIEVEMENT_CATEGORIES.tourTypes.badges.forEach(badge => {
        if (badge.isAllrounder) {
            const requiredTypes = ['wandern', 'Klettersteig', 'Radtour', 'Hike & Climb', 'Bike & Hike'];
            const allPresent = requiredTypes.every(t => typeFirstSeen[t]);
            const lastNeeded = allPresent
                ? requiredTypes.map(t => typeFirstSeen[t]).sort((a, b) => new Date(b.date) - new Date(a.date))[0]
                : null;
            results[badge.id] = {
                unlocked: allPresent,
                unlockedAt: lastNeeded?.date || null,
                unlockedTour: lastNeeded?.tourname || null,
unlockedTourId: lastNeeded?.id || null,
                progressCurrent: requiredTypes.filter(t => typeFirstSeen[t]).length,
                progressTarget: requiredTypes.length
            };
        } else {
            const match = typeFirstSeen[badge.matchValue];
            results[badge.id] = {
                unlocked: !!match,
                unlockedAt: match?.date || null,
                unlockedTour: match?.tourname || null,
unlockedTourId: match?.id || null,
                progressCurrent: match ? 1 : 0,
                progressTarget: 1
            };
        }
    });

    const longestStreak = computeLongestMonthStreak(allTours);
    ACHIEVEMENT_CATEGORIES.consistency.badges.forEach(badge => {
        if (badge.isFullYear) {
            const achieved = computeFullYearActive(allTours);
            results[badge.id] = {
                unlocked: achieved,
                unlockedAt: null,
                unlockedTour: null,
                progressCurrent: achieved ? 1 : 0,
                progressTarget: 1
            };
        } else {
            results[badge.id] = {
                unlocked: longestStreak >= badge.threshold,
                unlockedAt: null,
                unlockedTour: null,
                progressCurrent: longestStreak,
                progressTarget: badge.threshold
            };
        }
    });

    const maxDistanceTour = sortedByDate.reduce((max, e) => {
        const d = parseFloat(String(e.strecke || '').replace(',', '.')) || 0;
        return d > (max?.val || 0)
    ? {
        val: d,
        id: e.id,
        date: e.date,
        tourname: e.tourname
    }
    : max;
    }, null);
    ACHIEVEMENT_CATEGORIES.longestTour.badges.forEach(badge => {
        const reached = maxDistanceTour && maxDistanceTour.val >= badge.threshold ? maxDistanceTour : null;
        results[badge.id] = {
            unlocked: !!reached,
            unlockedAt: reached?.date || null,
            unlockedTour: reached?.tourname || null,
unlockedTourId: reached?.id || null,
            progressCurrent: maxDistanceTour?.val || 0,
            progressTarget: badge.threshold
        };
    });

    const maxAscentTour = sortedByDate.reduce((max, e) => {
        const a = parseFloat(String(e.aufstieg || '').replace(',', '.')) || 0;
        return a > (max?.val || 0)
    ? {
        val: a,
        id: e.id,
        date: e.date,
        tourname: e.tourname
    }
    : max;
    }, null);
    ACHIEVEMENT_CATEGORIES.dailyAscent.badges.forEach(badge => {
        const reached = maxAscentTour && maxAscentTour.val >= badge.threshold ? maxAscentTour : null;
        results[badge.id] = {
            unlocked: !!reached,
            unlockedAt: reached?.date || null,
            unlockedTour: reached?.tourname || null,
unlockedTourId: reached?.id || null,
            progressCurrent: maxAscentTour?.val || 0,
            progressTarget: badge.threshold
        };
    });

    const { records: perfRecords, maxScore } = computePerformanceRecordHistory(allTours);
    ACHIEVEMENT_CATEGORIES.performance.badges.forEach(badge => {
        if (badge.isRecordCounter) {
            const lastRecord = perfRecords[perfRecords.length - 1];
            results[badge.id] = {
                unlocked: perfRecords.length > 0,
                unlockedAt: lastRecord?.date || null,
                unlockedTour: lastRecord?.tourname || null,
unlockedTourId: lastRecord?.id || lastRecord?.entry?.id || null,
recordCount: perfRecords.length,
                isCounterType: true
            };
        } else {
            const reached = perfRecords.find(r => r.score >= badge.threshold);
            results[badge.id] = {
                unlocked: !!reached,
                unlockedAt: reached?.date || null,
                unlockedTour: reached?.tourname || null,
unlockedTourId: reached?.id || reached?.entry?.id || null,
progressCurrent: maxScore,
                progressTarget: badge.threshold
            };
        }
    });

    return results;
}

function recomputeAndSyncAchievements({ silent = false } = {}) {
    const freshResults = computeAllAchievements();
    const stored = appStorage.get(ACHIEVEMENTS_KEY);
    const isFirstRun = stored === null || stored === undefined;

    const previousUnlocked = isFirstRun ? {} : stored;
    const newlyUnlocked = [];
    const nextStored = { ...previousUnlocked };

    getAllAchievementBadgeDefs().forEach(badge => {
        const current = freshResults[badge.id];
        if (!current) return;

        const wasUnlocked = !!previousUnlocked[badge.id]?.unlocked;
        const isUnlocked = !!current.unlocked;

        const prevCount = previousUnlocked[badge.id]?.recordCount || 0;
        const currCount = current.recordCount || 0;
        const counterIncreased = badge.isRecordCounter ? currCount > prevCount : false;

        if (isUnlocked && (!wasUnlocked || counterIncreased)) {
            nextStored[badge.id] = {
    unlocked: true,
    unlockedAt: current.unlockedAt,
    unlockedTour: current.unlockedTour,
    unlockedTourId: current.unlockedTourId || null,
    recordCount: current.recordCount || undefined
};

            if (!isFirstRun && !silent && !ACHIEVEMENT_SILENT_CATEGORIES.has(badge.categoryId)) {
                newlyUnlocked.push(badge);
            }
        } else if (isUnlocked) {
            nextStored[badge.id] = nextStored[badge.id] || {
    unlocked: true,
    unlockedAt: current.unlockedAt,
    unlockedTour: current.unlockedTour,
    unlockedTourId: current.unlockedTourId || null,
    recordCount: current.recordCount || undefined
};
        }
    });

    appStorage.set(ACHIEVEMENTS_KEY, nextStored);

    newlyUnlocked.forEach(badge => triggerAchievementUnlockCelebration(badge));

    return { freshResults, newlyUnlocked, isFirstRun };
}

function triggerAchievementUnlockCelebration(badge) {
    const def = ACHIEVEMENT_CATEGORIES[badge.categoryId]?.badges.find(b => b.id === badge.id) || badge;
    const name = def.nameFn ? def.nameFn(def.threshold) : (def.id || 'Achievement');

    triggerConfetti();
    showAchievementToast(`${def.icon || '🏅'} Achievement freigeschaltet: ${name}`);
}

let achievementsYearFilter = 'all';

function populateAchievementsYearSelect() {
    const select = document.getElementById('achievements-year-select');
    if (!select) return;

    const years = getWrappedAvailableYears();
    select.innerHTML = `<option value="all">Gesamt (alle Jahre)</option>` +
        years.map(y => `<option value="${y}">${y}</option>`).join('');

    select.value = achievementsYearFilter;
}

function getAchievementsFilteredTours() {
    return achievementsYearFilter === 'all'
        ? (appStorage.get('touren') || [])
        : getWrappedDataForYear(Number(achievementsYearFilter));
}

function renderAchievementsView() {
    const container =
        document.getElementById('achievements-categories');

    const summaryValue =
        document.getElementById('achievements-summary-value');

    if (!container) return;

    const results =
        computeAllAchievements(
            getAchievementsFilteredTours()
        );

    const allBadges =
        getAllAchievementBadgeDefs();

    const unlockedCount =
        allBadges.filter(
            badge => results[badge.id]?.unlocked
        ).length;

    const totalCount = allBadges.length;

    const totalPercent = totalCount > 0
        ? Math.round((unlockedCount / totalCount) * 100)
        : 0;

    if (summaryValue) {
        summaryValue.innerHTML = `
            <div class="achievements-summary-main">
                <strong>${unlockedCount}</strong>
                <span>von ${totalCount} Achievements freigeschaltet</span>
            </div>

            <div class="achievements-summary-percent">
                ${totalPercent}%
            </div>

            <div class="achievements-progress-track">
                <span
                    class="achievements-progress-bar"
                    style="width:${totalPercent}%">
                </span>
            </div>
        `;
    }

    container.innerHTML =
        Object.entries(ACHIEVEMENT_CATEGORIES)
            .map(([catId, cat]) => {
                const categoryTotal =
                    cat.badges.length;

                const categoryUnlocked =
                    cat.badges.filter(
                        badge => results[badge.id]?.unlocked
                    ).length;

                const categoryPercent =
                    categoryTotal > 0
                        ? Math.round(
                            (categoryUnlocked / categoryTotal) * 100
                        )
                        : 0;

                const isComplete =
                    categoryUnlocked === categoryTotal;

                const isStarted =
                    categoryUnlocked > 0;

                const stateClass = isComplete
                    ? 'complete'
                    : isStarted
                        ? 'started'
                        : 'empty';

                return `
                    <button
                        type="button"
                        class="
                            achievement-category-tile
                            ${stateClass}
                        "
                        data-category-id="${catId}">

                        <span class="achievement-category-tile-top">
                            <span class="achievement-category-tile-icon">
                                ${cat.icon}
                            </span>

                            <span class="achievement-category-tile-state">
                                ${
                                    isComplete
                                        ? '✓'
                                        : `${categoryPercent}%`
                                }
                            </span>
                        </span>

                        <span class="achievement-category-tile-label">
                            ${cat.label}
                        </span>

                        <span class="achievement-category-tile-count">
                            ${categoryUnlocked}/${categoryTotal}
                        </span>

                        <span class="achievement-category-progress-track">
                            <span
                                class="achievement-category-progress-bar"
                                style="width:${categoryPercent}%">
                            </span>
                        </span>
                    </button>
                `;
            })
            .join('');

    container
        .querySelectorAll('.achievement-category-tile')
        .forEach(tile => {
            tile.addEventListener('click', () => {
                openAchievementCategoryModal(
                    tile.dataset.categoryId,
                    results
                );
            });
        });
}

function openAchievementCategoryModal(categoryId, resultsInput = null) {
    const results = resultsInput || computeAllAchievements(getAchievementsFilteredTours());
    const cat = ACHIEVEMENT_CATEGORIES[categoryId];
    if (!cat) return;

    const modal = document.getElementById('achievement-category-modal');
    const title = document.getElementById('achievement-category-title');
    const badgesContainer = document.getElementById('achievement-category-badges');
    if (!modal || !title || !badgesContainer) return;

    title.textContent = `${cat.icon} ${cat.label}`;

    badgesContainer.innerHTML = cat.badges.map(badge => {
        const r = results[badge.id] || {};
        const isUnlocked = !!r.unlocked;
        const name = badge.nameFn ? badge.nameFn(badge.threshold) : badge.id;

        return `
            <button type="button"
                class="achievement-badge ${isUnlocked ? 'unlocked' : 'locked'}"
                data-badge-id="${badge.id}">
                <span class="achievement-badge-icon">${isUnlocked ? badge.icon : '🔒'}</span>
                <span class="achievement-badge-name">${isUnlocked ? name : '???'}</span>
            </button>
        `;
    }).join('');

    badgesContainer.querySelectorAll('.achievement-badge').forEach(btn => {
        btn.addEventListener('click', () => {
            openAchievementDetailModal(btn.dataset.badgeId, results);
        });
    });

    modal.classList.remove('hidden');
}

function findTourById(tourId) {
    if (!tourId) return null;

    const tours = appStorage.get('touren') || [];

    return tours.find(
        tour => String(tour.id) === String(tourId)
    ) || null;
}

function openAchievementTourById(tourId) {
    const tour = findTourById(tourId);

    if (!tour) {
        showToast(
            'Die zugehörige Tour wurde nicht gefunden.',
            {
                type: 'error',
                duration: 2500
            }
        );
        return;
    }

    document
        .getElementById('achievement-detail-modal')
        ?.classList.add('hidden');

    document
        .getElementById('achievement-category-modal')
        ?.classList.add('hidden');

    openTourDetail(tour, {
        returnModalId: 'achievement-detail-modal'
    });
}

function openAchievementDetailModal(badgeId, resultsInput = null) {
    const results = resultsInput || computeAllAchievements();
    const badge = getAllAchievementBadgeDefs().find(b => b.id === badgeId);
    if (!badge) return;

    const r = results[badgeId] || {};
    const isUnlocked = !!r.unlocked;
    const name = badge.nameFn ? badge.nameFn(badge.threshold) : badge.id;
    const cat = ACHIEVEMENT_CATEGORIES[badge.categoryId];

    const modal = document.getElementById('achievement-detail-modal');
    const title = document.getElementById('achievement-detail-title');
    const body = document.getElementById('achievement-detail-body');
    if (!modal || !title || !body) return;

    title.textContent = isUnlocked ? name : 'Noch gesperrt';

    let bodyHtml = '';

    if (isUnlocked) {
        bodyHtml += `<div class="achievement-detail-icon">${badge.icon}</div>`;
        if (r.unlockedAt) {
            const d = new Date(r.unlockedAt);
            if (!isNaN(d.getTime())) {
                bodyHtml += `<p>Freigeschaltet am ${d.toLocaleDateString('de-AT')}</p>`;
            }
        }
        if (r.unlockedTour) {
    const tourLabel =
        `${r.unlockedTour}${r.unlockedAt ? ` · ${new Date(r.unlockedAt).toLocaleDateString('de-AT')}` : ''}`;

    if (r.unlockedTourId) {
        bodyHtml += `
            <div class="achievement-detail-tour-section">
                <div class="achievement-detail-tour-label">
                    Erreicht durch
                </div>

                <button
                    type="button"
                    class="achievement-detail-tour-link"
                    data-achievement-tour-id="${escapeHtmlAttribute(r.unlockedTourId)}">

                    <span>🥾</span>
                    <span>${escapeHtml(tourLabel)}</span>
                    <span class="achievement-detail-tour-arrow">›</span>
                </button>
            </div>
        `;
    } else {
        bodyHtml += `
            <p>
                Erreicht durch:
                ${escapeHtml(tourLabel)}
            </p>
        `;
    }
}
        if (r.recordCount) {
            bodyHtml += `<p>${r.recordCount}× erreicht</p>`;
        }
    } else {
        bodyHtml += `<div class="achievement-detail-icon locked">🔒</div>`;
        bodyHtml += `<p>Dieses Achievement ist noch nicht freigeschaltet.</p>`;
        if (r.progressTarget && !badge.isRecordCounter) {
            bodyHtml += `<p>Fortschritt: ${Math.round(r.progressCurrent || 0).toLocaleString('de-AT')} / ${r.progressTarget.toLocaleString('de-AT')}</p>`;
        }
    }

    body.innerHTML = bodyHtml;

body
    .querySelectorAll('[data-achievement-tour-id]')
    .forEach(button => {
        button.addEventListener('click', () => {
            openAchievementTourById(
                button.dataset.achievementTourId
            );
        });
    });

    modal.classList.remove('hidden');
}

