    const lightSets = [
        [[0,'#6fbf73'],[0.4,'#a8d86a'],[1,'#f9d77e']],   // original
        [[0,'#2471a3'],[0.4,'#5dade2'],[1,'#aed6f1']],   // blau
        [[0,'#ba4a00'],[0.4,'#e67e22'],[1,'#fdebd0']],   // orange
        [[0,'#7d3c98'],[0.4,'#af7ac5'],[1,'#d7bde2']],   // lila
        [[0,'#117a65'],[0.4,'#45b39d'],[1,'#a3e4d7']],   // petrol
    ];
    const darkSets = [
        [[0,'#000000'],[0.2,'#3b0000'],[1,'#7a0d0d']],   // original
        [[0,'#000510'],[0.2,'#001840'],[1,'#1a5276']],   // blau
        [[0,'#010f05'],[0.2,'#0b3d1a'],[1,'#1e8449']],   // grün
        [[0,'#100800'],[0.2,'#3d1f00'],[1,'#784212']],   // amber
        [[0,'#08000f'],[0.2,'#2d0050'],[1,'#6c3483']],   // lila
    ];
    const greenSets = [
        [[0,'#0d2418'],[0.25,'#1b4332'],[1,'#52b788']],  // original
        [[0,'#0d1824'],[0.25,'#1b2d43'],[1,'#5288b7']],  // blau
        [[0,'#24180d'],[0.25,'#43321b'],[1,'#b78852']],  // amber
        [[0,'#200d24'],[0.25,'#3b1b43'],[1,'#9752b7']],  // lila
        [[0,'#0d2424'],[0.25,'#1b4343'],[1,'#52b7b7']],  // petrol
    ];

    const summitSets = [

    // aktuelles Summit-Grün
    [
        [0, '#101412'],
        [0.35, '#46504a'],
        [0.70, '#dce5df'],
        [1, '#63b7ff']
    ],

    // Silber
    [
        [0, '#141817'],
        [0.35, '#58615d'],
        [0.70, '#c7d0cb'],
        [1, '#ffffff']
    ],

    // kräftigeres Grün
    [
        [0, '#09150e'],
        [0.35, '#006b2d'],
        [0.70, '#00b94f'],
        [1, '#39ff88']
    ],

    // Graphit
    [
        [0, '#0b0d0c'],
        [0.35, '#303633'],
        [0.70, '#777f7b'],
        [1, '#c8d0cc']
    ],

    // Grün-Weiß
    [
        [0, '#111513'],
        [0.35, '#176b3a'],
        [0.70, '#57e693'],
        [1, '#eafff1']
    ]
];                

    if (isSummit) {
    return summitSets[
        yearIndex % summitSets.length
    ];
}                
    if (isGreen) return greenSets[yearIndex % greenSets.length];
    if (isDark)  return darkSets [yearIndex % darkSets.length];
