document.addEventListener('touchstart', function onFirstTouch() {
    document.body.classList.add('touch-mode');
    document.removeEventListener('touchstart', onFirstTouch);
}, { passive: true });

/*
 * Mobile Tap-State Cleanup
 * ------------------------
 * Touch-Browser können :hover bzw. Fokus nach einem Tap sichtbar halten.
 * Echte ausgewählte .active-Zustände bleiben unangetastet; wir lösen nur
 * den temporären DOM-Fokus des tatsächlich angetippten Bedienelements.
 */
function initMobileTapStateCleanup() {
    const interactiveSelector = [
        'button',
        'a[href]',
        '[role="button"]',
        '.box-header',
        '.tour-list li',
        '.dash-tour-list li',
        '.peak-tour-list li',
        '.highlight-clickable',
        '.stats-clickable',
        '.tour-search-result',
        '.checklist-item',
        '.stats-peak-history-item'
    ].join(',');

    const releaseFocus = target => {
        const element = target?.closest?.(interactiveSelector);
        if (!element) return;

        /* Erst nach dem regulären click-Event lösen. */
        setTimeout(() => {
            if (document.activeElement === element && typeof element.blur === 'function') {
                element.blur();
            }
        }, 0);
    };

    document.addEventListener('pointerup', event => {
        if (event.pointerType === 'touch' || event.pointerType === 'pen') {
            document.body.classList.add('touch-mode');
            releaseFocus(event.target);
        }
    }, { passive: true, capture: true });

    document.addEventListener('pointercancel', event => {
        if (event.pointerType === 'touch' || event.pointerType === 'pen') {
            releaseFocus(event.target);
        }
    }, { passive: true, capture: true });

    /* Fallback für ältere Touch-Browser ohne Pointer Events. */
    document.addEventListener('touchend', event => {
        releaseFocus(event.target);
    }, { passive: true, capture: true });
}

initMobileTapStateCleanup();

