function showPlanSection(section) {

    /*
     * Aktiven Button markieren
     */
    planSectionButtons.forEach(btn => {

        btn.classList.toggle(
            'active',
            btn.dataset.planSection === section
        );

    });


    /*
     * Nur die Boxen des gewählten Bereichs anzeigen.
     *
     * "Liste" besitzt bewusst zwei Boxen:
     * Mobile-Liste + Desktop-Tabelle.
     * Das vorhandene Responsive-CSS entscheidet,
     * welche davon tatsächlich sichtbar ist.
     */
    planSectionPanels.forEach(panel => {

        const isActive =
            panel.dataset.planPanel === section;

        panel.classList.toggle(
            'plan-panel-active',
            isActive
        );


        if (isActive) {

            /*
             * Gewählten Bereich automatisch öffnen.
             */
            panel.classList.add('active');

            const content =
                panel.querySelector('.box-content');

            if (content) {
                requestAnimationFrame(() => {
                    content.style.maxHeight =
                        content.scrollHeight + 'px';
                });
            }

        } else {

            panel.classList.remove('active');

            const content =
                panel.querySelector('.box-content');

            if (content) {
                content.style.maxHeight = '0';
            }

        }

    });


    /*
     * Beim Bereichswechsel immer oben im
     * Inhaltsbereich beginnen.
     */
    const accordion =
        document.querySelector(
            '#tour-view > .accordion'
        );

    if (accordion) {
        accordion.scrollTop = 0;
    }
}


