    const planMultidayFieldsEl = document.getElementById('plan-multiday-fields');
    if (planMultidayFieldsEl) planMultidayFieldsEl.style.display = isMultidayPlanEntry ? 'flex' : 'none';
    document.getElementById('plan-tour-group').value = entry.tourGroup || '';
    document.getElementById('plan-tour-day').value = entry.tourDay || '';
    document.getElementById('plan-tour-day-count').value = entry.tourDayCount || '';

