function transferPlannedTourToSavedForm(entry) {
    if (!entry) return;

    // Übernahme aus Planung ist kein Edit eines gespeicherten Eintrags.
    delete form.dataset.editEntryId;

    // Formular "Tour speichern" befüllen
    form.date.value = '';
    form.tourname.value = entry.tourname || '';
    form.strecke.value = entry.strecke || '';
    form.aufstieg.value = entry.aufstieg || '';
    form.ausgangspunkt.value = entry.ausgangspunkt || '';
    form.zeit.value = entry.zeit || '';

    if (notesEl) {
        notesEl.value = entry.notes || '';
    }

if (bikeStreckeInput) {
    bikeStreckeInput.value = entry.bikeStrecke || '';
}

if (bikeHmInput) {
    bikeHmInput.value = entry.bikeHm || '';
}

if (bikeZeitInput) {
    bikeZeitInput.value = entry.bikeZeit || '';
}

if (ferrataStreckeInput) {
    ferrataStreckeInput.value =
        entry.ferrataStrecke || '';
}

if (ferrataHmInput) {
    ferrataHmInput.value =
        entry.ferrataHm || '';
}

if (ferrataZeitInput) {
    ferrataZeitInput.value =
        entry.ferrataZeit || '';
}

if (regionEl) {
    regionEl.value = entry.region || '';
}
if (difficultyEl) difficultyEl.value = entry.difficulty || '';
if (ferrataFields) {
    ferrataFields.style.display =
        String(entry.difficulty || '').trim().toLowerCase() === 'hike & climb'
            ? 'contents'
            : 'none';
}

updateActivityFieldsVisibility();

    const isMultidayTransfer = String(entry.difficulty || '').toLowerCase() === 'mehrtägig';
    const transferMultidayFieldsEl = document.getElementById('multiday-fields');
    if (transferMultidayFieldsEl) transferMultidayFieldsEl.style.display = isMultidayTransfer ? 'flex' : 'none';
    document.getElementById('tour-group').value = entry.tourGroup || '';
    document.getElementById('tour-day').value = entry.tourDay || '';
    document.getElementById('tour-day-count').value = entry.tourDayCount || '';

    // Steigungsmodus zurücksetzen
    useFullDistanceForGradient = false;
    if (slopeToggleBtn) {
        slopeToggleBtn.setAttribute('aria-pressed', 'false');
    }

    // Gipfel und dynamische Gipfelfelder
    const count = parseInt(entry.gipfel) || 0;
    gipfelSelect.value = count;
    gipfelDetailsContainer.innerHTML = '';

    if (count > 0 && entry.gipfelDetails) {
        gipfelDetailsContainer.style.display = 'flex';

        for (let j = 0; j < count; j++) {
            const g = entry.gipfelDetails[j] || { name: '', hoehe: '' };

            const div = document.createElement('div');
            div.classList.add('form-group');

            div.innerHTML = `
                <label>Gipfel ${j + 1} Name:</label>
                <input type="text" name="gipfel_name_${j + 1}" value="${escapeHtmlAttribute(g.name || '')}">
                <label>Gipfel ${j + 1} Seehöhe (m):</label>
                <input type="number" inputmode="numeric" step="1" min="0" name="gipfel_hoehe_${j + 1}" value="${escapeHtmlAttribute(g.hoehe || '')}">
            `;

            gipfelDetailsContainer.appendChild(div);
        }
    } else {
        gipfelDetailsContainer.style.display = 'none';
    }

    // Ursprüngliche geplante Tour löschen
    removePlannedTourFromStorage(entry);

    // Geplante Touren neu laden
    loadPlannedTours();
    updatePlannedPeaks();

    // Modal schließen
    closeTourDetail();

    // Zur App-Ansicht wechseln
    if (typeof goToView === 'function') {
        goToView('app', true);
    }

    // Box "Tour speichern" öffnen
    const saveBox = form.closest('.box');

    openBoxIfNeeded(saveBox, () => {
        form.tourname.focus();

        saveBox.scrollIntoView({
            behavior: 'smooth',
            block: 'start'
        });
    });

autoSaveDataFileIfLinked();

}

// ---------- Tabelle ----------

const plannedTableEntryCache = new Map();

function initPlannedTableDelegation() {
    if (!plannedTableBody || plannedTableBody.dataset.delegated === '1') return;

    plannedTableBody.dataset.delegated = '1';

    plannedTableBody.addEventListener('click', event => {
        const row = event.target.closest('tr[data-key]');
        if (!row || !plannedTableBody.contains(row)) return;

        const key = row.dataset.key || '';
        const entry = plannedTableEntryCache.get(key);
        if (!entry) return;

        if (event.target.closest('.gipfel-toggle')) {
            event.stopPropagation();

            const accordion =
                row.nextElementSibling?.querySelector('.gipfel-accordion');

            if (accordion) {
                accordion.style.display =
                    accordion.style.display === 'block'
                        ? 'none'
                        : 'block';

                requestAnimationFrame(() => updateBoxHeight(plannedBox));
            }

            return;
        }

        if (event.target.closest('.delete-btn')) {
            event.stopPropagation();

            if (entry._isMultidaySummary) return;

            const allPlanned = appStorage.get('plannedTours') || [];

            const originalIndex =
                allPlanned.findIndex(item =>
                    normalizePlannedTourForCompare(item) === key
                );

            if (originalIndex > -1) {
                const deletedEntry =
                    JSON.parse(JSON.stringify(allPlanned[originalIndex]));
                const deletedIndex = originalIndex;

                allPlanned.splice(originalIndex, 1);
                appStorage.set('plannedTours', allPlanned);

                loadPlannedTours();
                updatePlannedPeaks();

                showToast(`„${deletedEntry.tourname || 'Tour'}“ gelöscht`, {
                    type: 'undo',
                    duration: 5000,
                    undoCallback: () => {
                        const current = appStorage.get('plannedTours') || [];
                        current.splice(deletedIndex, 0, deletedEntry);
                        appStorage.set('plannedTours', current);
                        loadPlannedTours();
                        updatePlannedPeaks();
                        showToast('Tour wiederhergestellt.', {
                            type: 'success',
                            duration: 2000
                        });
                    }
                });
            }

            return;
        }

        if (event.target.closest('.edit-btn')) {
            event.stopPropagation();

            if (entry._isMultidaySummary) return;

            const entryToEdit = JSON.parse(JSON.stringify(entry));

            fillPlanFormFromEntry(entryToEdit);
            removePlannedTourFromStorage(entryToEdit);

            loadPlannedTours();
            updatePlannedPeaks();

            openBoxIfNeeded(planBox, () => {
                planTourname.focus();

                planBox.scrollIntoView({
                    behavior: 'smooth',
                    block: 'start'
                });
            });

            return;
        }

        if (event.target.closest('.load-btn')) {
            event.stopPropagation();

            if (entry._isMultidaySummary) return;

            transferPlannedTourToSavedForm(entry);
            return;
        }

        if (entry._isMultidaySummary) {
            openTourGroupModal(entry._tourGroupName, 'planned');
        }
    });
}

function loadPlannedTours() {
    plannedTours = appStorage.get('plannedTours') || [];

    initPlannedTableDelegation();
    plannedTableEntryCache.clear();

    plannedTableBody.innerHTML = '';

    const displayData = groupEntriesForDisplay(plannedTours, 'planned')
        .sort((a, b) => {
            const ma = parseInt(a.monatVon) || 99;
            const mb = parseInt(b.monatVon) || 99;

            if (ma !== mb) return ma - mb;

            return (a.tourname || '').localeCompare(b.tourname || '');
        });

    displayData.forEach((t, i) => {
        const isGroup = !!t._isMultidaySummary;
        const key = normalizePlannedTourForCompare(t);

        const tr = document.createElement('tr');
        tr.dataset.key = key;
        plannedTableEntryCache.set(key, t);

        if (isGroup) tr.classList.add('is-multiday-row');

        tr.innerHTML = `
            <td data-label="Nr.">${i + 1}</td>
            <td data-label="Saison">${formatSaison(t.monatVon, t.monatBis)}</td>
            <td data-label="Tour">${escapeHtml(t.tourname || 'Unbekannt')}${multidaySummaryBadge(t)}</td>
            <td data-label="Gipfel" class="gipfel-toggle" style="cursor:pointer;font-weight:600;">${t.gipfel}</td>
            <td data-label="Strecke"><span class="value">${formatDecimalAT(t.strecke)}</span></td>
            <td data-label="Aufstieg"><span class="value">${t.aufstieg}</span></td>
            <td data-label="Startpunkt">${escapeHtml(t.ausgangspunkt || '–')}</td>
            <td data-label="Zeit"><span class="value">${t.zeit}</span></td>
            <td data-label="Aktion">
                ${isGroup ? '' : `
                <button class="edit-btn" title="Geplante Tour bearbeiten">✎</button>
                <button class="load-btn" title="Ins Formular übernehmen">⏳</button>
                <button class="delete-btn">✕</button>
                `}
            </td>
        `;

        plannedTableBody.appendChild(tr);

        if (t.gipfelDetails && t.gipfelDetails.length > 0) {
            const acc = document.createElement('tr');
            acc.innerHTML = `
                <td colspan="9">
                    <div class="gipfel-accordion" style="display:none;">
                        ${t.gipfelDetails.map(g => `⛰ ${escapeHtml(g.name || 'Unbekannt')} – ${escapeHtml(g.hoehe || '–')} m`).join('<br>')}
                    </div>
                </td>
            `;
            plannedTableBody.appendChild(acc);
        }
    });

    requestAnimationFrame(() => updateBoxHeight(plannedBox));
    updatePlannedOverview();

    syncMobilePlanTourListFromTable();

    const listBox = document.getElementById('planned-tours-list');
    if (listBox && listBox.classList.contains('active')) {
        const content = listBox.querySelector('.box-content');
        requestAnimationFrame(() => {
            if (listBox.classList.contains('active')) {
                content.style.maxHeight = content.scrollHeight + 'px';
            }
        });
    }
}

// --------------- mobile Plan-Liste --------------

const mobilePlannedTourEntryCache = [];

function initMobilePlannedTourDelegation(list) {
    if (!list || list.dataset.delegated === '1') return;

    list.dataset.delegated = '1';

    list.addEventListener('click', event => {
        const item = event.target.closest('li[data-entry-index]');
        if (!item || !list.contains(item)) return;

        const index = parseInt(item.dataset.entryIndex, 10);
        const entry = mobilePlannedTourEntryCache[index];

        if (!entry) return;

        if (entry._isMultidaySummary) {
            openTourGroupModal(
                entry._tourGroupName,
                'planned'
            );
        } else {
            openPlannedTourDetail(entry);
        }
    });
}

function syncMobilePlanTourListFromTable() {
    const listBox = document.querySelector('#planned-tours-list');
    if (!listBox) return;

    const list = listBox.querySelector('.tour-list');
    if (!list) return;

    initMobilePlannedTourDelegation(list);

    list.innerHTML = '';
    mobilePlannedTourEntryCache.length = 0;

    if (!plannedTours || plannedTours.length === 0) {
        list.innerHTML = '<li style="opacity:.6">Keine Touren</li>';
        return;
    }

    const sortedTours = groupEntriesForDisplay(
        plannedTours,
        'planned'
    ).sort((a, b) => {
        return String(a.tourname || '').localeCompare(
            String(b.tourname || ''),
            'de',
            { sensitivity: 'base' }
        );
    });

    sortedTours.forEach(entry => {
        const cacheIndex = mobilePlannedTourEntryCache.length;
        mobilePlannedTourEntryCache.push(entry);

        const li = document.createElement('li');
        li.dataset.entryIndex = String(cacheIndex);

        li.innerHTML = `
            <span class="tour-name">
                ${escapeHtml(entry.tourname || 'Unbekannt')}
                ${multidaySummaryBadge(entry)}
            </span>
        `;

        list.appendChild(li);
    });

    const listBoxContainer = listBox.closest('.box');

    if (
        listBoxContainer &&
        listBoxContainer.classList.contains('active')
    ) {
        const content = listBoxContainer.querySelector('.box-content');

        if (content) {
            requestAnimationFrame(() => {
                if (listBoxContainer.classList.contains('active')) {
                    content.style.maxHeight =
                        content.scrollHeight + 'px';
                }
            });
        }
    }
}

function updatePlannedOverview() {
    const tours = plannedTours;

    let totalTours = countDistinctTours(tours);
    let totalPeaks = 0;
    let totalDistance = 0;
    let totalAscent = 0;
    let totalMinutes = 0;

    tours.forEach(t => {
        totalPeaks += parseInt(t.gipfel) || 0;
        totalDistance += parseFloat(t.strecke) || 0;
        totalAscent += parseInt(t.aufstieg) || 0;

        if (t.zeit) {
            const [h, m] = t.zeit.split(':').map(Number);
            totalMinutes += (h * 60 + m);
        }
    });

    const hours = Math.floor(totalMinutes / 60);
    const minutes = totalMinutes % 60;

    document.getElementById('ov-total-tours').textContent = totalTours;
    document.getElementById('ov-total-peaks').textContent = totalPeaks;
    document.getElementById('ov-total-distance').textContent = totalDistance.toFixed(1);
    document.getElementById('ov-total-ascent').textContent = totalAscent;
    document.getElementById('ov-total-time').textContent =
        `${hours}:${String(minutes).padStart(2, '0')}`;
}



// ---------------- Checkliste: Tagestour / Mehrtägig persistent ----------------

function initChecklistToggle() {
    const checklistBox = document.getElementById('checklist-box');
    if (!checklistBox) return;

    const STORAGE_KEY = 'tourChecklistState_v1';

    const modeButtons = checklistBox.querySelectorAll('.checklist-mode-btn');
    const sections = checklistBox.querySelectorAll('.checklist-specific');
    const checkboxes = checklistBox.querySelectorAll('.checklist-item input[type="checkbox"]');

    // gespeicherten Zustand laden
    let checklistState = appStorage.get(STORAGE_KEY) || {
        mode: 'day',
        checked: {}
    };

    function saveChecklistState() {
        appStorage.set(STORAGE_KEY, checklistState);
    }

    function getCheckboxKey(input) {
        const item = input.closest('.checklist-item');
        const text = item?.querySelector('span')?.textContent?.trim() || '';

        return text
            .toLowerCase()
            .replace(/\s+/g, '-')
            .replace(/[ä]/g, 'ae')
            .replace(/[ö]/g, 'oe')
            .replace(/[ü]/g, 'ue')
            .replace(/[ß]/g, 'ss');
    }

    function updateChecklistBoxHeight() {
    if (typeof updateBoxHeight === 'function') {
        requestAnimationFrame(() => {
            updateBoxHeight(checklistBox);
        });
    } else {
        const content = checklistBox.querySelector('.box-content');

        if (checklistBox.classList.contains('active') && content) {
            requestAnimationFrame(() => {
                content.style.maxHeight =
                    content.scrollHeight + 'px';
            });
        }
    }
}

function scrollChecklistToTop() {
    if (window.innerWidth > 768) return;

    const header = checklistBox.querySelector('.box-header');
    if (!header) return;

    /*
     * Erst die neue Checklistenhöhe übernehmen,
     * danach die Box an die obere View-Kante scrollen.
     */
    requestAnimationFrame(() => {
        requestAnimationFrame(() => {
            scrollBoxHeaderToTopMobile(header);
        });
    });
}

    function setMode(mode, shouldSave = true) {
        checklistState.mode = mode;

        // Buttons aktiv/inaktiv setzen
        modeButtons.forEach(btn => {
            const isActive = btn.dataset.checklistMode === mode;
            btn.classList.toggle('active', isActive);
            btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
        });

        // passende Sektion anzeigen
        sections.forEach(section => {
            const isVisible = section.dataset.checklistSection === mode;
            section.classList.toggle('is-hidden', !isVisible);
        });

        if (shouldSave) {
            saveChecklistState();
        }

        updateChecklistBoxHeight();

        if (shouldSave) {
            scrollChecklistToTop();
        }
    }

    // gespeicherte Checkbox-Zustände anwenden
    checkboxes.forEach(input => {
        const key = getCheckboxKey(input);

        input.checked = checklistState.checked[key] === true;

        input.addEventListener('change', () => {
            checklistState.checked[key] = input.checked;
            saveChecklistState();
        });
    });

    // Umschalter speichern
    modeButtons.forEach(btn => {
        btn.addEventListener('click', () => {
            setMode(btn.dataset.checklistMode, true);
        });
    });

    // gespeicherten Modus wiederherstellen
    setMode(checklistState.mode || 'day', false);
}

document.addEventListener('DOMContentLoaded', initChecklistToggle);
document.addEventListener('DOMContentLoaded', initHeaderScrollShadow);


// =========================
// Suche & Vergleich – gemeinsame Helfer
// =========================


function parseNum(val) {
  if (val === '' || val == null) return null;
  const n = parseFloat(String(val).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
}



/* =========================================================
   Neue unabhängige Tourensuche
   ========================================================= */

/*
 * Suchtexte vereinheitlichen.
 *
 * Dadurch funktionieren unter anderem:
 *
 * - Groß-/Kleinschreibung unabhängig
 * - ä  <-> ae
 * - ö  <-> oe
 * - ü  <-> ue
 * - ß  <-> ss
 */
function normalizeTourSearchText(value) {

    return String(value ?? '')
        .toLowerCase()
        .replace(/ä/g, 'ae')
        .replace(/ö/g, 'oe')
        .replace(/ü/g, 'ue')
        .replace(/ß/g, 'ss')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z0-9]+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
}


/*
 * Alle für die Suche interessanten
 * Informationen einer Tour zu einem
 * einzigen Suchtext zusammenfassen.
 */
let tourSearchTextCache = new WeakMap();

function invalidateTourSearchCache() {
    tourSearchTextCache = new WeakMap();
}

function buildTourSearchText(entry) {

    if (!entry) return '';

    if (
        typeof entry === 'object' &&
        tourSearchTextCache.has(entry)
    ) {
        return tourSearchTextCache.get(entry);
    }


    const parts = [

        entry.date,

        entry.tourname,
        entry.tourGroup,

        entry.region,
        entry.difficulty,

        entry.notes,
        entry.ausgangspunkt,

        entry.strecke,
        entry.aufstieg,
        entry.zeit,

        entry.bikeStrecke,
        entry.bikeHm,
        entry.bikeZeit,

        entry.ferrataStrecke,
        entry.ferrataHm,
        entry.ferrataZeit,

        entry.gipfel

    ];

     /*
 * Übergeordnete Regionsgruppe ebenfalls
 * durchsuchbar machen.
 *
 * Beispiel:
 * Iseltal   -> zusätzlich Osttirol
 * Mölltal   -> zusätzlich Kärnten
 */
const normalizedEntryRegion =
    normalizeTourSearchText(
        entry.region
    );


if (
    normalizedEntryRegion &&
    typeof MAP_REGION_GROUPS ===
        'object'
) {

    Object.entries(
        MAP_REGION_GROUPS
    )
    .forEach(
        ([groupName, regions]) => {

            if (
                !Array.isArray(regions)
            ) {
                return;
            }


            const belongsToGroup =
                regions.some(
                    region =>
                        normalizeTourSearchText(
                            region
                        ) ===
                        normalizedEntryRegion
                );


            if (belongsToGroup) {
                parts.push(
                    groupName
                );
            }

        }
    );
}

    /*
     * Berechnete Schwierigkeit ebenfalls
     * durchsuchbar machen:
     *
     * leicht / mittel / schwer
     */
    if (
        typeof getEffectiveDifficulty ===
        'function'
    ) {

        parts.push(
            getEffectiveDifficulty(entry)
        );
    }


    /*
     * Gipfelnamen und Gipfelhöhen.
     */
    if (
        Array.isArray(
            entry.gipfelDetails
        )
    ) {

        entry.gipfelDetails
            .forEach(gipfel => {

                parts.push(
                    gipfel?.name
                );

                parts.push(
                    gipfel?.hoehe
                );

            });
    }


    const searchableText =
        normalizeTourSearchText(
            parts.join(' ')
        );

    if (typeof entry === 'object') {
        tourSearchTextCache.set(
            entry,
            searchableText
        );
    }

    return searchableText;
}


/*
 * Prüfen, ob eine Tour zur Suchanfrage passt.
 *
 * Mehrere Suchbegriffe müssen ALLE vorkommen,
 * dürfen aber aus unterschiedlichen Feldern
 * stammen.
 */



/*
 * Eigenständige Trefferliste.
 *
 * Die Suche arbeitet vollständig unabhängig
 * und beeinflusst weder Stats, Highlights
 * noch die normale Tourenliste.
 */
function getTourSearchResults(query) {

    const normalizedQuery =
        normalizeTourSearchText(query);

    if (!normalizedQuery) {
        return [];
    }

    const searchTerms =
        normalizedQuery
            .split(' ')
            .filter(Boolean);

    const tours =
        appStorage.get('touren') || [];

    return tours.filter(entry => {
        const searchableText =
            buildTourSearchText(entry);

        return searchTerms.every(
            term =>
                searchableText.includes(term)
        );
    });
}

/* =========================================================
   Neue Tourensuche – Treffer darstellen
   ========================================================= */

function formatTourSearchDate(value) {

    const match =
        String(value || '')
            .match(
                /^(\d{4})-(\d{2})-(\d{2})/
            );

    if (!match) {
        return String(value || '');
    }

    return (
        `${match[3]}.${match[2]}.${match[1]}`
    );
}


const tourSearchDelegationState = {
    query: '',
    visibleResults: []
};

function openDelegatedTourSearchResult(resultEl) {
    if (!resultEl) return;

    const index = parseInt(
        resultEl.dataset.searchResultIndex,
        10
    );

    const entry =
        tourSearchDelegationState.visibleResults[index];

    if (!entry) return;

    if (entry._isMultidaySummary) {
        openTourGroupModal(
            entry._tourGroupName || entry.tourGroup,
            'saved'
        );
        return;
    }

    openTourDetail(entry, {
        returnModalId: null
    });
}

function initTourSearchResultDelegation(container) {
    if (!container || container.dataset.delegated === '1') return;

    container.dataset.delegated = '1';

    container.addEventListener('click', event => {
        const pageButton =
            event.target.closest('.tour-search-page-btn');

        if (pageButton && container.contains(pageButton)) {
            const nextPage = parseInt(
                pageButton.dataset.searchPage,
                10
            );

            if (!Number.isFinite(nextPage)) return;

            renderTourSearchResults(
                tourSearchDelegationState.query,
                nextPage
            );

            container.scrollTop = 0;
            return;
        }

        const resultEl =
            event.target.closest('.tour-search-result');

        if (resultEl && container.contains(resultEl)) {
            openDelegatedTourSearchResult(resultEl);
        }
    });

    container.addEventListener('keydown', event => {
        if (event.key !== 'Enter' && event.key !== ' ') return;

        const resultEl =
            event.target.closest('.tour-search-result');

        if (!resultEl || !container.contains(resultEl)) return;

        event.preventDefault();
        openDelegatedTourSearchResult(resultEl);
    });
}

function renderTourSearchResults(
    query,
    page = 1
) {

    const container =
        document.getElementById(
            'tour-search-results'
        );

    if (!container) return;

    initTourSearchResultDelegation(container);

    const normalizedQuery =
        normalizeTourSearchText(
            query
        );


    /*
     * Kein Suchtext:
     * Trefferbereich vollständig ausblenden.
     */
    if (!normalizedQuery) {
        tourSearchDelegationState.query = '';
        tourSearchDelegationState.visibleResults = [];

        container.innerHTML = '';
        container.hidden = true;

        return;
    }


    /*
     * Zuerst unabhängig suchen.
     */
    const rawResults =
        getTourSearchResults(
            normalizedQuery
        );


    /*
     * Mehrtagestouren zu einem Treffer
     * zusammenfassen.
     */
    const results =
        groupEntriesForDisplay(
            rawResults,
            'saved'
        )
        .sort((a, b) => {

            const timeA =
                new Date(
                    a?.date || 0
                ).getTime() || 0;

            const timeB =
                new Date(
                    b?.date || 0
                ).getTime() || 0;

            return timeB - timeA;
        });


    container.hidden = false;


    if (results.length === 0) {
        tourSearchDelegationState.query = query;
        tourSearchDelegationState.visibleResults = [];

        container.innerHTML = `
            <div class="tour-search-empty">
                Keine passenden Touren gefunden
            </div>
        `;

        return;
    }


    /*
 * Suchergebnisse seitenweise darstellen.
 */
const RESULTS_PER_PAGE = 10;

const totalPages =
    Math.max(
        1,
        Math.ceil(
            results.length /
            RESULTS_PER_PAGE
        )
    );


/*
 * Falls durch eine neue Suche weniger
 * Seiten vorhanden sind, Seite absichern.
 */
const currentPage =
    Math.min(
        Math.max(
            parseInt(page, 10) || 1,
            1
        ),
        totalPages
    );


const startIndex =
    (currentPage - 1) *
    RESULTS_PER_PAGE;


const visibleResults =
    results.slice(
        startIndex,
        startIndex +
            RESULTS_PER_PAGE
    );

tourSearchDelegationState.query = query;
tourSearchDelegationState.visibleResults = visibleResults;

const countLabel =
    `${visibleResults.length} von ${results.length} Treffern`;


/*
 * Seitenbuttons erzeugen.
 */
const paginationHtml =
    totalPages > 1

        ? `
            <div class="tour-search-pagination">

                ${
                    Array.from(
                        {
                            length: totalPages
                        },
                        (_, index) => {

                            const pageNumber =
                                index + 1;

                            return `
                                <button
                                    type="button"
                                    class="
                                        tour-search-page-btn
                                        ${
                                            pageNumber ===
                                            currentPage
                                                ? 'active'
                                                : ''
                                        }
                                    "
                                    data-search-page="${pageNumber}"
                                    aria-label="Seite ${pageNumber}"
                                    aria-current="${
                                        pageNumber ===
                                        currentPage
                                            ? 'page'
                                            : 'false'
                                    }">

                                    ${pageNumber}

                                </button>
                            `;
                        }
                    ).join('')
                }

            </div>
        `

        : '';


    container.innerHTML = `

        <div class="tour-search-results-head">

    <span class="tour-search-results-count">
        ${countLabel}
    </span>

    ${paginationHtml}

</div>

        <div class="tour-search-results-list">

            ${visibleResults.map((entry, resultIndex) => {

                const isMultiday =
                    entry._isMultidaySummary === true;

                const title =
                    entry.tourname ||
                    'Unbenannte Tour';

                const date =
                    formatTourSearchDate(
                        entry.date
                    );

                const region =
                    String(
                        entry.region || ''
                    ).trim();

                const difficulty =
                    isMultiday
                        ? 'Mehrtägig'
                        : String(
                            entry.difficulty || ''
                        ).trim();

                const distance =
                    parseNum(
                        entry.strecke
                    );

                const ascent =
                    parseNum(
                        entry.aufstieg
                    );

                const peaks =
                    parseInt(
                        entry.gipfel
                    ) || 0;

                const stages =
                    isMultiday
                        ? parseInt(
                            entry._stageCount
                        ) || 0
                        : 0;


                return `

                    <div
    class="tour-search-result"
    data-search-result-index="${resultIndex}"
    role="button"
    tabindex="0">

                        <div class="tour-search-result-title">
                            ${escapeHtml(title)}
                        </div>

                        <div class="tour-search-result-meta">

                            ${date
                                ? `<span>📅 ${escapeHtml(date)}</span>`
                                : ''
                            }

                            ${region
                                ? `<span>📍 ${escapeHtml(region)}</span>`
                                : ''
                            }

                            ${difficulty
                                ? `<span>🥾 ${escapeHtml(difficulty)}</span>`
                                : ''
                            }

                            ${stages > 0
                                ? `<span>🗂 ${stages} Etappen</span>`
                                : ''
                            }

                            ${distance !== null
                                ? `<span>🛤 ${formatDecimalAT(distance)} km</span>`
                                : ''
                            }

                            ${ascent !== null
                                ? `<span>↗ ${Math.round(ascent)} hm</span>`
                                : ''
                            }

                            ${peaks > 0
                                ? `<span>⛰ ${peaks}</span>`
                                : ''
                            }

                        </div>

                    </div>

                `;

            }).join('')}

        </div>
    `;


}

function initTourSearchResults() {

    const input =
        document.getElementById(
            'fv-query'
        );

    if (!input) return;

    let searchTimer = null;

    renderTourSearchResults(
        input.value,
        1
    );

    input.addEventListener(
        'input',
        () => {
            clearTimeout(searchTimer);

            searchTimer = setTimeout(
                () => {
                    renderTourSearchResults(
                        input.value,
                        1
                    );
                },
                120
            );
        }
    );
}

/* =========================================================
   Suche & Vergleich – Daten nur bei Bedarf aktualisieren
   ========================================================= */

function refreshFilterViewData() {
    if (typeof populateCompareOptions === 'function') {
        populateCompareOptions();
    }

    if (typeof populateTourCompareFilters === 'function') {
        populateTourCompareFilters(true);
    }

    if (typeof populateFilters === 'function') {
        populateFilters(
            appStorage.get('touren') || []
        );
    }

    const input =
        document.getElementById('fv-query');

    if (input && input.value.trim()) {
        renderTourSearchResults(
            input.value,
            1
        );
    }

    markDerivedViewClean('filter');
}


/* =========================================================
   Manueller Tourvergleich
   ========================================================= */

function getTourCompareElements() {
    return {
        type: document.getElementById('tour-compare-type-filter'),
        region: document.getElementById('tour-compare-region-filter'),
        yearA: document.getElementById('tour-compare-year-a'),
        yearB: document.getElementById('tour-compare-year-b'),
        tourA: document.getElementById('tour-compare-tour-a'),
        tourB: document.getElementById('tour-compare-tour-b'),
        run: document.getElementById('tour-compare-run-btn'),
        result: document.getElementById('tour-compare-result')
    };
}

function getTourCompareDate(entry) {
    const date = parseStatsCalendarDate(entry?.date);
    return date instanceof Date && !isNaN(date.getTime()) ? date : null;
}

function getTourCompareDifficultyLabel(value) {
    const raw = String(value || '').trim();
    const normalized = raw.toLowerCase();

    const labels = {
        'wandern': 'Wandern',
        'klettersteig': 'Klettersteig',
        'hike & climb': 'Hike & Climb',
        'bike & hike': 'Bike & Hike',
        'radtour': 'Radtour',
        'mehrtägig': 'Mehrtägig'
    };

    return labels[normalized] || raw || 'Ohne Tourart';
}

function syncTourCompareMobileSelect(select) {
    if (!select) return;
    if (typeof mobSelSyncDisplay === 'function') {
        try { mobSelSyncDisplay(select); } catch (_) {}
    }
}

function clearTourCompareResult() {
    const result = getTourCompareElements().result;
    if (!result) return;
    result.innerHTML = '';
    result.hidden = true;
}

function populateTourCompareSelect(select, options, placeholder, preferredValue = '') {
    if (!select) return '';

    const validValues = new Set(options.map(option => String(option.value)));
    const nextValue = validValues.has(String(preferredValue))
        ? String(preferredValue)
        : '';

    select.innerHTML = `
        <option value="">${escapeHtml(placeholder)}</option>
        ${options.map(option => `
            <option value="${escapeHtmlAttribute(String(option.value))}">
                ${escapeHtml(option.label)}
            </option>
        `).join('')}
    `;

    select.value = nextValue;
    syncTourCompareMobileSelect(select);
    return nextValue;
}

function getTourCompareFilteredTours(yearValue) {
    const { type, region } = getTourCompareElements();
    const selectedType = String(type?.value || 'all');
    const selectedRegion = String(region?.value || 'all');

    return [...(appStorage.get('touren') || [])]
        .filter(entry => {
            const date = getTourCompareDate(entry);
            if (!date) return false;

            if (
                yearValue &&
                yearValue !== 'all' &&
                date.getFullYear() !== Number(yearValue)
            ) {
                return false;
            }

            if (
                selectedType !== 'all' &&
                String(entry?.difficulty || '').trim().toLowerCase() !== selectedType
            ) {
                return false;
            }

            if (
                selectedRegion !== 'all' &&
                String(entry?.region || '').trim() !== selectedRegion
            ) {
                return false;
            }

            return true;
        })
        .sort((a, b) => getTourCompareDate(b) - getTourCompareDate(a));
}

function formatTourCompareOptionLabel(entry) {
    const date = getTourCompareDate(entry);
    const dateText = date
        ? date.toLocaleDateString('de-AT', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric'
        })
        : '–';

    const name = String(entry?.tourname || 'Unbekannte Tour').trim();
    return `${dateText} · ${name}`;
}

function populateTourCompareTourSelects(preserveSelections = true) {
    const els = getTourCompareElements();
    if (!els.tourA || !els.tourB) return;

    const previousA = preserveSelections ? els.tourA.value : '';
    const previousB = preserveSelections ? els.tourB.value : '';

    const toursA = getTourCompareFilteredTours(els.yearA?.value || 'all');
    const toursB = getTourCompareFilteredTours(els.yearB?.value || 'all');

    const optionsA = toursA.map(entry => ({
        value: String(entry.id || ''),
        label: formatTourCompareOptionLabel(entry)
    })).filter(option => option.value);

    const optionsB = toursB.map(entry => ({
        value: String(entry.id || ''),
        label: formatTourCompareOptionLabel(entry)
    })).filter(option => option.value);

    const valueA = populateTourCompareSelect(
        els.tourA,
        optionsA,
        toursA.length ? 'Bitte Tour wählen' : 'Keine Touren im Filter',
        previousA
    );

    const filteredOptionsB = optionsB.filter(option => option.value !== valueA);
    const valueB = populateTourCompareSelect(
        els.tourB,
        filteredOptionsB,
        toursB.length ? 'Bitte Tour wählen' : 'Keine Touren im Filter',
        previousB === valueA ? '' : previousB
    );

    if (valueB) {
        const filteredOptionsA = optionsA.filter(option => option.value !== valueB);
        populateTourCompareSelect(
            els.tourA,
            filteredOptionsA,
            toursA.length ? 'Bitte Tour wählen' : 'Keine Touren im Filter',
            valueA
        );
    }
}

function populateTourCompareFilters(preserveSelections = true) {
    const els = getTourCompareElements();
    if (!els.type || !els.region || !els.yearA || !els.yearB) return;

    const tours = [...(appStorage.get('touren') || [])]
        .filter(entry => getTourCompareDate(entry));

    const previous = {
        type: preserveSelections ? els.type.value : 'all',
        region: preserveSelections ? els.region.value : 'all',
        yearA: preserveSelections ? els.yearA.value : '',
        yearB: preserveSelections ? els.yearB.value : ''
    };

    const typeOrder = [
        'wandern',
        'klettersteig',
        'hike & climb',
        'bike & hike',
        'radtour',
        'mehrtägig'
    ];

    const types = Array.from(new Set(
        tours
            .map(entry => String(entry?.difficulty || '').trim().toLowerCase())
            .filter(Boolean)
    )).sort((a, b) => {
        const indexA = typeOrder.indexOf(a);
        const indexB = typeOrder.indexOf(b);
        const rankA = indexA === -1 ? 999 : indexA;
        const rankB = indexB === -1 ? 999 : indexB;
        return rankA - rankB || a.localeCompare(b, 'de');
    });

    els.type.innerHTML = `
        <option value="all">Alle Tourarten</option>
        ${types.map(value => `
            <option value="${escapeHtmlAttribute(value)}">
                ${escapeHtml(getTourCompareDifficultyLabel(value))}
            </option>
        `).join('')}
    `;
    els.type.value = types.includes(previous.type) ? previous.type : 'all';

    const regions = Array.from(new Set(
        tours
            .map(entry => String(entry?.region || '').trim())
            .filter(Boolean)
    )).sort((a, b) => a.localeCompare(b, 'de', { sensitivity: 'base' }));

    els.region.innerHTML = `
        <option value="all">Alle Regionen</option>
        ${regions.map(value => `
            <option value="${escapeHtmlAttribute(value)}">${escapeHtml(value)}</option>
        `).join('')}
    `;
    els.region.value = regions.includes(previous.region) ? previous.region : 'all';

    const years = Array.from(new Set(
        tours.map(entry => getTourCompareDate(entry)?.getFullYear()).filter(Number.isFinite)
    )).sort((a, b) => b - a);

    const defaultYear = years.includes(new Date().getFullYear())
        ? String(new Date().getFullYear())
        : String(years[0] || 'all');

    const yearOptions = [
        { value: 'all', label: 'Alle Jahre' },
        ...years.map(year => ({ value: String(year), label: String(year) }))
    ];

    const setYearOptions = (select, preferred) => {
        select.innerHTML = yearOptions.map(option => `
            <option value="${escapeHtmlAttribute(option.value)}">${escapeHtml(option.label)}</option>
        `).join('');

        const valid = yearOptions.some(option => option.value === preferred);
        select.value = valid ? preferred : defaultYear;
        syncTourCompareMobileSelect(select);
    };

    setYearOptions(els.yearA, previous.yearA || defaultYear);
    setYearOptions(els.yearB, previous.yearB || defaultYear);
    syncTourCompareMobileSelect(els.type);
    syncTourCompareMobileSelect(els.region);

    populateTourCompareTourSelects(preserveSelections);
}

function getTourCompareEntryById(id) {
    const wanted = String(id || '').trim();
    if (!wanted) return null;

    return (appStorage.get('touren') || []).find(entry =>
        String(entry?.id || '').trim() === wanted
    ) || null;
}

function getTourCompareProfile(entry, analysis) {
    if (!entry || !analysis) return '–';

    const id = String(entry.id || '').trim();
    const item = analysis.analyzed.find(candidate =>
        String(candidate.entry?.id || '').trim() === id
    );

    if (!item) return '–';
    const definition = getTourProfileDefinition(item.profileKey);
    return `${definition.icon} ${definition.label}`;
}

function getTourCompareMetrics(entry, profileAnalysis) {
    const distance = parseTourProfileNumber(entry?.strecke);
    const ascent = parseTourProfileNumber(entry?.aufstieg);
    const minutes = getEntryMinutesForDevelopment(entry);
    const timeHours = minutes > 0 ? minutes / 60 : null;
    const adjustedDistance = Number(getAdjustedDistance(entry)) || 0;
    const adjustedHours = Number(getAdjustedTimeHours(entry)) || 0;
    const performance = calculatePerformanceIndex(entry);

    return {
        type: getTourTypeDifficultyLabel(entry) || '–',
        region: String(entry?.region || '–'),
        profile: getTourCompareProfile(entry, profileAnalysis),
        distance: Number.isFinite(distance) && distance > 0 ? distance : null,
        ascent: Number.isFinite(ascent) && ascent >= 0 ? ascent : null,
        minutes: minutes > 0 ? minutes : null,
        speed:
            Number.isFinite(distance) && distance > 0 && Number.isFinite(timeHours) && timeHours > 0
                ? distance / timeHours
                : null,
        gradient:
            Number.isFinite(ascent) && ascent > 0 && adjustedDistance > 0
                ? ascent / adjustedDistance
                : null,
        ascentRate:
            Number.isFinite(ascent) && ascent > 0 && adjustedHours > 0
                ? ascent / adjustedHours
                : null,
        performance:
            performance && Number.isFinite(performance.score)
                ? Number(performance.score)
                : null,
        steps: Number(calculateEntrySteps(entry)) || 0
    };
}

function formatTourCompareTime(minutes) {
    if (!Number.isFinite(minutes) || minutes <= 0) return '–';
    return formatMinutesToHHMM(Math.round(minutes)) + ' h';
}

function formatTourCompareValue(value, kind) {
    if (value === null || value === undefined || !Number.isFinite(Number(value))) return '–';
    const number = Number(value);

    switch (kind) {
        case 'distance':
            return `${number.toFixed(1).replace('.', ',')} km`;
        case 'ascent':
            return `${Math.round(number)} hm`;
        case 'minutes':
            return formatTourCompareTime(number);
        case 'speed':
            return `${number.toFixed(2).replace('.', ',')} km/h`;
        case 'gradient':
            return `${Math.round(number)} hm/km`;
        case 'ascentRate':
            return `${Math.round(number)} hm/h`;
        case 'performance':
            return `${Math.round(number)} / 100`;
        case 'steps':
            return Math.round(number).toLocaleString('de-AT');
        default:
            return String(value);
    }
}

function formatTourCompareDifference(a, b, kind) {
    if (!Number.isFinite(a) || !Number.isFinite(b)) return '–';

    const diff = b - a;
    const sign = diff > 0.000001 ? '+' : diff < -0.000001 ? '−' : '±';
    const abs = Math.abs(diff);

    let absoluteText;
    switch (kind) {
        case 'distance':
            absoluteText = `${abs.toFixed(1).replace('.', ',')} km`;
            break;
        case 'ascent':
            absoluteText = `${Math.round(abs)} hm`;
            break;
        case 'minutes': {
            const rounded = Math.round(abs);
            const h = Math.floor(rounded / 60);
            const m = String(rounded % 60).padStart(2, '0');
            absoluteText = `${h}:${m} h`;
            break;
        }
        case 'speed':
            absoluteText = `${abs.toFixed(2).replace('.', ',')} km/h`;
            break;
        case 'gradient':
            absoluteText = `${Math.round(abs)} hm/km`;
            break;
        case 'ascentRate':
            absoluteText = `${Math.round(abs)} hm/h`;
            break;
        case 'performance':
            absoluteText = `${Math.round(abs)} Pkt.`;
            break;
        case 'steps':
            absoluteText = Math.round(abs).toLocaleString('de-AT');
            break;
        default:
            absoluteText = String(abs);
    }

    const percent = Math.abs(a) > 0.000001
        ? (diff / Math.abs(a)) * 100
        : null;

    const percentText = Number.isFinite(percent)
        ? ` · ${percent > 0 ? '+' : percent < 0 ? '−' : '±'}${Math.abs(percent).toFixed(1).replace('.', ',')} %`
        : '';

    return `<span class="tour-compare-delta">${sign}${absoluteText}${percentText}</span>`;
}

function renderTourComparison(entryA, entryB) {
    const result = getTourCompareElements().result;
    if (!result) return;

    const profileAnalysis = buildTourProfileAnalysis(appStorage.get('touren') || []);
    const a = getTourCompareMetrics(entryA, profileAnalysis);
    const b = getTourCompareMetrics(entryB, profileAnalysis);

    const row = (label, valueA, valueB, difference = '–') => `
        <div class="tour-compare-row">
            <div>${escapeHtml(label)}</div>
            <div>${valueA}</div>
            <div>${valueB}</div>
            <div>${difference}</div>
        </div>
    `;

    result.innerHTML = `
        <div class="tour-compare-table">
            <div class="tour-compare-row tour-compare-head">
                <div>Kennzahl</div>
                <div>Tour A</div>
                <div>Tour B</div>
                <div>Differenz</div>
            </div>

            ${row('Tourprofil', escapeHtml(a.profile), escapeHtml(b.profile))}
            ${row('Art der Tour', escapeHtml(a.type), escapeHtml(b.type))}
            ${row('Region', escapeHtml(a.region), escapeHtml(b.region))}
            ${row('Strecke', formatTourCompareValue(a.distance, 'distance'), formatTourCompareValue(b.distance, 'distance'), formatTourCompareDifference(a.distance, b.distance, 'distance'))}
            ${row('Aufstieg', formatTourCompareValue(a.ascent, 'ascent'), formatTourCompareValue(b.ascent, 'ascent'), formatTourCompareDifference(a.ascent, b.ascent, 'ascent'))}
            ${row('Gehzeit', formatTourCompareValue(a.minutes, 'minutes'), formatTourCompareValue(b.minutes, 'minutes'), formatTourCompareDifference(a.minutes, b.minutes, 'minutes'))}
            ${row('Geschwindigkeit', formatTourCompareValue(a.speed, 'speed'), formatTourCompareValue(b.speed, 'speed'), formatTourCompareDifference(a.speed, b.speed, 'speed'))}
            ${row('Steigung', formatTourCompareValue(a.gradient, 'gradient'), formatTourCompareValue(b.gradient, 'gradient'), formatTourCompareDifference(a.gradient, b.gradient, 'gradient'))}
            ${row('Anstieg / h', formatTourCompareValue(a.ascentRate, 'ascentRate'), formatTourCompareValue(b.ascentRate, 'ascentRate'), formatTourCompareDifference(a.ascentRate, b.ascentRate, 'ascentRate'))}
            ${row('Leistungsindex', formatTourCompareValue(a.performance, 'performance'), formatTourCompareValue(b.performance, 'performance'), formatTourCompareDifference(a.performance, b.performance, 'performance'))}
            ${row('Schritte', formatTourCompareValue(a.steps, 'steps'), formatTourCompareValue(b.steps, 'steps'), formatTourCompareDifference(a.steps, b.steps, 'steps'))}
        </div>
    `;

    result.hidden = false;
}

function runTourComparison() {
    const els = getTourCompareElements();
    const entryA = getTourCompareEntryById(els.tourA?.value);
    const entryB = getTourCompareEntryById(els.tourB?.value);

    if (!entryA || !entryB) {
        showToast('Bitte Tour A und Tour B auswählen.', {
            type: 'error',
            duration: 2600
        });
        return;
    }

    if (String(entryA.id) === String(entryB.id)) {
        showToast('Bitte zwei unterschiedliche Touren auswählen.', {
            type: 'error',
            duration: 2600
        });
        return;
    }

    renderTourComparison(entryA, entryB);
}

function initTourCompareFeature() {
    const els = getTourCompareElements();
    if (!els.run) return;

    populateTourCompareFilters(false);

    [els.type, els.region].forEach(select => {
        select?.addEventListener('change', () => {
            populateTourCompareTourSelects(false);
            clearTourCompareResult();
        });
    });

    [els.yearA, els.yearB].forEach(select => {
        select?.addEventListener('change', () => {
            populateTourCompareTourSelects(true);
            clearTourCompareResult();
        });
    });

    els.tourA?.addEventListener('change', () => {
        populateTourCompareTourSelects(true);
        clearTourCompareResult();
    });

    els.tourB?.addEventListener('change', () => {
        populateTourCompareTourSelects(true);
        clearTourCompareResult();
    });

    els.run.addEventListener('click', runTourComparison);
}

