function bridgeBodyBackButton(bodyId, headerBackId, selector) {
    const body = document.getElementById(bodyId);
    const headerBack = document.getElementById(headerBackId);
    if (!body || !headerBack) return;

    const sync = () => {
        const bodyBack = body.querySelector(selector);

        if (bodyBack) {
            bodyBack.classList.add('ux-bridged-back');
            headerBack.hidden = false;
            headerBack.dataset.uxBridge = '1';
            headerBack.onclick = () => bodyBack.click();
            return;
        }

        if (headerBack.dataset.uxBridge === '1') {
            headerBack.hidden = true;
            headerBack.onclick = null;
            delete headerBack.dataset.uxBridge;
        }
    };

    new MutationObserver(sync).observe(body, {
        childList: true,
        subtree: true
    });

    sync();
}

function initConsistentDrilldownNavigation() {
    bridgeBodyBackButton(
        'tl-body',
        'tl-back',
        '[id^="tl-back-"], #peak-tours-back'
    );

    bridgeBodyBackButton(
        'ds-body',
        'ds-header-back',
        '#ds-back, #peak-tours-back'
    );
}

let filterUiSaveTimer = null;

function captureFilterUiState() {
    const root = document.getElementById('filter-view');
    if (!root) return;

    const controls = {};

    root.querySelectorAll('input[id], select[id]').forEach(control => {
        if (!control.id || control.type === 'file') return;

        controls[control.id] = control.type === 'checkbox'
            ? Boolean(control.checked)
            : String(control.value ?? '');
    });

    appStorage.set(FILTER_UI_STATE_KEY, controls);
}

function scheduleFilterUiStateSave() {
    clearTimeout(filterUiSaveTimer);
    filterUiSaveTimer = setTimeout(captureFilterUiState, 220);
}

function restoreFilterUiState() {
    const root = document.getElementById('filter-view');
    const saved = appStorage.get(FILTER_UI_STATE_KEY);
    if (!root || !saved || typeof saved !== 'object') return;

    const deferredTourSelects = [];

    Object.entries(saved).forEach(([id, value]) => {
        const control = document.getElementById(id);
        if (!control || !root.contains(control)) return;

        if (id === 'tour-compare-a' || id === 'tour-compare-b') {
            deferredTourSelects.push([control, value]);
            return;
        }

        if (control.type === 'checkbox') {
            control.checked = Boolean(value);
        } else if (
            control.tagName === 'SELECT' &&
            !Array.from(control.options).some(option => option.value === String(value))
        ) {
            return;
        } else {
            control.value = String(value ?? '');
        }

        control.dispatchEvent(new Event('change', { bubbles: true }));
        if (control.tagName === 'INPUT' && control.type !== 'checkbox') {
            control.dispatchEvent(new Event('input', { bubbles: true }));
        }
    });

    requestAnimationFrame(() => {
        deferredTourSelects.forEach(([control, value]) => {
            if (Array.from(control.options).some(option => option.value === String(value))) {
                control.value = String(value);
                control.dispatchEvent(new Event('change', { bubbles: true }));
            }
        });
    });
}

function initFilterViewPersistence() {
    const root = document.getElementById('filter-view');
    if (!root) return;

    root.addEventListener('change', scheduleFilterUiStateSave);
    root.addEventListener('input', scheduleFilterUiStateSave);

    requestAnimationFrame(restoreFilterUiState);
}

function sortEntries(arr) {

    if (!Array.isArray(arr)) {
        return [];
    }

    /*
     * Einheitliche Standardsortierung:
     * neueste Tour zuerst.
     *
     * Keine Abhängigkeit mehr vom
     * ehemaligen Filter-State.
     */
    arr.sort((a, b) => {

        const timeA =
            new Date(
                a?.date || 0
            ).getTime();

        const timeB =
            new Date(
                b?.date || 0
            ).getTime();


        const safeA =
            Number.isFinite(timeA)
                ? timeA
                : 0;

        const safeB =
            Number.isFinite(timeB)
                ? timeB
                : 0;


        return safeB - safeA;
    });


    return arr;
}


function getAllSavedTours() {
    return appStorage.get('touren') || [];
}

function populateCompareOptions() {
    const tours = getAllSavedTours();
    const years = new Set();

    tours.forEach(entry => {
        if (!entry.date) return;
        const d = new Date(entry.date);
        if (isNaN(d.getTime())) return;
        years.add(d.getFullYear());
    });

    const sortedYears = Array.from(years).sort((a, b) => b - a);

    const yearSelects = [compareYearA, compareYearB, compareMonthYearA, compareMonthYearB];
    yearSelects.forEach(select => {
        if (!select) return;
        const current = select.value;
        select.innerHTML = '<option value="">Bitte wählen</option>';

        sortedYears.forEach(year => {
            const opt = document.createElement('option');
            opt.value = String(year);
            opt.textContent = String(year);
            select.appendChild(opt);
        });

        if (current && sortedYears.includes(Number(current))) {
            select.value = current;
        }
    });

    const monthSelects = [compareMonthA, compareMonthB];
    monthSelects.forEach(select => {
        if (!select) return;
        const current = select.value;
        select.innerHTML = '<option value="">Bitte wählen</option>';

        COMPARE_MONTH_NAMES.forEach((name, index) => {
            const opt = document.createElement('option');
            opt.value = String(index + 1);
            opt.textContent = name;
            select.appendChild(opt);
        });

        if (current) {
            select.value = current;
        }
    });

    const seasonYears = new Set(sortedYears);

    tours.forEach(entry => {
        const d = parseStatsCalendarDate(entry?.date);
        if (!d) return;

        /* Dezember gehört zum Winter des Folgejahres. */
        if (d.getMonth() === 11) {
            seasonYears.add(d.getFullYear() + 1);
        }
    });

    const sortedSeasonYears =
        Array.from(seasonYears)
            .sort((a, b) => b - a);

    [compareSeasonYearA, compareSeasonYearB, compareSeasonYearAll]
        .forEach(select => {
            if (!select) return;

            const current = select.value;
            select.innerHTML = '<option value="">Bitte wählen</option>';

            sortedSeasonYears.forEach(year => {
                const opt = document.createElement('option');
                opt.value = String(year);
                opt.textContent = String(year);
                select.appendChild(opt);
            });

            if (
                current &&
                sortedSeasonYears.includes(Number(current))
            ) {
                select.value = current;
            }
        });

    [compareSeasonA, compareSeasonB]
        .forEach(select => {
            if (!select) return;

            const current = select.value;
            select.innerHTML = '<option value="">Bitte wählen</option>';

            COMPARE_SEASONS.forEach(season => {
                const opt = document.createElement('option');
                opt.value = season.value;
                opt.textContent = season.label;
                select.appendChild(opt);
            });

            if (current) {
                select.value = current;
            }
        });
}

function setCompareMode(mode, save = true) {
    const validModes = ['years', 'months', 'seasons', 'seasonYear'];
    compareMode = validModes.includes(mode) ? mode : 'years';

    if (save) {
        appStorage.set(COMPARE_MODE_KEY, compareMode);
    }

    mode = compareMode;

    if (compareInlineResult) {
        compareInlineResult.innerHTML = '';
        compareInlineResult.hidden = true;
    }

    document.querySelectorAll('.compare-mode-btn').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.compareMode === mode);
    });

    compareYearsPanel?.classList.toggle(
    'is-hidden',
    mode !== 'years'
);

compareMonthsPanel?.classList.toggle(
    'is-hidden',
    mode !== 'months'
);

compareSeasonsPanel?.classList.toggle(
    'is-hidden',
    mode !== 'seasons'
);

compareSeasonYearPanel?.classList.toggle(
    'is-hidden',
    mode !== 'seasonYear'
);
}

function getEntriesForCompareSelection(side) {
    const tours = getAllSavedTours();

    if (compareMode === 'years') {
        const year = side === 'a' ? compareYearA?.value : compareYearB?.value;
        if (!year) return null;

        return tours.filter(entry => {
            if (!entry.date) return false;
            const d = new Date(entry.date);
            if (isNaN(d.getTime())) return false;
            return d.getFullYear() === Number(year);
        });
    }

    if (compareMode === 'seasons') {
        const season =
            side === 'a'
                ? compareSeasonA?.value
                : compareSeasonB?.value;

        const year =
            side === 'a'
                ? compareSeasonYearA?.value
                : compareSeasonYearB?.value;

        if (!season || !year) return null;

        return tours.filter(entry =>
            entryMatchesCompareSeason(
                entry,
                season,
                Number(year)
            )
        );
    }

    const month = side === 'a' ? compareMonthA?.value : compareMonthB?.value;
    const year = side === 'a' ? compareMonthYearA?.value : compareMonthYearB?.value;

    if (!month || !year) return null;

    return tours.filter(entry => {
        if (!entry.date) return false;
        const d = new Date(entry.date);
        if (isNaN(d.getTime())) return false;

        return (
            d.getFullYear() === Number(year) &&
            (d.getMonth() + 1) === Number(month)
        );
    });
}



function formatMinutesToHHMM(totalMinutes) {
    const mins = Math.round(totalMinutes || 0);
    const h = Math.floor(mins / 60);
    const m = mins % 60;
    return `${h}:${String(m).padStart(2, '0')}`;
}



function computeStatsSummary(entries) {
    let totalDistance = 0;
    let totalAscent = 0;
    let totalMinutes = 0;
    let totalPeaks = 0;
    let totalSteps = 0;

    let distanceCount = 0;
    let ascentCount = 0;
    let timeCount = 0;
    let stepsCount = 0;

    let peaks2000 = 0;
    let peaks2500 = 0;
    let peaks3000 = 0;

    let gradSum = 0;
    let gradWeight = 0;

    let ascentRateSum = 0;
let ascentRateWeight = 0;

let performanceSum = 0;
let performanceWeight = 0;

let bigTours = 0;

    entries.forEach(entry => {
        const dist = entry.strecke ? parseFloat(String(entry.strecke).replace(',', '.')) || 0 : 0;
        const asc = entry.aufstieg ? parseFloat(String(entry.aufstieg).replace(',', '.')) || 0 : 0;
        const entrySteps = calculateEntrySteps(entry);

        totalDistance += dist;
        totalAscent += asc;
        totalPeaks += parseInt(entry.gipfel) || 0;
        totalSteps += entrySteps;

        if (dist > 0) distanceCount++;
        if (String(entry.aufstieg ?? '').trim() !== '') ascentCount++;
        if (entrySteps > 0) stepsCount++;

if (isBigTourCountable(entry, entries)) {
    bigTours++;
}


/*
 * Leistungsindex der Tour
 */
const performance =
    calculatePerformanceIndex(
        entry
    );

const performanceScore =
    performance &&
    Number.isFinite(
        performance.score
    )
        ? performance.score
        : null;

if (performanceScore !== null) {
    performanceSum +=
        performanceScore;

    performanceWeight++;
}

        if (entry.zeit && entry.zeit.includes(':')) {
            const [h, m] = entry.zeit.split(':').map(Number);
            const entryMinutes = h * 60 + m;
            if (Number.isFinite(entryMinutes) && entryMinutes > 0) {
                totalMinutes += entryMinutes;
                timeCount++;
            }
        }

        if (entry.gipfelDetails && Array.isArray(entry.gipfelDetails)) {
            entry.gipfelDetails.forEach(g => {
                const height = parsePeakHeight(g.hoehe);

                if (height >= 2000 && height <= 2499) peaks2000++;
                else if (height >= 2500 && height <= 2999) peaks2500++;
                else if (height >= 3000) peaks3000++;
            });
        }

        const ascAdj = getAdjustedAscent(entry);
        const distAdj = getAdjustedDistance(entry);
        const hoursAdj = getAdjustedTimeHours(entry);

        if (distAdj > 0 && ascAdj > 0) {
            gradSum += ascAdj / distAdj;
            gradWeight++;
        }

        if (hoursAdj > 0 && ascAdj > 0) {
            ascentRateSum += ascAdj / hoursAdj;
            ascentRateWeight++;
        }
    });

    const totalHours = totalMinutes / 60;
    const avgDistance = distanceCount > 0 ? totalDistance / distanceCount : 0;
    const avgAscent = ascentCount > 0 ? totalAscent / ascentCount : 0;
    const avgMinutes = timeCount > 0 ? totalMinutes / timeCount : 0;
    const avgSteps = stepsCount > 0 ? totalSteps / stepsCount : 0;
    const avgSpeed = totalHours > 0 ? totalDistance / totalHours : 0;
    const avgGradient = gradWeight > 0 ? gradSum / gradWeight : 0;
    const avgAscentPerHour = ascentRateWeight > 0 ? ascentRateSum / ascentRateWeight : 0;

    const avgPerformanceIndex =
    performanceWeight > 0
        ? performanceSum /
          performanceWeight
        : null;

    return {
        totalTours: countDistinctTours(entries),
        bigTours,
        totalPeaks,
        totalSteps,
        peaks2000,
        peaks2500,
        peaks3000,
        totalDistance,
        totalAscent,
        totalMinutes,
        totalTimeText: formatMinutesToHHMM(totalMinutes),
        avgDistance,
        avgAscent,
        avgMinutes,
        avgSteps,
        avgSpeed,
        avgGradient,
        avgAscentPerHour,
        avgPerformanceIndex,
    };
}

// ================== PDF-Tourenbuch: Datenfunktionen ==================

function getToursInYearRange(fromYear, toYear) {
    const from = Math.min(fromYear, toYear);
    const to = Math.max(fromYear, toYear);

    return getAllSavedTours()
        .filter(entry => {
            const date = parseStatsCalendarDate(entry?.date);
            if (!date) return false;
            const year = date.getFullYear();
            return year >= from && year <= to;
        })
        .sort((a, b) => parseStatsCalendarDate(a.date) - parseStatsCalendarDate(b.date));
}

function getPdfExportAvailableYears() {
    const years = new Set();
    getAllSavedTours().forEach(entry => {
        const date = parseStatsCalendarDate(entry?.date);
        if (date) years.add(date.getFullYear());
    });
    return Array.from(years).sort((a, b) => b - a);
}

function buildPdfYearOverviewRows(fromYear, toYear) {
    const rows = [];
    for (let year = fromYear; year <= toYear; year++) {
        const entries = getToursInYearRange(year, year);
        if (!entries.length) continue;
        const stats = computeStatsSummary(entries);
        rows.push([
            String(year),
            String(stats.totalTours),
            `${stats.totalDistance.toFixed(1).replace('.', ',')} km`,
            `${Math.round(stats.totalAscent)} hm`,
            `${stats.totalTimeText} h`,
            Math.round(stats.totalSteps).toLocaleString('de-AT'),
            String(stats.totalPeaks)
        ]);
    }
    return rows;
}


function getPdfRepresentativePhoto(entries) {
    const withPhotos = entries.filter(e => e.imageData);
    if (!withPhotos.length) return null;

    let best = withPhotos[0];
    let bestScore = -Infinity;

    withPhotos.forEach(entry => {
        const perf = calculatePerformanceIndex(entry);
        const score = perf && Number.isFinite(perf.score) ? perf.score : -1;
        if (score > bestScore) {
            bestScore = score;
            best = entry;
        }
    });

    return best;
}

function formatDelta(a, b, decimals = 0, suffix = '') {
    const diff = b - a;

    if (Math.abs(diff) < 0.000001) {
        return `<span class="compare-delta neutral">±0${suffix}</span>`;
    }

    const cls = diff > 0 ? 'positive' : 'negative';
    const sign = diff > 0 ? '+' : '';
    return `<span class="compare-delta ${cls}">${sign}${diff.toFixed(decimals).replace('.', ',')}${suffix}</span>`;
}

function formatTimeDelta(minutesA, minutesB) {
    const diff = Math.round(minutesB - minutesA);

    if (diff === 0) {
        return `<span class="compare-delta neutral">±0:00 h</span>`;
    }

    const cls  = diff > 0 ? 'positive' : 'negative';
    const sign = diff > 0 ? '+' : '-';

    const absDiff = Math.abs(diff);
    const h = Math.floor(absDiff / 60);
    const m = absDiff % 60;

    const timeStr = `${h}:${String(m).padStart(2, '0')}`;

    return `<span class="compare-delta ${cls}">${sign}${timeStr} h</span>`;
}



function renderCompareInline(html) {
    if (!compareInlineResult) return;

    compareInlineResult.innerHTML = html;
    compareInlineResult.hidden = false;
}



function closeCompareModal() {
    const compareModal = document.getElementById('compare-modal');
    const compareModalBody = document.getElementById('compare-modal-body');

    if (!compareModal || !compareModalBody) return;

    compareModal.classList.add('hidden');
    compareModalBody.innerHTML = '';
    document.body.classList.remove('modal-open');
}


function runFourSeasonComparison() {
    const year = Number(compareSeasonYearAll?.value);

    if (!Number.isFinite(year) || year <= 0) {
        showToast(
            'Bitte ein Jahr für den Jahreszeitenvergleich auswählen.',
            {
                type: 'error',
                duration: 3000
            }
        );
        return;
    }

    const tours = getAllSavedTours();

    const seasonResults = COMPARE_SEASONS.map(season => {
        const entries = tours.filter(entry =>
            entryMatchesCompareSeason(entry, season.value, year)
        );

        return {
            ...season,
            stats: computeStatsSummary(entries)
        };
    });

    const values = formatter =>
        seasonResults
            .map(item => `<div>${formatter(item.stats)}</div>`)
            .join('');

    const row = (label, formatter) => `
        <div class="compare-row compare-four-seasons">
            <div class="compare-label">${label}</div>
            ${values(formatter)}
        </div>
    `;

    const html = `
        <div class="compare-table compare-four-seasons-table">
            <div class="compare-row compare-head compare-four-seasons">
                <div>Kennzahl</div>
                ${seasonResults.map(item => `<div>${escapeHtml(item.label)}</div>`).join('')}
            </div>

            ${row('Anzahl Touren', s => s.totalTours)}
            ${row('Big Tours', s => s.bigTours)}
            ${row('Gipfel gesamt', s => s.totalPeaks)}
            ${row('Gipfel ab 2000 m', s => s.peaks2000)}
            ${row('Gipfel ab 2500 m', s => s.peaks2500)}
            ${row('Gipfel ab 3000 m', s => s.peaks3000)}
            ${row('Gesamtstrecke', s => `${s.totalDistance.toFixed(1).replace('.', ',')} km`)}
            ${row('Ø Strecke', s => `${s.avgDistance.toFixed(1).replace('.', ',')} km`)}
            ${row('Gesamtaufstieg', s => `${Math.round(s.totalAscent)} hm`)}
            ${row('Ø Aufstieg', s => `${Math.round(s.avgAscent)} hm`)}
            ${row('Gesamtzeit', s => `${s.totalTimeText} h`)}
            ${row('Ø Gehzeit', s => `${formatMinutesToHHMM(s.avgMinutes)} h`)}
            ${row('Schritte gesamt', s => Math.round(s.totalSteps).toLocaleString('de-AT'))}
            ${row('Ø Schritte', s => Math.round(s.avgSteps).toLocaleString('de-AT'))}
            ${row('Ø Leistungsindex', s => Number.isFinite(s.avgPerformanceIndex) ? `${Math.round(s.avgPerformanceIndex)} / 100` : '–')}
            ${row('Ø Geschwindigkeit', s => `${s.avgSpeed.toFixed(2).replace('.', ',')} km/h`)}
            ${row('Ø Steigung', s => `${s.avgGradient.toFixed(0)} hm/km`)}
            ${row('Ø Anstieg', s => `${s.avgAscentPerHour.toFixed(0)} hm/h`)}
        </div>
    `;

    renderCompareInline(html);
}

