function getMobileSavedTourPageCount() {
    const allTours = sortEntries(
        groupEntriesForDisplay(getFilteredData(), 'saved')
    );

    return Math.max(
        1,
        Math.ceil(allTours.length / PAGE_SIZE)
    );
}

function scrollSavedTourListToTop() {
    const listBox = document.getElementById('saved-tours-list');
    const scrollContainer = listBox?.closest('.view');

    if (!listBox || !scrollContainer) return;

    function scrollToListTop() {
        const containerRect = scrollContainer.getBoundingClientRect();
        const listRect = listBox.getBoundingClientRect();

        /*
         * Absolute Position der Tourenliste innerhalb
         * des scrollenden View-Containers.
         */
        const targetTop =
            scrollContainer.scrollTop +
            listRect.top -
            containerRect.top;

        scrollContainer.scrollTop = Math.max(0, targetTop);
    }

    /*
     * Nach dem Rendern mehrfach korrigieren.
     * "auto" verhindert, dass ein vorheriger Smooth-Scroll
     * die neue Position wieder überschreibt.
     */
    requestAnimationFrame(() => {
        scrollToListTop();

        requestAnimationFrame(() => {
            scrollToListTop();

            setTimeout(() => {
                scrollToListTop();
            }, 80);

            setTimeout(() => {
                scrollToListTop();
            }, 250);
        });
    });
}

