// ─── Dashboard Stat Modal ────────────────────────────────────────────────────

function closeDashStatModal() {
    const modal = document.getElementById('dash-stat-modal');
    if (!modal) return;
    modal.classList.add('hidden');
    document.body.classList.remove('modal-open');
}

function openDashStatModal(type, tours) {
    const modal   = document.getElementById('dash-stat-modal');
    const titleEl = document.getElementById('ds-title');
    const bodyEl  = document.getElementById('ds-body');
    if (!modal || !titleEl || !bodyEl) return;

    const MN = ['Jän','Feb','Mär','Apr','Mai','Jun','Jul','Aug','Sep','Okt','Nov','Dez'];
    const n  = tours.length;

    function row(label, value, sub = false, id = '') {
        const cls = sub ? ' class="stats-sub"' : (id ? ' class="highlight-clickable"' : '');
        const idAttr = id ? ` id="${id}"` : '';
        return `<li${cls}${idAttr}>
            <span class="stats-label">${label}</span>
            <span class="stats-value">${value}</span>
        </li>`;
    }

    function sectionTitle(text) {
        return `<div style="margin-top:12px;font-size:11px;font-weight:700;opacity:.6;margin-bottom:6px;letter-spacing:.3px;">${text}</div>`;
    }
    function monthRow(label, value, mi) {
        return `<li class="highlight-clickable" data-month-idx="${mi}">
            <span class="stats-label">${label}</span>
            <span class="stats-value">${value}</span>
        </li>`;
    }

    function monthRows(countFn, valueFn) {
    const MN = ['Jän','Feb','Mär','Apr','Mai','Jun','Jul','Aug','Sep','Okt','Nov','Dez'];
    const mc = Array(12).fill(0);
    tours.forEach(e => { try { mc[new Date(e.date).getMonth()] += countFn(e); } catch {} });
    return MN.map((n, i) => mc[i] > 0
        ? `<li class="highlight-clickable" data-month-idx="${i}">
               <span class="stats-label">${n}</span>
               <span class="stats-value">${valueFn(mc[i])}</span>
           </li>` : '').join('');
    }

    let title = '';
    let bodyHtml = '';
    let specialEntries = [];   // für data-sentry click handler

    switch (type) {

        // ── Touren ───────────────────────────────────────────────────
        case 'touren': {
            title = '🥾 Alle Touren';
            const sorted = [...tours].sort((a, b) => new Date(b.date) - new Date(a.date));
            specialEntries = sorted;
            bodyHtml = `
                <ul class="stats-list">${row('Anzahl Touren', countDistinctTours(tours), false, 'ds-total-row')}</ul>
                ${sectionTitle('NACH MONAT')}
                <ul class="stats-list">
                    ${monthRows(
                        e => (e.tourGroup ? (isFirstEtappeInList(e, tours) ? 1 : 0) : 1),
                        v => v + (v === 1 ? ' Tour' : ' Touren')
                    )}
                </ul>`;
            break;
        }

// ── Schritte ────────────────────────────────────────────────
        case 'steps': {
            title = '👣 Schritte';

            const monthSteps = Array(12).fill(0);
            let totalSteps = 0;

            tours.forEach(e => {
                const steps =
                    Number(calculateEntrySteps(e)) || 0;

                totalSteps += steps;

                if (!e.date) return;

                const date = new Date(e.date);
                if (isNaN(date.getTime())) return;

                monthSteps[date.getMonth()] += steps;
            });

            const averageSteps =
                n > 0
                    ? totalSteps / n
                    : 0;

            bodyHtml = `
                <ul class="stats-list">
                    ${row(
                        'Schritte gesamt',
                        Math.round(totalSteps)
                            .toLocaleString('de-AT'),
                        false,
                        'ds-total-row'
                    )}

                    ${row(
                        'Ø Schritte / Tour',
                        Math.round(averageSteps)
                            .toLocaleString('de-AT'),
                        true
                    )}

                    ${monthSteps.map((value, i) => {
                        if (value <= 0) return '';

                        return monthRow(
                            MN[i],
                            Math.round(value)
                                .toLocaleString('de-AT') +
                                ' Schritte',
                            i
                        );
                    }).join('')}
                </ul>
            `;

            break;
        }

        // ── Gipfel ───────────────────────────────────────────────────
        case 'gipfel': {
            title = '🏔️ Gipfel';
            let p2000 = 0, p2500 = 0, p3000 = 0;
            let allPeaks = [];
            tours.forEach(e => {
                (e.gipfelDetails || []).forEach(g => {
                    const h = parsePeakHeight(g.hoehe);
                    allPeaks.push({ name: g.name || '–', hoehe: h, entry: e });
                    if      (h >= 3000) p3000++;
                    else if (h >= 2500) p2500++;
                    else if (h >= 2000) p2000++;
                });
            });
            allPeaks.sort((a, b) => b.hoehe - a.hoehe);
            const seen = new Set();
            const uniquePeaks = allPeaks.filter(p => {
                const k = (p.name + p.hoehe).toLowerCase();
                if (seen.has(k)) return false;
                seen.add(k); return true;
            });
            const totalPeaks = tours.reduce((s, e) => s + (parseInt(e.gipfel) || 0), 0);
            specialEntries = uniquePeaks.map(p => p.entry);
            bodyHtml = `
                <ul class="stats-list">
                    ${row('Gipfel gesamt', totalPeaks, false, 'ds-total-row')}
                    ${p3000 > 0 ? `
    <li
        class="highlight-clickable peak-tier-3 stats-peak-row"
        data-peak-min="3000"
        data-peak-max=""
        data-peak-title="Gipfel über 3000 m">
        <span class="stats-label">über 3000 m</span>
        <span class="stats-value">${p3000}</span>
    </li>
` : ''}

${p2500 > 0 ? `
    <li
        class="highlight-clickable peak-tier-2 stats-peak-row"
        data-peak-min="2500"
        data-peak-max="2999"
        data-peak-title="Gipfel über 2500 m">
        <span class="stats-label">über 2500 m</span>
        <span class="stats-value">${p2500}</span>
    </li>
` : ''}

${p2000 > 0 ? `
    <li
        class="highlight-clickable peak-tier-1 stats-peak-row"
        data-peak-min="2000"
        data-peak-max="2499"
        data-peak-title="Gipfel über 2000 m">
        <span class="stats-label">über 2000 m</span>
        <span class="stats-value">${p2000}</span>
    </li>
` : ''}
                </ul>
                ${sectionTitle('NACH MONAT')}
                <ul class="stats-list">
                    ${monthRows(
                        e => (e.gipfelDetails || []).length || parseInt(e.gipfel) || 0,
                        v => v + ' Gipfel'
                    )}
                </ul>`;
            break;
        }

        // ── Big Tours ────────────────────────────────────────────────
        case 'bigTours': {
            title = '💪🏼 Big Tours';
            const big = [...tours]
                .filter(e => isBigTourCountable(e, tours))
                .sort((a, b) => new Date(b.date) - new Date(a.date));
            specialEntries = big;
            bodyHtml = `
                <ul class="stats-list">${row('Anzahl Big Tours', big.length, false, 'ds-total-row')}</ul>
                ${sectionTitle('NACH MONAT')}
                <ul class="stats-list">
                    ${monthRows(
                        e => isBigTourCountable(e, tours) ? 1 : 0,
                        v => v + (v === 1 ? ' Tour' : ' Touren')
                    )}
                </ul>`;
            break;
        }

        // ── Strecke ──────────────────────────────────────────────────
        case 'strecke': {
            title = '📏 Strecke';
            const mS = Array(12).fill(0);
            let total = 0;
            tours.forEach(e => {
                const d = parseFloat(String(e.strecke || '').replace(',', '.')) || 0;
                if (d > 0 && e.date) {
                    const m = new Date(e.date).getMonth();
                    if (!isNaN(m)) { mS[m] += d; total += d; }
                }
            });
            const avg = n > 0 ? total / n : 0;
            bodyHtml = `<ul class="stats-list">
                ${row('Gesamtstrecke',    total.toFixed(1).replace('.', ',') + ' km', false, 'ds-total-row')}
                ${row('Ø Strecke / Tour', formatDecimalAT(avg) + ' km', true)}
                ${mS.map((v, i) => v > 0 ? monthRow(MN[i], v.toFixed(1).replace('.', ',') + ' km', i) : '').join('')}
            </ul>`;
            break;
        }

        // ── Aufstieg ─────────────────────────────────────────────────
        case 'aufstieg': {
            title = '⛰️ Aufstieg';
            const mA = Array(12).fill(0);
            let total = 0;
            tours.forEach(e => {
                const a = parseFloat(String(e.aufstieg || '').replace(',', '.')) || 0;
                if (a > 0 && e.date) {
                    const m = new Date(e.date).getMonth();
                    if (!isNaN(m)) { mA[m] += a; total += a; }
                }
            });
            const avg = n > 0 ? total / n : 0;
            bodyHtml = `<ul class="stats-list">
                ${row('Gesamtaufstieg',    Math.round(total).toLocaleString('de-AT') + ' hm', false, 'ds-total-row')}
                ${row('Ø Aufstieg / Tour', Math.round(avg).toLocaleString('de-AT')   + ' hm', true)}
                ${mA.map((v, i) => v > 0 ? monthRow(MN[i], Math.round(v).toLocaleString('de-AT') + ' hm', i) : '').join('')}
            </ul>`;
            break;
        }

        // ── Gehzeit ──────────────────────────────────────────────────
        case 'gehzeit': {
            title = '⏱️ Gehzeit';
            const mM = Array(12).fill(0);
            let totalMin = 0;
            tours.forEach(e => {
                if (!e.zeit || !e.zeit.includes(':') || !e.date) return;
                const [h, m] = e.zeit.split(':').map(Number);
                if (isNaN(h) || isNaN(m)) return;
                const mins = h * 60 + m;
                const mi   = new Date(e.date).getMonth();
                if (!isNaN(mi)) { mM[mi] += mins; totalMin += mins; }
            });
            const avgMin = n > 0 ? totalMin / n : 0;
            const fmt = mins =>
                `${Math.floor(mins / 60)}:${String(Math.round(mins % 60)).padStart(2, '0')} h`;
            bodyHtml = `<ul class="stats-list">
                ${row('Gehzeit gesamt',   fmt(totalMin), false, 'ds-total-row')}
                ${row('Ø Gehzeit / Tour', fmt(avgMin), true)}
                ${mM.map((v, i) => v > 0 ? monthRow(MN[i], fmt(v), i) : '').join('')}
            </ul>`;
            break;
        }

        // ── Speed ────────────────────────────────────────────────────
        case 'speed': {
            title = '💨 Ø Geschwindigkeit';
            const mDist = Array(12).fill(0), mMin = Array(12).fill(0);
            let fast = null, slow = null;
            tours.forEach(e => {
                const d = parseFloat(String(e.strecke || '').replace(',', '.')) || 0;
                if (!d || !e.zeit || !e.zeit.includes(':') || !e.date) return;
                const [h, m] = e.zeit.split(':').map(Number);
                if (isNaN(h) || isNaN(m)) return;
                const timeH = (h * 60 + m) / 60;
                if (timeH <= 0) return;
                const speed = d / timeH;
                const mi = new Date(e.date).getMonth();
                if (!isNaN(mi)) { mDist[mi] += d; mMin[mi] += h * 60 + m; }
                if (!fast || speed > fast.v) fast = { v: speed, entry: e };
                if (!slow || speed < slow.v) slow = { v: speed, entry: e };
            });
            const mSpeeds = mDist.map((d, i) => mMin[i] > 0 ? d / (mMin[i] / 60) : 0);
            specialEntries = [fast?.entry || null, slow?.entry || null];
            bodyHtml = `<ul class="stats-list">
                ${fast ? `<li class="highlight-clickable" data-sentry="0">
                    <span class="stats-label">🏆 Schnellste · ${escapeHtml(fast.entry.tourname||'–')}</span>
                    <span class="stats-value">${formatDecimalAT(fast.v)} km/h</span></li>` : ''}
                ${slow ? `<li class="highlight-clickable" data-sentry="1">
                    <span class="stats-label">🐢 Langsamste · ${escapeHtml(slow.entry.tourname||'–')}</span>
                    <span class="stats-value">${formatDecimalAT(slow.v)} km/h</span></li>` : ''}
                ${mSpeeds.map((v, i) =>
    v > 0
        ? monthRow(
            MN[i],
            formatDecimalAT(v) + ' km/h',
            i
        )
        : ''
).join('')}
            </ul>`;
            break;
        }

        // ── Steigung ─────────────────────────────────────────────────
        case 'steigung': {
            title = '📐 Ø Steigung';
            const mGS = Array(12).fill(0), mGC = Array(12).fill(0);
            let steep = null, flat = null;
            tours.forEach(e => {
                const asc  = getAdjustedAscent(e);
                const dist = getAdjustedDistance(e);
                if (asc <= 0 || dist <= 0 || !e.date) return;
                const g = asc / dist;
                const mi = new Date(e.date).getMonth();
                if (!isNaN(mi)) { mGS[mi] += g; mGC[mi]++; }
                if (!steep || g > steep.v) steep = { v: g, entry: e };
                if (!flat  || g < flat.v)  flat  = { v: g, entry: e };
            });
            specialEntries = [steep?.entry || null, flat?.entry || null];
            bodyHtml = `<ul class="stats-list">
                ${steep ? `<li class="highlight-clickable" data-sentry="0">
                    <span class="stats-label">🏔️ Steilste · ${escapeHtml(steep.entry.tourname||'–')}</span>
                    <span class="stats-value">${Math.round(steep.v)} hm/km</span></li>` : ''}
                ${flat  ? `<li class="highlight-clickable" data-sentry="1">
                    <span class="stats-label">🌄 Flachste · ${escapeHtml(flat.entry.tourname||'–')}</span>
                    <span class="stats-value">${Math.round(flat.v)} hm/km</span></li>` : ''}
                ${mGS.map((s, i) => {
                    const v = mGC[i] > 0 ? s / mGC[i] : 0;
                    return v > 0 ? monthRow(MN[i], Math.round(v) + ' hm/km', i) : '';
                }).join('')}
            </ul>`;
            break;
        }

        // ── Anstieg ──────────────────────────────────────────────────
        case 'anstieg': {
            title = '⬆️ Ø Anstieg';
            const mRS = Array(12).fill(0), mRC = Array(12).fill(0);
            let fast = null, slow = null;
            tours.forEach(e => {
                const asc  = getAdjustedAscent(e);
                const time = getAdjustedTimeHours(e);
                if (asc <= 0 || time <= 0 || !e.date) return;
                const rate = asc / time;
                const mi   = new Date(e.date).getMonth();
                if (!isNaN(mi)) { mRS[mi] += rate; mRC[mi]++; }
                if (!fast || rate > fast.v) fast = { v: rate, entry: e };
                if (!slow || rate < slow.v) slow = { v: rate, entry: e };
            });
            specialEntries = [fast?.entry || null, slow?.entry || null];
            bodyHtml = `<ul class="stats-list">
                ${fast ? `<li class="highlight-clickable" data-sentry="0">
                    <span class="stats-label">⚡ Schnellster · ${escapeHtml(fast.entry.tourname||'–')}</span>
                    <span class="stats-value">${Math.round(fast.v)} hm/h</span></li>` : ''}
                ${slow ? `<li class="highlight-clickable" data-sentry="1">
                    <span class="stats-label">🐌 Langsamster · ${escapeHtml(slow.entry.tourname||'–')}</span>
                    <span class="stats-value">${Math.round(slow.v)} hm/h</span></li>` : ''}
                ${mRS.map((s, i) => {
                    const v = mRC[i] > 0 ? s / mRC[i] : 0;
                    return v > 0 ? monthRow(MN[i], Math.round(v) + ' hm/h', i) : '';
                }).join('')}
            </ul>`;
            break;
        }
    }

    titleEl.textContent = title;
    bodyEl.innerHTML    = bodyHtml;

    // Gipfel-Höhenklassen anklickbar
bodyEl.querySelectorAll('[data-peak-min]').forEach(el => {
    el.style.cursor = 'pointer';

    el.addEventListener('click', () => {
        const minH = Number(el.dataset.peakMin);

        const maxH =
            el.dataset.peakMax === ''
                ? null
                : Number(el.dataset.peakMax);

        const tierTitle =
            el.dataset.peakTitle || 'Gipfel';

        showDashPeakTier(
            minH,
            maxH,
            tours,
            tierTitle,
            title
        );
    });
});

    // Click-Handler für alle anklickbaren Zeilen
    bodyEl.querySelectorAll('[data-sentry]').forEach(el => {
        const idx   = parseInt(el.dataset.sentry);
        const entry = specialEntries[idx];
        if (!entry) return;
        el.style.cursor = 'pointer';
        el.addEventListener('click', () => {
    closeDashStatModal();

    openTourDetail(entry, {
        returnModalId: 'dash-stat-modal'
    });
});
    });

    // Monats-Drilldown
    bodyEl.querySelectorAll('[data-month-idx]').forEach(el => {
        const mi = parseInt(el.dataset.monthIdx);
        el.style.cursor = 'pointer';
        el.addEventListener('click', () => showDashMonthTours(type, mi, tours, title));
    });

    // Gesamt-Zeile klickbar -> alle Touren/Gipfel sortiert nach Größe
    const totalRowEl = bodyEl.querySelector('#ds-total-row');
    if (totalRowEl) {
        totalRowEl.style.cursor = 'pointer';
        totalRowEl.addEventListener('click', () => showDashAllSorted(type, tours, title));
    }

    const card     = modal.querySelector('.modal-card');
    const backdrop = modal.querySelector('.modal-backdrop');
    if (card)     { card.classList.remove('is-dragging'); card.style.transform = ''; }
    if (backdrop) { backdrop.style.opacity = ''; }

    attachModalSwipeDown(modal, closeDashStatModal);
    modal.classList.remove('hidden');
    document.body.classList.add('modal-open');
}

function showDashPeakTier(
    minH,
    maxH,
    allTours,
    tierTitle,
    backTitle
) {

    const titleEl =
        document.getElementById(
            'ds-title'
        );

    const bodyEl =
        document.getElementById(
            'ds-body'
        );

    if (!titleEl || !bodyEl) {
        return;
    }


    const peakOccurrences = [];


    allTours.forEach(entry => {

        (entry.gipfelDetails || [])
            .forEach(g => {

                const height =
                    parsePeakHeight(
                        g.hoehe
                    );

                if (
                    height >= minH &&
                    (
                        maxH === null ||
                        height <= maxH
                    )
                ) {

                    peakOccurrences.push({
                        name:
                            g.name || '–',

                        rawHoehe:
                            height,

                        entry
                    });
                }
            });
    });


    const peaksList =
        groupPeakOccurrences(
            peakOccurrences
        )
        .sort(
            (a, b) =>
                b.rawHoehe -
                a.rawHoehe
        );


    titleEl.textContent =
        `🏔️ ${tierTitle}`;


    bodyEl.innerHTML = `

        <button
            class="save-btn"
            id="ds-back"
            style="
                margin-bottom:12px;
                padding:5px 14px;
                font-size:13px;
            ">
            ← Zurück
        </button>

        <ul class="stats-list">

            ${
                peaksList.length === 0

                    ? `
                        <li>
                            <span class="stats-label">
                                Keine Gipfel
                            </span>
                        </li>
                      `

                    : peaksList
                        .map(
                            (peak, index) => {

                                const countHtml =
                                    peak.count > 1
                                        ? ` (${peak.count})`
                                        : '';

                                return `

                                    <li
                                        class="
                                            highlight-clickable
                                            ${getPeakTierClass(
                                                peak.rawHoehe
                                            )}
                                        "
                                        data-dash-peak-idx="${index}">

                                        <span class="stats-label">
                                            ${escapeHtml(
                                                peak.name
                                            )}${countHtml}
                                        </span>

                                        <span class="stats-value">
                                            ${peak.rawHoehe} m
                                        </span>

                                    </li>
                                `;
                            }
                        )
                        .join('')
            }

        </ul>
    `;


    document
        .getElementById('ds-back')
        ?.addEventListener(
            'click',
            () => {

                openDashStatModal(
                    'gipfel',
                    allTours
                );
            }
        );


    bodyEl
        .querySelectorAll(
            '[data-dash-peak-idx]'
        )
        .forEach(el => {

            const peak =
                peaksList[
                    Number(
                        el.dataset
                            .dashPeakIdx
                    )
                ];

            if (!peak) return;


            el.addEventListener(
                'click',
                () => {

                    closeDashStatModal();

                    openGroupedPeak(
                        peak,
                        {
                            returnModalId:
                                'dash-stat-modal'
                        }
                    );
                }
            );
        });
}   

function showDashAllSorted(type, allTours, backTitle) {
    const titleEl = document.getElementById('ds-title');
    const bodyEl  = document.getElementById('ds-body');
    if (!titleEl || !bodyEl) return;

    // Gipfel:
    // gleiche Gipfel zusammenfassen
    if (type === 'gipfel') {

        const peakOccurrences = [];

        allTours.forEach(entry => {

            (entry.gipfelDetails || [])
                .forEach(g => {

                    if (
                        g.name ||
                        g.hoehe
                    ) {

                        peakOccurrences.push({
                            name:
                                g.name || '–',

                            rawHoehe:
                                parsePeakHeight(
                                    g.hoehe
                                ),

                            entry
                        });
                    }
                });
        });


        const peaksList =
            groupPeakOccurrences(
                peakOccurrences
            )
            .sort(
                (a, b) =>
                    b.rawHoehe -
                    a.rawHoehe
            );


        titleEl.textContent =
            `${backTitle} · Alle Gipfel`;


        bodyEl.innerHTML = `

            <button
                class="save-btn"
                id="ds-back"
                style="
                    margin-bottom:12px;
                    padding:5px 14px;
                    font-size:13px;
                ">
                ← Zurück
            </button>

            <ul class="stats-list">

                ${
                    peaksList.length === 0

                        ? `
                            <li>
                                <span class="stats-label">
                                    Keine Gipfel
                                </span>
                            </li>
                          `

                        : peaksList
                            .map(
                                (peak, index) => {

                                    const countHtml =
                                        peak.count > 1
                                            ? ` (${peak.count})`
                                            : '';

                                    return `

                                        <li
                                            class="
                                                ${getPeakTierClass(
                                                    peak.rawHoehe
                                                )}
                                                highlight-clickable
                                            "
                                            data-allentry="${index}">

                                            <span class="stats-label">
                                                ${escapeHtml(
                                                    peak.name
                                                )}${countHtml}
                                            </span>

                                            <span class="stats-value">
                                                ${
                                                    peak.rawHoehe > 0
                                                        ? peak.rawHoehe +
                                                          ' m'
                                                        : '–'
                                                }
                                            </span>

                                        </li>
                                    `;
                                }
                            )
                            .join('')
                }

            </ul>
        `;


        document
            .getElementById('ds-back')
            ?.addEventListener(
                'click',
                () => {

                    openDashStatModal(
                        type,
                        allTours
                    );
                }
            );


        bodyEl
            .querySelectorAll(
                '[data-allentry]'
            )
            .forEach(el => {

                const peak =
                    peaksList[
                        Number(
                            el.dataset.allentry
                        )
                    ];

                if (!peak) return;


                el.addEventListener(
                    'click',
                    () => {

                        /*
                         * Dashboard-Modal nur verstecken.
                         * Sein Inhalt bleibt erhalten.
                         */
                        closeDashStatModal();

                        openGroupedPeak(
                            peak,
                            {
                                returnModalId:
                                    'dash-stat-modal'
                            }
                        );
                    }
                );
            });


        return;
    }


    // Sonstige Typen: Mehrtagestouren zusammenfassen, dann nach Größe sortieren
    const seenGroups = new Set();
    const dedupedTours = allTours
        .filter(e => {
            if (type === 'bigTours') return isBigTourCountable(e, allTours);
            return true;
        })
        .filter(e => {
            if (!e.tourGroup) return true;
            if (seenGroups.has(e.tourGroup)) return false;
            seenGroups.add(e.tourGroup);
            return true;
        })
        .map(e => e.tourGroup ? buildMultidaySummaryEntry(e.tourGroup, getTourGroupStages(e.tourGroup, allTours)) : e);

    function metricValue(e) {
    switch (type) {

        case 'touren': {
            const time =
                new Date(e.date).getTime();

            return Number.isFinite(time)
                ? time
                : 0;
        }

                  case 'bigTours':
    return getBigTourIndex(
        e,
        allTours
    );

        case 'aufstieg':
            return parseFloat(
                String(e.aufstieg || '').replace(',', '.')
            ) || 0;

        case 'gehzeit': {
            if (!e.zeit || !e.zeit.includes(':')) return 0;

            const [h, m] = e.zeit.split(':').map(Number);

            return (h * 60 + m) || 0;
        }

        case 'steps':
            return calculateEntrySteps(e);

        default:
            return parseFloat(
                String(e.strecke || '').replace(',', '.')
            ) || 0;
    }
}

    function metricLabel(e) {
    switch (type) {

                    case 'touren':
                            return '';

                    case 'bigTours':
    return 'Index ' +
        Math.round(
            getBigTourIndex(
                e,
                allTours
            )
        );

        case 'aufstieg':
            return e.aufstieg ? e.aufstieg + ' hm' : '–';

        case 'gehzeit':
            return e.zeit ? e.zeit + ' h' : '–';

        case 'steps': {
            const steps = calculateEntrySteps(e);

            return steps > 0
                ? Math.round(steps).toLocaleString('de-AT') +
                    ' Schritte'
                : '–';
        }

        default:
            return e.strecke ? e.strecke + ' km' : '–';
    }
}

    const sorted = [...dedupedTours].sort((a, b) => metricValue(b) - metricValue(a));
    const groupValueType =
    (type === 'aufstieg' ||
     type === 'gehzeit' ||
     type === 'steps')
        ? type
        : 'strecke';

    titleEl.textContent = `${backTitle} · Alle Touren`;
    bodyEl.innerHTML = `
        <button class="save-btn" id="ds-back"
            style="margin-bottom:12px;padding:5px 14px;font-size:13px;">← Zurück</button>
        <ul class="stats-list">
            ${sorted.length === 0
                ? '<li><span class="stats-label">Keine Touren</span><span class="stats-value">–</span></li>'
                : sorted.map((e, i) => `
                    <li class="highlight-clickable" data-allentry="${i}">
                        <span class="stats-label">${e.date || '–'} · ${escapeHtml(e.tourname || 'Unbekannt')}${multidaySummaryBadge(e)}</span>
                        <span class="stats-value">${metricLabel(e)}</span>
                    </li>`).join('')}
        </ul>`;

    document.getElementById('ds-back')?.addEventListener('click', () => openDashStatModal(type, allTours));

    bodyEl.querySelectorAll('[data-allentry]').forEach(el => {
        const idx   = parseInt(el.dataset.allentry);
        const entry = sorted[idx];
        if (!entry) return;
        el.style.cursor = 'pointer';
        el.addEventListener('click', () => {
            closeDashStatModal();
            if (entry._isMultidaySummary) {
    openTourGroupModal(
    entry._tourGroupName,
    'saved',
    groupValueType,
    {
        returnModalId:
            'dash-stat-modal'
    }
);
} else {
    openTourDetail(entry, {
        returnModalId: 'dash-stat-modal'
    });
}
        });
    });
}

function showDashMonthTours(type, mi, allTours, backTitle) {
    const MN      = ['Jän','Feb','Mär','Apr','Mai','Jun','Jul','Aug','Sep','Okt','Nov','Dez'];
    const titleEl = document.getElementById('ds-title');
    const bodyEl  = document.getElementById('ds-body');
    if (!titleEl || !bodyEl) return;

    // ── Gipfel: Peaks des Monats anzeigen ──────────────────────
    if (type === 'gipfel') {

        const peakOccurrences = [];


        allTours.forEach(entry => {

            if (!entry.date) {
                return;
            }

            const date =
                new Date(entry.date);

            if (
                isNaN(date.getTime()) ||
                date.getMonth() !== mi
            ) {
                return;
            }


            (entry.gipfelDetails || [])
                .forEach(g => {

                    if (
                        g.name ||
                        g.hoehe
                    ) {

                        peakOccurrences.push({
                            name:
                                g.name || '–',

                            rawHoehe:
                                parsePeakHeight(
                                    g.hoehe
                                ),

                            entry
                        });
                    }
                });
        });


        const peaksList =
            groupPeakOccurrences(
                peakOccurrences
            )
            .sort(
                (a, b) =>
                    b.rawHoehe -
                    a.rawHoehe
            );


        titleEl.textContent =
            `${backTitle} · ${MN[mi]}`;


        bodyEl.innerHTML = `

            <button
                class="save-btn"
                id="ds-back"
                style="
                    margin-bottom:12px;
                    padding:5px 14px;
                    font-size:13px;
                ">
                ← Zurück
            </button>

            <ul class="stats-list">

                ${
                    peaksList.length === 0

                        ? `
                            <li>
                                <span class="stats-label">
                                    Keine Gipfel
                                </span>
                            </li>
                          `

                        : peaksList
                            .map(
                                (peak, index) => {

                                    const countHtml =
                                        peak.count > 1
                                            ? ` (${peak.count})`
                                            : '';

                                    return `

                                        <li
                                            class="
                                                ${getPeakTierClass(
                                                    peak.rawHoehe
                                                )}
                                                highlight-clickable
                                            "
                                            data-msentry="${index}">

                                            <span class="stats-label">
                                                ${escapeHtml(
                                                    peak.name
                                                )}${countHtml}
                                            </span>

                                            <span class="stats-value">
                                                ${
                                                    peak.rawHoehe > 0
                                                        ? peak.rawHoehe +
                                                          ' m'
                                                        : '–'
                                                }
                                            </span>

                                        </li>
                                    `;
                                }
                            )
                            .join('')
                }

            </ul>
        `;


        document
            .getElementById('ds-back')
            ?.addEventListener(
                'click',
                () => {

                    openDashStatModal(
                        type,
                        allTours
                    );
                }
            );


        bodyEl
            .querySelectorAll(
                '[data-msentry]'
            )
            .forEach(el => {

                const peak =
                    peaksList[
                        Number(
                            el.dataset.msentry
                        )
                    ];

                if (!peak) return;


                el.addEventListener(
                    'click',
                    () => {

                        closeDashStatModal();

                        openGroupedPeak(
                            peak,
                            {
                                returnModalId:
                                    'dash-stat-modal'
                            }
                        );
                    }
                );
            });


        return;
    }

    const seenGroupsForMonth = new Set();
    const monthTours = allTours
        .filter(e => { try { return e.date && new Date(e.date).getMonth() === mi; } catch { return false; } })
        .filter(e => {
            if (type === 'bigTours') return isBigTourCountable(e, allTours);
            if (type === 'touren') return e.tourGroup ? isFirstEtappeInList(e, allTours) : true;
            return true;
        })
        .filter(e => {
            if (!e.tourGroup) return true;
            if (seenGroupsForMonth.has(e.tourGroup)) return false;
            seenGroupsForMonth.add(e.tourGroup);
            return true;
        })
        .map(e =>
    e.tourGroup
        ? buildMultidaySummaryEntry(
            e.tourGroup,
            getTourGroupStages(
                e.tourGroup,
                allTours
            )
        )
        : e
)
.sort((a, b) => {

    /*
     * Alle Touren:
     * neueste Tour zuerst.
     *
     * Andere Dashboard-Drilldowns
     * behalten ihre bisherige
     * Sortierung.
     */
    if (type === 'touren') {
        return (
            new Date(b.date) -
            new Date(a.date)
        );
    }

    if (type === 'bigTours') {
        return (
            getBigTourIndex(b, allTours) -
            getBigTourIndex(a, allTours)
        );
    }

    return (
        new Date(a.date) -
        new Date(b.date)
    );
});

    function tourValue(e) {
        switch (type) {
            case 'aufstieg': return e.aufstieg ? e.aufstieg + ' hm' : '–';
            case 'gehzeit':  return e.zeit     ? e.zeit + ' h'      : '–';
case 'touren':
    return '';

case 'bigTours':
    return 'Index ' +
        Math.round(
            getBigTourIndex(
                e,
                allTours
            )
        );

case 'steps': {
                const steps = calculateEntrySteps(e);

                return steps > 0
                    ? Math.round(steps).toLocaleString('de-AT') +
                        ' Schritte'
                    : '–';
            }
            case 'speed': {
                const d = parseFloat(String(e.strecke || '').replace(',', '.')) || 0;
                if (!e.zeit || !e.zeit.includes(':')) return '–';
                const [h, m] = e.zeit.split(':').map(Number);
                const t = (h * 60 + m) / 60;
                return t > 0
    ? formatDecimalAT(d / t) + ' km/h'
    : '–';
            }
            case 'steigung': {
                const asc  = getAdjustedAscent(e);
                const dist = getAdjustedDistance(e);
                return asc > 0 && dist > 0 ? Math.round(asc / dist) + ' hm/km' : '–';
            }
            case 'anstieg': {
                const asc  = getAdjustedAscent(e);
                const time = getAdjustedTimeHours(e);
                return asc > 0 && time > 0 ? Math.round(asc / time) + ' hm/h' : '–';
            }
            default: return e.strecke ? e.strecke + ' km' : '–';
        }
    }

    titleEl.textContent = `${backTitle} · ${MN[mi]}`;
    bodyEl.innerHTML = `
        <button class="save-btn" id="ds-back"
            style="margin-bottom:12px;padding:5px 14px;font-size:13px;">← Zurück</button>
        <ul class="stats-list">
            ${monthTours.length === 0
                ? '<li><span class="stats-label">Keine Touren</span><span class="stats-value">–</span></li>'
                : monthTours.map((e, i) => `
                    <li class="highlight-clickable" data-msentry="${i}">
                        <span class="stats-label">${e.date || '–'} · ${escapeHtml(e.tourname || 'Unbekannt')}${multidaySummaryBadge(e)}</span>
                        <span class="stats-value">${tourValue(e)}</span>
                    </li>`).join('')}
        </ul>`;

    document.getElementById('ds-back')?.addEventListener('click', () => {
        openDashStatModal(type, allTours);
    });

    bodyEl.querySelectorAll('[data-msentry]').forEach(el => {
    const idx   = parseInt(el.dataset.msentry);
    const entry = monthTours[idx];

    if (!entry) return;

    el.style.cursor = 'pointer';

    el.addEventListener('click', () => {
        closeDashStatModal();

        if (entry._isMultidaySummary) {
            openTourGroupModal(
    entry._tourGroupName,
    'saved',
    type,
    {
        returnModalId:
            'dash-stat-modal'
    }
);
        } else {
            openTourDetail(entry, {
                returnModalId: 'dash-stat-modal'
            });
        }
    });
});
}

// ════════════════════════════════════════════════════════
//  IndexedDB Storage Layer mit Cache
// ════════════════════════════════════════════════════════
const IDB_NAME  = 'BergtorenDB';
const IDB_VER   = 1;
const IDB_STORE = 'keyval';
const STARTUP_IGNORED_STORAGE_KEY = 'preispilot-osttirol-v1';
const TOUR_IMAGE_STORAGE_PREFIX = '~tourImage:';
const TOUR_IMAGE_SPLIT_MARKER = '__tourImagesSplit_v1__';
let   _db       = null;
let   _dbOpenPromise = null;
const _cache    = {};
const tourImageLoadPromises = new Map();
let _storageWriteQueue = Promise.resolve();

function cloneStorageValue(value) {
    if (typeof structuredClone === 'function') {
        try {
            return structuredClone(value);
        } catch (error) {
            console.warn('[Storage] Snapshot fehlgeschlagen:', error);
        }
    }

    return value;
}

function queueStorageWrite(task) {
    _storageWriteQueue =
        _storageWriteQueue
            .catch(() => undefined)
            .then(task)
            .catch(error => {
                console.error('[Storage] Schreibfehler:', error);
            });

    return _storageWriteQueue;
}

function _openDB() {
    if (_db) return Promise.resolve(_db);
    if (_dbOpenPromise) return _dbOpenPromise;

    const attachDatabase = db => {
        _db = db;
        _db.onversionchange = () => {
            _db.close();
            _db = null;
            _dbOpenPromise = null;
            window.__BERGTOUREN_DB_BOOTSTRAP_PROMISE__ = null;
        };
        return db;
    };

    const openRequest = () => new Promise((resolve, reject) => {
        const req = indexedDB.open(IDB_NAME, IDB_VER);
        req.onupgradeneeded = e => {
            if (!e.target.result.objectStoreNames.contains(IDB_STORE))
                e.target.result.createObjectStore(IDB_STORE);
        };
        req.onsuccess = e => resolve(e.target.result);
        req.onerror = e => reject(e.target.error);
    });

    // Wenn index.html die Verbindung schon gestartet hat, deren Promise
    // weiterverwenden, statt beim App-Start ein zweites Mal indexedDB.open aufzurufen.
    const bootstrapPromise = window.__BERGTOUREN_DB_BOOTSTRAP_PROMISE__;
    const sourcePromise = bootstrapPromise && typeof bootstrapPromise.then === 'function'
        ? Promise.resolve(bootstrapPromise).catch(error => {
            console.warn('[Storage] Früher DB-Start fehlgeschlagen; erneuter Versuch:', error);
            return openRequest();
        })
        : openRequest();

    _dbOpenPromise = sourcePromise
        .then(attachDatabase)
        .finally(() => {
            _dbOpenPromise = null;
        });

    return _dbOpenPromise;
}

// Die Verbindung früh öffnen, damit der Datenbankstart bereits während der
// restlichen App-Initialisierung laufen kann. Spätere Aufrufer teilen sich
// dieselbe ausstehende Verbindung; die eigentliche Datenladung bleibt in initStorage().
const _dbOpenWarmupStartedAt = performance.now();
const _dbOpenWarmupPromise = _openDB()
    .then(() => {
        if (APP_PERF_ENABLED) {
            const bootstrapStartedAt = window.__BERGTOUREN_DB_BOOTSTRAP_STARTED_AT__;
            const bootstrapDoneAt = window.__BERGTOUREN_DB_BOOTSTRAP_DONE_AT__;
            const hasBootstrapTiming =
                Number.isFinite(bootstrapStartedAt) &&
                Number.isFinite(bootstrapDoneAt);

            const openDuration = hasBootstrapTiming
                ? bootstrapDoneAt - bootstrapStartedAt
                : performance.now() - _dbOpenWarmupStartedAt;

            appPerfRecord('storage.openDBWarmup', openDuration);

            if (hasBootstrapTiming) {
                console.info(
                    '[PERF] IndexedDB früh bereit nach',
                    bootstrapDoneAt.toFixed(1),
                    'ms; Öffnungsdauer:',
                    openDuration.toFixed(1),
                    'ms'
                );
            }
        }
    })
    .catch(error => {
        console.warn('[Storage] Frühes Öffnen der IndexedDB fehlgeschlagen:', error);
    });
function _idbSet(key, val) {
    return _openDB().then(db => new Promise((res, rej) => {
        const req = db.transaction(IDB_STORE,'readwrite').objectStore(IDB_STORE).put(val, key);
        req.onsuccess = res; req.onerror = () => rej(req.error);
    }));
}
function _idbGet(key) {
    return _openDB().then(db => new Promise((res, rej) => {
        const req = db.transaction(IDB_STORE, 'readonly').objectStore(IDB_STORE).get(key);
        req.onsuccess = () => res(req.result == null ? null : req.result);
        req.onerror = () => rej(req.error);
    }));
}

// Liefert einen speicherbaren Touren-Datensatz ohne eingebettete Bilddaten.
// Tourbilder werden unter stabilen Tour-IDs separat gespeichert.
function prepareTourStorageEntries(tours) {
    const metadataTours = [];
    const imageWrites = [];
    const imageDeletes = [];

    tours.forEach(entry => {
        if (!entry || typeof entry !== 'object') {
            metadataTours.push(entry);
            return;
        }

        const metadata = { ...entry };
        const hasImageProperty = Object.prototype.hasOwnProperty.call(entry, 'imageData');
        const imageData = typeof entry.imageData === 'string' ? entry.imageData : '';
        const id = String(entry.id || '').trim();

        if (hasImageProperty && id) {
            const imageKey = TOUR_IMAGE_STORAGE_PREFIX + id;
            if (imageData) {
                imageWrites.push({ key: imageKey, value: imageData });
                metadata.hasImage = true;
                entry.hasImage = true;
            } else {
                imageDeletes.push(imageKey);
                metadata.hasImage = false;
                entry.hasImage = false;
            }
            delete metadata.imageData;
        } else if (imageData && !id) {
            // Bei unerwarteten Einträgen ohne ID nichts entfernen: Inline-Bild
            // bleibt als sichere Rückfallvariante erhalten.
            metadata.hasImage = true;
            entry.hasImage = true;
        } else {
            metadata.hasImage = Boolean(entry.hasImage);
            if (hasImageProperty && !imageData) {
                delete metadata.imageData;
            }
        }

        metadataTours.push(metadata);
    });

    return { metadataTours, imageWrites, imageDeletes };
}

// Speichert Metadaten, Bildänderungen und Versionsmarker atomar in einer
// IndexedDB-Transaktion. Ein Abbruch lässt den vorherigen Stand intakt.
function _idbWritePreparedTourStorage(prepared) {
    return _openDB().then(db => new Promise((resolve, reject) => {
        const tx = db.transaction(IDB_STORE, 'readwrite');
        const store = tx.objectStore(IDB_STORE);

        store.put(prepared.metadataTours, 'touren');
        prepared.imageWrites.forEach(item => store.put(item.value, item.key));
        prepared.imageDeletes.forEach(key => store.delete(key));
        store.put(true, TOUR_IMAGE_SPLIT_MARKER);

        const fail = () => reject(
            tx.error || new Error('Touren und Tourbilder konnten nicht gemeinsam gespeichert werden.')
        );
        tx.onerror = fail;
        tx.onabort = fail;
        tx.oncomplete = () => resolve(prepared.metadataTours);
    }));
}

async function loadTourImageData(entry) {
    if (!entry || typeof entry !== 'object') return entry;
    if (typeof entry.imageData === 'string' && entry.imageData) return entry;
    if (!entry.hasImage || !entry.id) return entry;

    const id = String(entry.id);
    const key = TOUR_IMAGE_STORAGE_PREFIX + id;
    let imagePromise = tourImageLoadPromises.get(key);

    if (!imagePromise) {
        imagePromise = _idbGet(key)
            .then(value => typeof value === 'string' ? value : '')
            .catch(error => {
                console.warn('[Storage] Tourbild konnte nicht geladen werden:', error);
                return '';
            })
            .finally(() => tourImageLoadPromises.delete(key));
        tourImageLoadPromises.set(key, imagePromise);
    }

    const imageData = await imagePromise;
    if (imageData) {
        entry.imageData = imageData;
        entry.hasImage = true;
    } else {
        entry.hasImage = false;
    }

    return entry;
}

async function loadTourImagesForEntries(entries) {
    const list = Array.isArray(entries) ? entries : [];
    await Promise.all(list.map(entry => loadTourImageData(entry)));
    return list;
}

// Für den getrennten PDF-Magazin-Renderer, der in einer eigenen Datei liegt.
window.loadTourImagesForEntries = loadTourImagesForEntries;

function _idbDel(key) {
    return _openDB().then(db => new Promise((res, rej) => {
        const req = db.transaction(IDB_STORE,'readwrite').objectStore(IDB_STORE).delete(key);
        req.onsuccess = res; req.onerror = () => rej(req.error);
    }));
}
function _idbGetAll() {
    return _openDB().then(db => new Promise((res, rej) => {
        const tx = db.transaction(IDB_STORE, 'readonly');
        const store = tx.objectStore(IDB_STORE);

        // Zwei große Werte werden aus dem kritischen Startpfad ausgelassen:
        // PreisPilot (fremder Datensatz) und die separat gespeicherten Tourbilder.
        // Die Bilddaten bleiben in IndexedDB und werden bei Bedarf nachgeladen.
        const excludedKey = STARTUP_IGNORED_STORAGE_KEY;
        const imagePrefixMax = TOUR_IMAGE_STORAGE_PREFIX + '\\uffff';
        const groups = [
            { range: IDBKeyRange.upperBound(excludedKey, true), keys: null, values: null },
            { range: IDBKeyRange.bound(excludedKey, true, TOUR_IMAGE_STORAGE_PREFIX, true), keys: null, values: null },
            { range: IDBKeyRange.lowerBound(imagePrefixMax, true), keys: null, values: null }
        ];

        const requests = [];
        groups.forEach(group => {
            const keysRequest = store.getAllKeys(group.range);
            const valuesRequest = store.getAll(group.range);
            requests.push(keysRequest, valuesRequest);
            keysRequest.onsuccess = () => { group.keys = keysRequest.result; };
            valuesRequest.onsuccess = () => { group.values = valuesRequest.result; };
        });

        const fail = () => rej(
            tx.error || requests.find(request => request.error)?.error ||
            new Error('IndexedDB konnte die gespeicherten Einträge nicht laden.')
        );
        tx.onerror = fail;
        tx.onabort = fail;
        tx.oncomplete = () => {
            const valid = groups.every(group =>
                Array.isArray(group.keys) &&
                Array.isArray(group.values) &&
                group.keys.length === group.values.length
            );
            if (!valid) {
                rej(new Error('IndexedDB hat Schlüssel und Werte nicht vollständig geliefert.'));
                return;
            }

            // Unterer Schlüsselbereich gefolgt vom oberen Bereich erhält
            // die IndexedDB-Schlüsselreihenfolge und das [{key, value}]-Format.
            res(groups.flatMap(group =>
                group.keys.map((key, index) => ({ key, value: group.values[index] }))
            ));
        };
    }));
}

// ── Öffentliche API — synchron dank Cache ───────────────
const appStorage = {

    get(key) {

        return (
            key in _cache
                ? _cache[key]
                : null
        );
    },


    set(key, val) {

        _cache[key] =
            val;

        if (
            typeof markStorageDependentViewsDirty ===
                'function'
        ) {
            markStorageDependentViewsDirty(key);
        }


        /*
         * Sobald sich die Tourhistorie
         * ändert, ist die bisherige
         * Leistungsindex-Vergleichsbasis
         * nicht mehr gültig.
         */
        if (key === 'touren') {
            if (
                typeof invalidatePerformanceIndexCache ===
                    'function'
            ) {
                invalidatePerformanceIndexCache();
            }

            if (
                typeof invalidateTourDataCaches ===
                    'function'
            ) {
                invalidateTourDataCaches();
            }
        }

        const snapshot =
            cloneStorageValue(val);

        if (key === 'touren' && Array.isArray(snapshot)) {
            // Daten bleiben im synchronen Speicher-Cache wie bisher verfügbar.
            // Persistiert werden jedoch nur Tourmetadaten; Bilder werden separat
            // abgelegt und bei Bedarf für Details, Wrapped, PDF oder Sicherung geladen.
            const prepared = prepareTourStorageEntries(snapshot);
            queueStorageWrite(
                () => _idbWritePreparedTourStorage(prepared)
            );
        } else {
            queueStorageWrite(
                () => _idbSet(key, snapshot)
            );
        }
    },


    remove(key) {

        delete _cache[key];

        if (
            typeof markStorageDependentViewsDirty ===
                'function'
        ) {
            markStorageDependentViewsDirty(key);
        }


        if (key === 'touren') {
            if (
                typeof invalidatePerformanceIndexCache ===
                    'function'
            ) {
                invalidatePerformanceIndexCache();
            }

            if (
                typeof invalidateTourDataCaches ===
                    'function'
            ) {
                invalidateTourDataCaches();
            }
        }

        queueStorageWrite(
            () => _idbDel(key)
        );
    }
};

// ── Einmalige Migration von localStorage ────────────────
async function migrateToIDB() {
    // Wird nur aufgerufen, wenn initStorage() im bereits geladenen
    // IndexedDB-Bestand keinen erfolgreichen Migrationsmarker gefunden hat.
    console.log('[Storage] Migriere localStorage → IndexedDB …');
    const migrationKeys = Object.keys(localStorage);
    let stepStart = APP_PERF_ENABLED ? performance.now() : 0;
    for (const key of migrationKeys) {
        try {
            const raw = localStorage.getItem(key);
            const val = (() => { try { return JSON.parse(raw); } catch { return raw; } })();
            await _idbSet(key, val);
            _cache[key] = val;
        } catch(e) { console.warn('[Storage] Migration fehlgeschlagen:', key, e); }
    }
    if (APP_PERF_ENABLED) {
        appPerfRecord('migrate.copyLocalStorage', performance.now() - stepStart);
        console.info('[PERF] Storage-Migration: lokale Schlüssel:', migrationKeys.length);
    }

    stepStart = APP_PERF_ENABLED ? performance.now() : 0;
    await _idbSet('__migrated__', true);
    _cache['__migrated__'] = true;
    if (APP_PERF_ENABLED) {
        appPerfRecord('migrate.writeMarker', performance.now() - stepStart);
    }
    console.log('[Storage] Migration abgeschlossen.');
    // Nach dem Testen: localStorage.clear();
}

// =========================
// Ripple-Effekt (Mobile Tap)
// =========================
(function () {
    const RIPPLE_SELECTOR = [
        'button.save-btn', '.toggle-btn', '#theme-toggle', '.delete-btn', '.edit-btn', '.load-btn',
        '.chart-tab', '.quick-filter-btn', '.yc-metric-btn', '.yc-year-toggle-btn', '.map-mode-btn',
        '.compare-mode-btn', '.checklist-mode-btn', '.chart-stat-tile',
        '.dash-stat-tile', '.dash-milestone-tile', '.tour-page-btn', '.mob-sel-opt', '.checklist-item',
        '.highlight-clickable', '.peak-tour-list li', '.dash-tour-list li',
        '#saved-tours-list .tour-list li', '#planned-tours-list .tour-list li', '.box-header',
        '.map-popup-btn', '.dash-year-arrow-btn'
    ].join(',');

    function spawnRipple(target, x, y) {
        const rect = target.getBoundingClientRect();
        const size = Math.max(rect.width, rect.height) * 1.8;
        const span = document.createElement('span');
        span.className = 'ripple-el';
        span.style.width = span.style.height = size + 'px';
        span.style.left = (x - rect.left - size / 2) + 'px';
        span.style.top = (y - rect.top - size / 2) + 'px';
        target.appendChild(span);
        requestAnimationFrame(() => span.classList.add('ripple-animate'));
        span.addEventListener('animationend', () => span.remove());
        setTimeout(() => { if (span.parentNode) span.remove(); }, 700);
    }

    function handleTouchStart(e) {
        const target = e.target.closest(RIPPLE_SELECTOR);
        if (!target) return;
        if (target.disabled) return;
        const point = e.touches ? e.touches[0] : e;
        spawnRipple(target, point.clientX, point.clientY);
    }

    if (window.matchMedia('(hover: none)').matches) {
        document.addEventListener('touchstart', handleTouchStart, { passive: true });
    }
})();

// =========================
// Zahlen-Count-Up-Animation
// =========================
(function () {
    const COUNTUP_SELECTOR = '.dash-stat-value, .chart-stat-value';
    const COUNTUP_DURATION = 650; // ms

    function parseNumberFlexible(numStr) {

    /*
     * Locale-Tausenderabstände entfernen:
     * normales Leerzeichen,
     * geschütztes Leerzeichen,
     * schmales geschütztes Leerzeichen.
     */
    let normalized =
        String(numStr)
            .replace(
                /[\s\u00A0\u202F]/g,
                ''
            );

    const hasComma =
        normalized.includes(',');

    const hasDot =
        normalized.includes('.');

    let decimals = 0;

        if (hasComma && hasDot) {
            normalized = numStr.replace(/\./g, '').replace(',', '.');
        } else if (hasComma && !hasDot) {
            normalized = numStr.replace(',', '.');
        } else if (hasDot && !hasComma) {
            const dotCount = (numStr.match(/\./g) || []).length;
            if (dotCount > 1) {
                normalized = numStr.replace(/\./g, '');
            }
        }

        const decMatch = normalized.match(/\.(\d+)$/);
        if (decMatch) decimals = decMatch[1].length;

        return { value: parseFloat(normalized), decimals };
    }

    function easeOutCubic(t) {
        return 1 - Math.pow(1 - t, 3);
    }

    function countUpElement(el) {
        const finalText = el.textContent;
        if (finalText === el.dataset.countUpLast) return;

        // Spezialfall: "HH:MM"-Format (z.B. Gehzeit "102:45")
        const timeMatch = finalText.match(/^(\d+):(\d{2})$/);
        if (timeMatch) {
            el.dataset.countUpLast = finalText;
            el._countUpAnimating = true;

            const targetH = parseInt(timeMatch[1], 10);
            const targetM = parseInt(timeMatch[2], 10);
            const startTime = performance.now();

            const stepTime = function (now) {
                const elapsed = now - startTime;
                const t = Math.min(1, elapsed / COUNTUP_DURATION);
                const eased = easeOutCubic(t);

                const curH = Math.round(targetH * eased);
                const curM = Math.round(targetM * eased);

                el.textContent = curH + ':' + String(curM).padStart(2, '0');

                if (t < 1) {
                    requestAnimationFrame(stepTime);
                } else {
                    el.textContent = finalText;
                    el._countUpAnimating = false;
                }
            };

            requestAnimationFrame(stepTime);
            return;
        }

        const match =
    finalText.match(
        /^(\D*)([\d.,\s\u00A0\u202F]+?)(\D*)$/
    );
        if (!match) {
            el.dataset.countUpLast = finalText;
            return;
        }

        const [, prefix, numStr, suffix] = match;
        const parsed = parseNumberFlexible(numStr);
        if (isNaN(parsed.value)) {
            el.dataset.countUpLast = finalText;
            return;
        }

        el.dataset.countUpLast = finalText;
        el._countUpAnimating = true;

        const target = parsed.value;
        const decimals = parsed.decimals;
        const startTime = performance.now();

        function step(now) {
            const elapsed = now - startTime;
            const t = Math.min(1, elapsed / COUNTUP_DURATION);
            const eased = easeOutCubic(t);
            const current = target * eased;

            el.textContent =
    prefix +
    formatDecimalAT(current, decimals) +
    suffix;

            if (t < 1) {
                requestAnimationFrame(step);
            } else {
                el.textContent = finalText;
                el._countUpAnimating = false;
            }
        }

        requestAnimationFrame(step);
    }

    const countUpObserver = new MutationObserver((mutations) => {
        const candidates = new Set();

        mutations.forEach((m) => {
            let node = m.target;
            if (node.nodeType === Node.TEXT_NODE) node = node.parentElement;
            if (!node || node.nodeType !== 1) return;

            if (node.matches && node.matches(COUNTUP_SELECTOR)) {
                candidates.add(node);
            }
            if (node.querySelectorAll) {
                node.querySelectorAll(COUNTUP_SELECTOR).forEach((el) => candidates.add(el));
            }
        });

       candidates.forEach((el) => {
            if (el._countUpAnimating) return;
            const newText = el.textContent;
            countUpElement(el);
            bounceIconFor(el, newText);
        });
    });

    // Merkt sich Werte anhand eines stabilen Schlüssels (übersteht Neu-Rendering der Kacheln)
    const iconBounceMemory = {};

    function getBounceKey(tile) {
        if (!tile) return null;
        if (tile.dataset && tile.dataset.tileType) return 'tt:' + tile.dataset.tileType;
        if (tile.dataset && tile.dataset.type) return 'dt:' + tile.dataset.type;
        // Fallback: Position innerhalb des Elternelements
        const parent = tile.parentElement;
        if (parent) {
            const idx = Array.prototype.indexOf.call(parent.children, tile);
            return 'pos:' + (parent.id || parent.className) + ':' + idx;
        }
        return null;
    }

    function bounceIconFor(valueEl, newText) {
        const tile = valueEl.closest('.dash-stat-tile, .chart-stat-tile');
        if (!tile) return;

        const key = getBounceKey(tile);
        if (!key) return;

        const prevText = iconBounceMemory[key];
        iconBounceMemory[key] = newText;

        // Nur bouncen, wenn vorher schon ein Wert bekannt war UND er sich geändert hat
        if (prevText === undefined || prevText === newText) return;

        const icon = tile.querySelector('.dash-stat-icon, .chart-stat-icon');
        if (!icon) return;

        icon.classList.remove('icon-bounce');
        void icon.offsetWidth; // Reflow erzwingen, damit Animation neu startet
        icon.classList.add('icon-bounce');
    }

    countUpObserver.observe(document.body, {
        childList: true,
        subtree: true,
        characterData: true
    });
})();

