(function () {
    const starsLayer = document.getElementById('stars-layer');
    if (!starsLayer) return;

    const STAR_COUNT = 70;

    function buildStars() {
        starsLayer.innerHTML = '';
        const frag = document.createDocumentFragment();

        for (let i = 0; i < STAR_COUNT; i++) {
            const star = document.createElement('div');
            star.className = 'star';

            const size = (Math.random() * 1.6 + 0.6).toFixed(2); // 0.6px - 2.2px
            const top = (Math.random() * 70).toFixed(2); // obere 70% des Bildschirms (Bergsilhouette meiden)
            const left = (Math.random() * 100).toFixed(2);
            const duration = (Math.random() * 3 + 2.5).toFixed(2); // 2.5s - 5.5s
            const delay = (Math.random() * 5).toFixed(2);
            const minOpacity = (Math.random() * 0.15 + 0.1).toFixed(2);
            const maxOpacity = (Math.random() * 0.3 + 0.6).toFixed(2);

            star.style.width = size + 'px';
            star.style.height = size + 'px';
            star.style.top = top + '%';
            star.style.left = left + '%';
            star.style.animationDuration = duration + 's';
            star.style.animationDelay = delay + 's';
            star.style.setProperty('--star-min', minOpacity);
            star.style.setProperty('--star-max', maxOpacity);

            frag.appendChild(star);
        }

        starsLayer.appendChild(frag);
    }

    buildStars();
})();

